package hello

import "strconv"

var visits int

func Visit(_ realm) int {
	visits++
	return visits
}

func Render(_ string) string {
	return "# Hello, Gnome Tavern\n\nVisits: " + strconv.Itoa(visits)
}

package hello

import "testing"

func TestVisit(cur realm, t *testing.T) {
	visits = 0
	if got := Visit(cross(cur)); got != 1 {
		t.Fatalf("Visit() = %d, want 1", got)
	}
	if got := Render(""); got != "# Hello, Gnome Tavern\n\nVisits: 1" {
		t.Fatalf("Render() = %q", got)
	}
}

// Tavern Trader — verifiable PAPER-trading agent on Gno.land.
// Single realm, the on-chain source of truth for paper trades.
// NO real funds ever move here: positions are state only, settled in
// paper USD. Prices are micro-USD (1_000_000 = $1.00); sizes are USD cents.
//
// Written against Gno v1.8.0 (Onyx testnet). Note: the old `std`
// package no longer exists in v1.8.0 — realms use the `realm` first
// argument and `cur.Previous().Address()` for the caller (see the
// demo realms in the gno repo, e.g. r/demo/defi/foo20).
//
// Rules enforced on-chain (fail-closed):
//   - a position needs a score >= MinScore (60)
//   - a stop-loss is required, on the correct side of entry
//   - a take-profit is required, on the correct side of entry
//   - per-trade size capped at MaxPositionCents ($50 paper)
//   - at most MaxOpenPositions open at once
//   - cumulative realised paper loss capped at DailyLossCapCents ($20);
//     once breached, no new positions open until the owner resets it
//   - writes (open / close / score / halt) are owner-only: only the
//     deployer key (the agent) may write. Reads are public.
//
// Ownership: the deployer calls ClaimOwner() once, right after deploy
// (init cannot see the deployer). Until claimed, all writes are blocked.
package taverntrader

import "strconv"

// ---------------------------------------------------------------------------
// Constants — the risk policy, visible on-chain.
// ---------------------------------------------------------------------------

const (
	// MinScore is the minimum agent score (0-100) a trade needs.
	MinScore = 60
	// MaxPositionCents caps one paper trade at $50.00.
	MaxPositionCents = 5000
	// DailyLossCapCents caps cumulative realised paper loss at $20.00.
	DailyLossCapCents = 2000
	// MaxOpenPositions caps concurrent open paper positions.
	MaxOpenPositions = 5
)

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

// Position is one paper trade. Status is "open" or "closed".
type Position struct {
	ID         int
	Symbol     string
	Side       string // "long" or "short"
	SizeCents  int64
	EntryPrice int64 // micro-USD
	StopLoss   int64 // micro-USD, required
	TakeProfit int64 // micro-USD, required
	Score      int
	Status     string
	Reason     string
	ClosePrice int64 // micro-USD, 0 while open
	PnLCents   int64 // realised paper P&L in cents, 0 while open
	Seq        int   // monotonic sequence number (ordering, no clock on-chain)
}

// Score is one agent scoring event, kept with its reason.
type Score struct {
	Symbol string
	Score  int
	Reason string
	Seq    int
}

// Decision is the append-only on-chain decision log.
type Decision struct {
	Kind   string // "open", "close", "score", "halt", "resume", "reset-loss", "claim"
	Detail string
	Seq    int
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

var (
	owner            address
	nextID           int
	seq              int
	positions        []Position
	scores           []Score
	decisions        []Decision
	realizedPnLCents int64
	halted           bool
	haltReason       string
)

func init() {
	nextID = 1
	seq = 1
	positions = []Position{}
	scores = []Score{}
	decisions = []Decision{}
}

// ---------------------------------------------------------------------------
// Internal helpers
// ---------------------------------------------------------------------------

func assertOwner(cur realm) {
	if owner == "" {
		panic("taverntrader: owner not claimed yet — deployer must call ClaimOwner first")
	}
	if cur.Previous().Address() != owner {
		panic("taverntrader: caller is not the owner")
	}
}

func nextSeq() int {
	s := seq
	seq++
	return s
}

func logDecision(kind, detail string) {
	decisions = append(decisions, Decision{Kind: kind, Detail: detail, Seq: nextSeq()})
}

func findPosition(id int) int {
	for i, p := range positions {
		if p.ID == id {
			return i
		}
	}
	return -1
}

func openCount() int {
	n := 0
	for _, p := range positions {
		if p.Status == "open" {
			n++
		}
	}
	return n
}

// validateTrade enforces the on-chain risk policy. It panics (fail-closed)
// on the first broken rule, before any state changes.
func validateTrade(symbol, side string, sizeCents, entryPrice, stopLoss, takeProfit int64, score int) {
	if symbol == "" {
		panic("taverntrader: symbol required")
	}
	if side != "long" && side != "short" {
		panic("taverntrader: side must be long or short")
	}
	if score < MinScore {
		panic("taverntrader: score below threshold")
	}
	if entryPrice <= 0 {
		panic("taverntrader: entry price must be positive")
	}
	if stopLoss <= 0 {
		panic("taverntrader: stop-loss required")
	}
	if takeProfit <= 0 {
		panic("taverntrader: take-profit required")
	}
	if side == "long" && stopLoss >= entryPrice {
		panic("taverntrader: long stop-loss must be below entry")
	}
	if side == "short" && stopLoss <= entryPrice {
		panic("taverntrader: short stop-loss must be above entry")
	}
	if side == "long" && takeProfit <= entryPrice {
		panic("taverntrader: long take-profit must be above entry")
	}
	if side == "short" && takeProfit >= entryPrice {
		panic("taverntrader: short take-profit must be below entry")
	}
	if sizeCents <= 0 {
		panic("taverntrader: size must be positive")
	}
	if sizeCents > MaxPositionCents {
		panic("taverntrader: size above per-trade cap")
	}
	if halted {
		panic("taverntrader: trading halted: " + haltReason)
	}
	if openCount() >= MaxOpenPositions {
		panic("taverntrader: too many open positions")
	}
	if realizedPnLCents < -DailyLossCapCents {
		panic("taverntrader: cumulative realised loss cap breached")
	}
}

// openPosition is the state-changing core, shared by the exported
// OpenPaperPosition and the tests.
func openPosition(symbol, side string, sizeCents, entryPrice, stopLoss, takeProfit int64, score int, reason string) int {
	validateTrade(symbol, side, sizeCents, entryPrice, stopLoss, takeProfit, score)
	id := nextID
	nextID++
	positions = append(positions, Position{
		ID: id, Symbol: symbol, Side: side, SizeCents: sizeCents,
		EntryPrice: entryPrice, StopLoss: stopLoss, TakeProfit: takeProfit,
		Score: score, Status: "open", Reason: reason, Seq: nextSeq(),
	})
	logDecision("open", symbol+" "+side+" #"+strconv.Itoa(id)+" score="+strconv.Itoa(score)+" "+reason)
	return id
}

// closePosition settles one open position at closePrice. Returns paper P&L in cents.
func closePosition(id int, closePrice int64, reason string) int64 {
	if closePrice <= 0 {
		panic("taverntrader: close price must be positive")
	}
	i := findPosition(id)
	if i < 0 {
		panic("taverntrader: unknown position")
	}
	if positions[i].Status != "open" {
		panic("taverntrader: position already closed")
	}
	p := &positions[i]
	var pnl int64
	if p.Side == "long" {
		pnl = p.SizeCents * (closePrice - p.EntryPrice) / p.EntryPrice
	} else {
		pnl = p.SizeCents * (p.EntryPrice - closePrice) / p.EntryPrice
	}
	p.Status = "closed"
	p.ClosePrice = closePrice
	p.PnLCents = pnl
	realizedPnLCents += pnl
	logDecision("close", p.Symbol+" "+p.Side+" #"+strconv.Itoa(id)+" pnl="+strconv.FormatInt(pnl, 10)+"c "+reason)
	return pnl
}

// ---------------------------------------------------------------------------
// Writes — owner-only (the agent key).
// ---------------------------------------------------------------------------

// ClaimOwner claims ownership for the caller. Callable exactly once, while
// owner is unset — the deployer calls it right after addpkg.
func ClaimOwner(cur realm) {
	if owner != "" {
		panic("taverntrader: owner already claimed")
	}
	owner = cur.Previous().Address()
	logDecision("claim", "owner claimed: "+string(owner))
}

// OpenPaperPosition opens a paper position. Returns the position id.
func OpenPaperPosition(cur realm, symbol, side string, sizeCents, entryPrice, stopLoss, takeProfit int64, score int, reason string) int {
	validateTrade(symbol, side, sizeCents, entryPrice, stopLoss, takeProfit, score)
	assertOwner(cur)
	return openPosition(symbol, side, sizeCents, entryPrice, stopLoss, takeProfit, score, reason)
}

// ClosePaperPosition closes an open paper position at closePrice.
// Returns realised paper P&L in USD cents.
func ClosePaperPosition(cur realm, id int, closePrice int64, reason string) int64 {
	assertOwner(cur)
	return closePosition(id, closePrice, reason)
}

// RecordScore stores one agent scoring event with its reason.
func RecordScore(cur realm, symbol string, score int, reason string) {
	assertOwner(cur)
	if symbol == "" {
		panic("taverntrader: symbol required")
	}
	if score < 0 || score > 100 {
		panic("taverntrader: score must be 0-100")
	}
	scores = append(scores, Score{Symbol: symbol, Score: score, Reason: reason, Seq: nextSeq()})
	logDecision("score", symbol+" score="+strconv.Itoa(score)+" "+reason)
}

// HaltPaperTrading stops new positions until ResumePaperTrading is called.
func HaltPaperTrading(cur realm, reason string) {
	assertOwner(cur)
	halted = true
	haltReason = reason
	logDecision("halt", reason)
}

// ResumePaperTrading lifts a halt.
func ResumePaperTrading(cur realm) {
	assertOwner(cur)
	halted = false
	haltReason = ""
	logDecision("resume", "trading resumed by owner")
}

// ResetLossCap resets the cumulative realised paper P&L to zero.
// Owner-only, and journaled — it is a deliberate reset, not a silent one.
func ResetLossCap(cur realm, reason string) {
	assertOwner(cur)
	realizedPnLCents = 0
	logDecision("reset-loss", reason)
}

// ---------------------------------------------------------------------------
// Reads — public.
// ---------------------------------------------------------------------------

// GetOwner returns the owner address ("" until ClaimOwner is called).
func GetOwner() address {
	return owner
}

// GetPosition returns one position as a readable line, or "" if unknown.
func GetPosition(id int) string {
	i := findPosition(id)
	if i < 0 {
		return ""
	}
	return formatPosition(positions[i])
}

// GetPositions returns all positions, one per line.
func GetPositions() string {
	out := ""
	for _, p := range positions {
		out += formatPosition(p) + "\n"
	}
	return out
}

// GetOpenPositions returns only open positions, one per line.
func GetOpenPositions() string {
	out := ""
	for _, p := range positions {
		if p.Status == "open" {
			out += formatPosition(p) + "\n"
		}
	}
	return out
}

// GetScores returns scoring events for a symbol, one per line.
func GetScores(symbol string) string {
	out := ""
	for _, s := range scores {
		if s.Symbol == symbol {
			out += symbol + " score=" + strconv.Itoa(s.Score) + " " + s.Reason + "\n"
		}
	}
	return out
}

// GetDecisions returns the on-chain decision log, one per line.
func GetDecisions() string {
	out := ""
	for _, d := range decisions {
		out += strconv.Itoa(d.Seq) + " [" + d.Kind + "] " + d.Detail + "\n"
	}
	return out
}

// GetStats returns a one-line summary: open count, realised P&L (cents), halted.
func GetStats() string {
	return "open=" + strconv.Itoa(openCount()) +
		" positions=" + strconv.Itoa(len(positions)) +
		" realisedPnLCents=" + strconv.FormatInt(realizedPnLCents, 10) +
		" halted=" + strconv.FormatBool(halted)
}

// GetRealizedPnLCents returns cumulative realised paper P&L in USD cents.
func GetRealizedPnLCents() int64 {
	return realizedPnLCents
}

func formatPosition(p Position) string {
	s := "#" + strconv.Itoa(p.ID) + " " + p.Symbol + " " + p.Side +
		" size=" + strconv.FormatInt(p.SizeCents, 10) + "c" +
		" entry=" + strconv.FormatInt(p.EntryPrice, 10) +
		" sl=" + strconv.FormatInt(p.StopLoss, 10) +
		" tp=" + strconv.FormatInt(p.TakeProfit, 10) +
		" score=" + strconv.Itoa(p.Score) +
		" status=" + p.Status +
		" reason=" + p.Reason
	if p.Status == "closed" {
		s += " close=" + strconv.FormatInt(p.ClosePrice, 10) +
			" pnl=" + strconv.FormatInt(p.PnLCents, 10) + "c"
	}
	return s
}

// Render renders the realm page.
func Render(path string) string {
	out := "# Tavern Trader — paper trading on Gno.land\n\n"
	out += "PAPER ONLY. No real funds move here — positions are state only, settled in paper USD.\n\n"
	out += "## Stats\n\n" + GetStats() + "\n\n"
	out += "## Open positions\n\n" + GetOpenPositions() + "\n"
	out += "## All positions\n\n" + GetPositions() + "\n"
	out += "## Decision log\n\n" + GetDecisions()
	return out
}

// Tests for the Tavern Trader realm. Run: gno test ./...
// Test functions take (cur realm, t *testing.T) and call exported realm
// functions through cross(cur), the same way an external caller would.
package taverntrader

import (
	"strings"
	"testing"
)

func mustPanic(t *testing.T, name string, f func()) {
	t.Helper()
	defer func() {
		if r := recover(); r == nil {
			t.Fatalf("%s: expected panic, got none", name)
		}
	}()
	f()
}

func TestClaimOwner(cur realm, t *testing.T) {
	if GetOwner() != "" {
		t.Fatalf("owner should start unclaimed")
	}
	ClaimOwner(cross(cur))
	if GetOwner() == "" {
		t.Fatalf("owner should be set after ClaimOwner")
	}
	// NOTE: a second ClaimOwner call panics ("owner already claimed") by
	// design, but it cannot be asserted here: a panic across a cross-realm
	// call is not recoverable by the caller's recover() in the Gno test VM
	// and aborts the whole test run. The exactly-once rule is enforced in
	// ClaimOwner (tavern.gno) and verified live after deploy instead.
}

func TestOpenAndCloseLong(cur realm, t *testing.T) {
	// $10.00 paper long on BTC at $100.00, close at $110.00 -> +$1.00 (+100c).
	id := OpenPaperPosition(cross(cur), "BTC", "long", 1000, 100_000_000, 90_000_000, 120_000_000, 75, "test long")
	pnl := ClosePaperPosition(cross(cur), id, 110_000_000, "test close")
	if pnl != 100 {
		t.Fatalf("long pnl: got %d cents, want 100", pnl)
	}
	if GetRealizedPnLCents() < 100 {
		t.Fatalf("realised pnl should include the +100c close")
	}
}

func TestOpenAndCloseShort(t *testing.T) {
	// $20.00 paper short on ETH at $50.00, close at $45.00 -> +$2.00 (+200c).
	id := openPosition("ETH", "short", 2000, 50_000_000, 55_000_000, 40_000_000, 80, "test short")
	pnl := closePosition(id, 45_000_000, "test close")
	if pnl != 200 {
		t.Fatalf("short pnl: got %d cents, want 200", pnl)
	}
}

func TestLosingClose(t *testing.T) {
	// $10.00 long on SOL at $100.00, close at $95.00 -> -$0.50 (-50c).
	before := GetRealizedPnLCents()
	id := openPosition("SOL", "long", 1000, 100_000_000, 90_000_000, 120_000_000, 65, "test loss")
	pnl := closePosition(id, 95_000_000, "test loss close")
	if pnl != -50 {
		t.Fatalf("losing pnl: got %d cents, want -50", pnl)
	}
	if GetRealizedPnLCents() != before-50 {
		t.Fatalf("realised pnl not updated by the loss")
	}
}

func TestScoreBelowThresholdBlocked(t *testing.T) {
	// Same rule as OpenPaperPosition's cross-realm path (it calls
	// validateTrade first), tested through validateTrade directly:
	// a cross-realm panic is not recoverable in the Gno test VM.
	mustPanic(t, "score 59", func() {
		validateTrade("BTC", "long", 1000, 100_000_000, 90_000_000, 120_000_000, 59)
	})
}

func TestStopLossRequired(t *testing.T) {
	mustPanic(t, "no stop-loss", func() {
		validateTrade("BTC", "long", 1000, 100_000_000, 0, 120_000_000, 75)
	})
	mustPanic(t, "long stop above entry", func() {
		validateTrade("BTC", "long", 1000, 100_000_000, 110_000_000, 120_000_000, 75)
	})
	mustPanic(t, "short stop below entry", func() {
		validateTrade("BTC", "short", 1000, 100_000_000, 90_000_000, 80_000_000, 75)
	})
}

func TestTakeProfitSideEnforced(t *testing.T) {
	mustPanic(t, "long tp below entry", func() {
		validateTrade("BTC", "long", 1000, 100_000_000, 90_000_000, 90_000_000, 75)
	})
	mustPanic(t, "short tp above entry", func() {
		validateTrade("BTC", "short", 1000, 100_000_000, 110_000_000, 110_000_000, 75)
	})
}

func TestPerTradeCap(t *testing.T) {
	mustPanic(t, "size 5001c above $50 cap", func() {
		validateTrade("BTC", "long", 5001, 100_000_000, 90_000_000, 120_000_000, 75)
	})
	// Exactly at the cap is allowed (if no other rule blocks it).
	validateTrade("BTC", "long", 5000, 100_000_000, 90_000_000, 120_000_000, 75)
}

func TestLossCapBlocksNewOpens(t *testing.T) {
	saved := realizedPnLCents
	realizedPnLCents = -DailyLossCapCents - 1
	mustPanic(t, "loss cap breached", func() {
		validateTrade("BTC", "long", 1000, 100_000_000, 90_000_000, 120_000_000, 75)
	})
	realizedPnLCents = saved
}

func TestDoubleCloseBlocked(t *testing.T) {
	id := openPosition("GNOT", "long", 500, 1_000_000, 900_000, 1_200_000, 70, "test double close")
	closePosition(id, 1_100_000, "first close")
	mustPanic(t, "second close", func() {
		closePosition(id, 1_100_000, "second close")
	})
}

func TestRecordScoreAndGetters(cur realm, t *testing.T) {
	RecordScore(cross(cur), "BTC", 72, "test score")
	if !strings.Contains(GetScores("BTC"), "score=72") {
		t.Fatalf("GetScores missing the recorded score")
	}
	id := OpenPaperPosition(cross(cur), "BTC", "long", 1000, 100_000_000, 90_000_000, 120_000_000, 77, "render check")
	line := GetPosition(id)
	if !strings.Contains(line, "BTC") || !strings.Contains(line, "open") {
		t.Fatalf("GetPosition line missing BTC/open: %q", line)
	}
	if GetPosition(999999) != "" {
		t.Fatalf("GetPosition of unknown id should be empty")
	}
	page := Render("")
	if !strings.Contains(page, "Tavern Trader") || !strings.Contains(page, "PAPER ONLY") {
		t.Fatalf("Render page missing header/PAPER label")
	}
	if !strings.Contains(GetPositions(), "BTC") {
		t.Fatalf("GetPositions missing the open BTC position")
	}
	ClosePaperPosition(cross(cur), id, 105_000_000, "cleanup close")
}

package cairnfold

import (
	"crypto/merkle"
	"encoding/binary"
	"encoding/hex"
	"errors"
	"strconv"
	"strings"
)

// SchemaV1 identifies canonical leaf schema version 1.
const SchemaV1 uint32 = 1

// MaxLeafCount bounds supported epoch roster sizes across encoder, decoder, and CLI.
const MaxLeafCount = 1_000_000

// Verification result codes returned by DecodeProofToken and VerifyToken.
const (
	CodeOK                  = "OK"
	CodeErrDecode           = "ERR_DECODE"
	CodeErrEpochNotFound    = "ERR_EPOCH_NOT_FOUND"
	CodeErrCallerMismatch   = "ERR_CALLER_MISMATCH"
	CodeErrIndexOutOfRange  = "ERR_INDEX_OUT_OF_RANGE"
	CodeErrAlreadyClaimed   = "ERR_ALREADY_CLAIMED"
	CodeErrMerkleProofMatch = "ERR_MERKLE_PROOF_MISMATCH"
)

// Member represents a single canonical roster entry.
type Member struct {
	Addr   address
	Weight uint64
	Role   string
}

// EpochView is the narrow read-only anchor view shared across realms.
type EpochView struct {
	ID               uint64
	Root             []byte
	RootHex          string
	LeafCount        int
	Purpose          string
	SealedHeight     int64
	SnapshotURI      string
	SnapshotVerified bool
	Folded           bool
}

// ProofToken represents a decoded single-string cf1:... claim proof.
type ProofToken struct {
	EpochID  uint64
	Index    int
	Total    int
	Addr     address
	Weight   uint64
	Role     string
	Aunts    []byte
	AuntsHex string
}

// VerifyResult carries a deterministic diagnostic code and explanation.
type VerifyResult struct {
	Code    string
	Message string
}

// OK reports whether verification succeeded.
func (r VerifyResult) OK() bool { return r.Code == CodeOK }

// IsValidRole checks ^[a-z0-9_-]{1,32}$ so delimiters cannot appear in role fields.
func IsValidRole(role string) bool {
	if len(role) == 0 || len(role) > 32 {
		return false
	}
	for i := 0; i < len(role); i++ {
		c := role[i]
		ok := (c >= 'a' && c <= 'z') || (c >= '0' && c <= '9') || c == '_' || c == '-'
		if !ok {
			return false
		}
	}
	return true
}

// IsValidPurpose checks 1..64 printable ASCII bytes excluding '|' and leading/trailing spaces.
func IsValidPurpose(purpose string) bool {
	if len(purpose) == 0 || len(purpose) > 64 {
		return false
	}
	if purpose[0] == ' ' || purpose[len(purpose)-1] == ' ' {
		return false
	}
	for i := 0; i < len(purpose); i++ {
		c := purpose[i]
		if c < 0x20 || c > 0x7e || c == '|' {
			return false
		}
	}
	return true
}

// IsCanonicalAddress checks that addr is a valid lowercase Gno bech32 address ("g1...").
func IsCanonicalAddress(addr address) bool {
	if !addr.IsValid() {
		return false
	}
	s := string(addr)
	if !strings.HasPrefix(s, "g1") {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9')) {
			return false
		}
	}
	return true
}

// EncodeLeaf returns canonical SchemaV1 leaf bytes:
// cairnfold:v1|<epochID>|<addr>|<weight>|<role>
func EncodeLeaf(epochID uint64, addr address, weight uint64, role string) ([]byte, error) {
	if epochID == 0 {
		return nil, errors.New("epochID must be >= 1")
	}
	if !IsCanonicalAddress(addr) {
		return nil, errors.New("invalid canonical lowercase gno address")
	}
	if weight == 0 {
		return nil, errors.New("weight must be >= 1")
	}
	if !IsValidRole(role) {
		return nil, errors.New("invalid role")
	}
	s := "cairnfold:v1|" +
		strconv.FormatUint(epochID, 10) + "|" +
		string(addr) + "|" +
		strconv.FormatUint(weight, 10) + "|" +
		role
	return []byte(s), nil
}

// EncodeByteSlices frames leaves as [4-byte BE count][4-byte BE len_i][leaf_i]...
// matching gnovm/stdlibs/crypto/merkle.HashFromByteSlices.
func EncodeByteSlices(items [][]byte) []byte {
	totalBytes := 4
	for _, it := range items {
		totalBytes += 4 + len(it)
	}
	out := make([]byte, 4, totalBytes)
	binary.BigEndian.PutUint32(out[0:4], uint32(len(items)))
	var lenBuf [4]byte
	for _, it := range items {
		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(it)))
		out = append(out, lenBuf[:]...)
		out = append(out, it...)
	}
	return out
}

// ComputeRoot computes the Tendermint Simple Merkle root over strictly ascending unique members.
func ComputeRoot(epochID uint64, sortedMembers []Member) ([]byte, error) {
	if len(sortedMembers) == 0 {
		return nil, errors.New("empty member list")
	}
	leaves := make([][]byte, len(sortedMembers))
	for i, m := range sortedMembers {
		if i > 0 && string(m.Addr) <= string(sortedMembers[i-1].Addr) {
			return nil, errors.New("members must be strictly sorted by unique address")
		}
		leaf, err := EncodeLeaf(epochID, m.Addr, m.Weight, m.Role)
		if err != nil {
			return nil, err
		}
		leaves[i] = leaf
	}
	root := merkle.HashFromByteSlices(EncodeByteSlices(leaves))
	if len(root) != 32 {
		return nil, errors.New("unexpected merkle root length")
	}
	return root, nil
}

func maxProofDepth(total int) int {
	if total <= 1 {
		return 0
	}
	depth := 0
	for v := total - 1; v > 0; v >>= 1 {
		depth++
	}
	return depth
}

func isCanonicalLowerHex(s string) bool {
	if len(s)%2 != 0 {
		return false
	}
	for i := 0; i < len(s); i++ {
		c := s[i]
		if !((c >= '0' && c <= '9') || (c >= 'a' && c <= 'f')) {
			return false
		}
	}
	return true
}

func validateAunts(total int, aunts []byte) error {
	if total <= 0 {
		return errors.New("total must be >= 1")
	}
	if total == 1 {
		if len(aunts) != 0 {
			return errors.New("single-leaf epoch must have empty aunts")
		}
		return nil
	}
	if len(aunts) == 0 || len(aunts)%32 != 0 {
		return errors.New("aunts byte length must be a positive multiple of 32")
	}
	if len(aunts) > 32*maxProofDepth(total) {
		return errors.New("aunts exceeds maximum tree depth")
	}
	return nil
}

// EncodeProofToken serializes a ProofToken into canonical cf1:... form.
func EncodeProofToken(p ProofToken) (string, error) {
	if p.EpochID == 0 {
		return "", errors.New("epochID must be >= 1")
	}
	if p.Total <= 0 || p.Total > MaxLeafCount || p.Index < 0 || p.Index >= p.Total {
		return "", errors.New("index or total out of allowed range")
	}
	if !IsCanonicalAddress(p.Addr) {
		return "", errors.New("invalid canonical lowercase address")
	}
	if p.Weight == 0 {
		return "", errors.New("weight must be >= 1")
	}
	if !IsValidRole(p.Role) {
		return "", errors.New("invalid role")
	}
	aunts := p.Aunts
	if len(aunts) == 0 && p.AuntsHex != "" {
		if !isCanonicalLowerHex(p.AuntsHex) {
			return "", errors.New("invalid lowercase hex in auntsHex")
		}
		dec, err := hex.DecodeString(p.AuntsHex)
		if err != nil {
			return "", err
		}
		aunts = dec
	}
	if err := validateAunts(p.Total, aunts); err != nil {
		return "", err
	}
	auntsHex := hex.EncodeToString(aunts)
	return "cf1:" +
		strconv.FormatUint(p.EpochID, 10) + ":" +
		strconv.Itoa(p.Index) + ":" +
		strconv.Itoa(p.Total) + ":" +
		string(p.Addr) + ":" +
		strconv.FormatUint(p.Weight, 10) + ":" +
		p.Role + ":" +
		auntsHex, nil
}

func parseCanonicalUint64(raw string) (uint64, bool) {
	if len(raw) == 0 {
		return 0, false
	}
	if len(raw) > 1 && raw[0] == '0' {
		return 0, false
	}
	for i := 0; i < len(raw); i++ {
		if raw[i] < '0' || raw[i] > '9' {
			return 0, false
		}
	}
	v, err := strconv.ParseUint(raw, 10, 64)
	if err != nil {
		return 0, false
	}
	return v, true
}

func parseCanonicalNonNegInt(raw string) (int, bool) {
	v, ok := parseCanonicalUint64(raw)
	if !ok || v > MaxLeafCount {
		return 0, false
	}
	return int(v), true
}

// DecodeProofToken parses and validates a canonical cf1:... proof token.
func DecodeProofToken(raw string) (ProofToken, VerifyResult) {
	parts := strings.Split(raw, ":")
	if len(parts) != 8 || parts[0] != "cf1" {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "token must have 8 ':'-separated parts starting with cf1"}
	}
	epochID, ok := parseCanonicalUint64(parts[1])
	if !ok || epochID == 0 {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "invalid epochID"}
	}
	index, ok := parseCanonicalNonNegInt(parts[2])
	if !ok {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "invalid index"}
	}
	total, ok := parseCanonicalNonNegInt(parts[3])
	if !ok || total <= 0 || index >= total {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "invalid total or index out of bounds"}
	}
	addr := address(parts[4])
	if !IsCanonicalAddress(addr) {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "invalid canonical lowercase gno address"}
	}
	weight, ok := parseCanonicalUint64(parts[5])
	if !ok || weight == 0 {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "invalid weight"}
	}
	role := parts[6]
	if !IsValidRole(role) {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "invalid role"}
	}
	auntsHex := parts[7]
	if !isCanonicalLowerHex(auntsHex) {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "auntsHex must be lowercase hex"}
	}
	aunts, err := hex.DecodeString(auntsHex)
	if err != nil {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: "failed to decode auntsHex"}
	}
	if err := validateAunts(total, aunts); err != nil {
		return ProofToken{}, VerifyResult{Code: CodeErrDecode, Message: err.Error()}
	}
	return ProofToken{
		EpochID:  epochID,
		Index:    index,
		Total:    total,
		Addr:     addr,
		Weight:   weight,
		Role:     role,
		Aunts:    aunts,
		AuntsHex: auntsHex,
	}, VerifyResult{Code: CodeOK, Message: "decoded"}
}

// VerifyToken executes the ordered 6-code verification pipeline shared by gate/v1 and census/v1.
func VerifyToken(raw string, caller address, epoch *EpochView, bitmap []byte) (ProofToken, VerifyResult) {
	tok, decRes := DecodeProofToken(raw)
	if !decRes.OK() {
		return ProofToken{}, decRes
	}
	if epoch == nil || epoch.ID != tok.EpochID || len(epoch.Root) != 32 {
		return tok, VerifyResult{Code: CodeErrEpochNotFound, Message: "epoch anchor not found"}
	}
	if !IsCanonicalAddress(caller) || caller != tok.Addr {
		return tok, VerifyResult{Code: CodeErrCallerMismatch, Message: "caller does not match proof address"}
	}
	if tok.Total != epoch.LeafCount || tok.Index < 0 || tok.Index >= tok.Total {
		return tok, VerifyResult{Code: CodeErrIndexOutOfRange, Message: "proof total/index does not match sealed epoch leaf count"}
	}
	if IsBitSet(bitmap, tok.Index) {
		return tok, VerifyResult{Code: CodeErrAlreadyClaimed, Message: "leaf index already claimed for this epoch"}
	}
	leaf, err := EncodeLeaf(tok.EpochID, tok.Addr, tok.Weight, tok.Role)
	if err != nil {
		return tok, VerifyResult{Code: CodeErrDecode, Message: err.Error()}
	}
	if !merkle.VerifySimpleProof(epoch.Root, leaf, tok.Index, tok.Total, tok.Aunts) {
		return tok, VerifyResult{Code: CodeErrMerkleProofMatch, Message: "tendermint merkle proof verification failed"}
	}
	return tok, VerifyResult{Code: CodeOK, Message: "verified"}
}

// BitmapSize returns ceil(leafCount/8) bytes for compact 1-bit-per-leaf nullifiers
// without signed-integer addition overflow near math.MaxInt.
func BitmapSize(leafCount int) int {
	if leafCount <= 0 {
		return 0
	}
	return (leafCount-1)/8 + 1
}

// IsBitSet reports whether bit index is set in bitmap.
func IsBitSet(bitmap []byte, index int) bool {
	if index < 0 {
		return false
	}
	byteIdx := index / 8
	if byteIdx >= len(bitmap) {
		return false
	}
	return (bitmap[byteIdx] & (1 << uint(index%8))) != 0
}

// SetBit sets bit index in bitmap, returning true if it transitioned 0 -> 1.
func SetBit(bitmap []byte, index int) bool {
	if index < 0 {
		return false
	}
	byteIdx := index / 8
	if byteIdx >= len(bitmap) {
		return false
	}
	mask := byte(1 << uint(index%8))
	if (bitmap[byteIdx] & mask) != 0 {
		return false
	}
	bitmap[byteIdx] |= mask
	return true
}

// Popcount counts total set bits across bitmap.
func Popcount(bitmap []byte) int {
	total := 0
	for _, b := range bitmap {
		for x := b; x != 0; x &= x - 1 {
			total++
		}
	}
	return total
}

// Package commitreveal runs the commit-reveal lifecycle for any sealed choice: a commit window
// in which participants submit only a hash, then a reveal window in which they open it with the
// value and salt. Games with secret picks, sealed-bid auctions and private votes can import it
// instead of writing window checks, hashing and reveal tracking by hand.
//
// A Session holds no coins and no global state. The importing realm stores the session (for
// example inside its own round struct), passes the block time to every call, and decides what
// the revealed values mean: who wins, who pays, who forfeits.
//
//	s := commitreveal.New(now, 3600, 3600)
//	err := s.Commit(now, caller, hash)          // hash = commitreveal.Hash(value, salt), made off-chain
//	err = s.Reveal(now, caller, value, salt)    // in the reveal window
//	for _, o := range s.Revealed() { ... }      // opened values, in commit order
//	late := s.Unrevealed()                      // committed but never opened
package commitreveal

import (
	"crypto/sha256"
	"encoding/hex"
	"errors"

	"gno.land/p/nt/avl/v0"
)

// Phase of a session at a point in time.
type Phase int

const (
	CommitPhase Phase = iota // commits are accepted
	RevealPhase              // reveals are accepted
	ClosedPhase              // both windows are over
)

var (
	ErrCommitClosed     = errors.New("commit window closed")
	ErrBadHash          = errors.New("commit must be 64 hex chars")
	ErrAlreadyCommitted = errors.New("already committed")
	ErrNotRevealWindow  = errors.New("not in reveal window")
	ErrNotCommitted     = errors.New("not a player in this session")
	ErrAlreadyRevealed  = errors.New("already revealed")
	ErrMismatch         = errors.New("reveal does not match commit")
)

// Hash returns hex(sha256("<value>:<salt>")), the value a participant commits.
// Clients compute it off-chain so the value never appears on chain before the reveal.
func Hash(value, salt string) string {
	sum := sha256.Sum256([]byte(value + ":" + salt))
	return hex.EncodeToString(sum[:])
}

// Verify reports whether value and salt open the given commit hash.
func Verify(hash, value, salt string) bool {
	return Hash(value, salt) == hash
}

// Opened is one revealed value.
type Opened struct {
	Who   address
	Value string
}

type entry struct {
	hash     string
	revealed bool
	value    string
}

// Session is one commit-reveal run. Times are Unix seconds (use the block time).
type Session struct {
	CommitEnd int64 // commits are accepted while now < CommitEnd
	RevealEnd int64 // reveals are accepted while CommitEnd <= now < RevealEnd

	order   []address // commit order
	entries *avl.Tree // address -> *entry
}

// New starts a session at now with a commit window and then a reveal window, in seconds.
func New(now, commitSecs, revealSecs int64) *Session {
	if commitSecs <= 0 || revealSecs <= 0 {
		panic("commitreveal: windows must be positive")
	}
	return &Session{
		CommitEnd: now + commitSecs,
		RevealEnd: now + commitSecs + revealSecs,
		entries:   avl.NewTree(),
	}
}

// Phase returns the session's phase at time now.
func (s *Session) Phase(now int64) Phase {
	switch {
	case now < s.CommitEnd:
		return CommitPhase
	case now < s.RevealEnd:
		return RevealPhase
	default:
		return ClosedPhase
	}
}

// Commit records who's hash during the commit window. Each address commits once.
func (s *Session) Commit(now int64, who address, hash string) error {
	if now >= s.CommitEnd {
		return ErrCommitClosed
	}
	if !isHex64(hash) {
		return ErrBadHash
	}
	if s.entries.Has(who.String()) {
		return ErrAlreadyCommitted
	}
	s.entries.Set(who.String(), &entry{hash: hash})
	s.order = append(s.order, who)
	return nil
}

// Reveal opens who's commit with value and salt during the reveal window.
func (s *Session) Reveal(now int64, who address, value, salt string) error {
	if now < s.CommitEnd || now >= s.RevealEnd {
		return ErrNotRevealWindow
	}
	e := s.get(who)
	if e == nil {
		return ErrNotCommitted
	}
	if e.revealed {
		return ErrAlreadyRevealed
	}
	if !Verify(e.hash, value, salt) {
		return ErrMismatch
	}
	e.revealed = true
	e.value = value
	return nil
}

// Has reports whether who has committed.
func (s *Session) Has(who address) bool { return s.entries.Has(who.String()) }

// Count is the number of commits.
func (s *Session) Count() int { return len(s.order) }

// IsRevealed reports whether who has opened their commit.
func (s *Session) IsRevealed(who address) bool {
	e := s.get(who)
	return e != nil && e.revealed
}

// Value returns who's revealed value; ok is false until they reveal.
func (s *Session) Value(who address) (value string, ok bool) {
	e := s.get(who)
	if e == nil || !e.revealed {
		return "", false
	}
	return e.value, true
}

// Players returns every committed address in commit order (a copy).
func (s *Session) Players() []address {
	out := make([]address, len(s.order))
	copy(out, s.order)
	return out
}

// Revealed returns the opened values in commit order.
func (s *Session) Revealed() []Opened {
	var out []Opened
	for _, who := range s.order {
		if e := s.get(who); e.revealed {
			out = append(out, Opened{Who: who, Value: e.value})
		}
	}
	return out
}

// Unrevealed returns the addresses that committed but have not revealed, in commit order.
// After the reveal window these are the participants who forfeited their reveal.
func (s *Session) Unrevealed() []address {
	var out []address
	for _, who := range s.order {
		if !s.get(who).revealed {
			out = append(out, who)
		}
	}
	return out
}

func (s *Session) get(who address) *entry {
	v := s.entries.Get(who.String())
	if v == nil {
		return nil
	}
	return v.(*entry)
}

func isHex64(h string) bool {
	if len(h) != 64 {
		return false
	}
	for _, c := range h {
		if !(c >= '0' && c <= '9' || c >= 'a' && c <= 'f' || c >= 'A' && c <= 'F') {
			return false
		}
	}
	return true
}

// Package avatar draws Taproom's pixel gnomes as SVG: a base gnome picked from the address
// (skin, beard and cap colour) and up to four equipped items layered on top. Any realm can import
// it to show the same gnome a player wears in Taproom.
//
//	svg := avatar.Render(addr, [4]int{107, 201, 0, 403}) // hat, outfit, held item, companion
//	img := "![gnome](" + avatar.DataURI(addr, equipped) + ")" // for Render() markdown
//
// Item IDs are slotBase + n with slotBase 100 hat, 200 outfit, 300 held, 400 companion and
// n = 1..12; 0 means nothing in that slot. Unknown IDs, and IDs in the wrong slot, are ignored.
// The art lives in layers.gno, generated from the web app's layer SVGs.
package avatar

import (
	"encoding/base64"
	"strconv"
	"strings"
)

// alphabet decodes the 4-character runs in layers.gno: x, y, length - 1, colour index.
const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz-_"

// Combo picks one of 8 base gnomes from the address, the same way the web app does:
// h = 7; h = h*31 + byte for each character (uint32); combo = h % 8.
func Combo(addr address) int {
	s := addr.String()
	h := uint32(7)
	for i := 0; i < len(s); i++ {
		h = h*31 + uint32(s[i])
	}
	return int(h % 8)
}

// ValidItem reports whether id is one of the 48 catalogue items.
func ValidItem(id int) bool {
	_, ok := items[id]
	return ok
}

// Render returns a 96 x 96 px SVG (48 x 48 pixel grid) of addr's gnome wearing the equipped items
// (hat, outfit, held, companion). Layers back to front: companion, body, outfit, head, hat or cap, held.
func Render(addr address, equipped [4]int) string {
	c := Combo(addr)
	item := func(slot int) ([2]string, bool) {
		id := equipped[slot]
		it, ok := items[id]
		return it, ok && id/100 == slot+1
	}
	var sb strings.Builder
	sb.WriteString(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48" width="96" height="96" shape-rendering="crispEdges">`)
	if it, ok := item(3); ok {
		sb.WriteString(layerSVG(it[0], it[1]))
	}
	sb.WriteString(layerSVG(bodyPal[c], bodyRuns))
	if it, ok := item(1); ok {
		sb.WriteString(layerSVG(it[0], it[1]))
	}
	sb.WriteString(layerSVG(headPal[c], headRuns))
	if it, ok := item(0); ok {
		sb.WriteString(layerSVG(it[0], it[1]))
	} else {
		sb.WriteString(layerSVG(capPal[c], capRuns))
	}
	if it, ok := item(2); ok {
		sb.WriteString(layerSVG(it[0], it[1]))
	}
	sb.WriteString("</svg>")
	return sb.String()
}

// DataURI returns Render's SVG as a base64 data URI, for an <img> or a markdown image.
func DataURI(addr address, equipped [4]int) string {
	return "data:image/svg+xml;base64," + base64.StdEncoding.EncodeToString([]byte(Render(addr, equipped)))
}

// num holds "0".."64" so drawing a run needs no number formatting.
var num [65]string

func init() {
	for i := range num {
		num[i] = strconv.Itoa(i)
	}
}

// dec decodes one character of the run alphabet.
func dec(b byte) int {
	switch {
	case b == '-':
		return 62
	case b == '_':
		return 63
	case b <= '9':
		return int(b - '0')
	case b <= 'Z':
		return int(b-'A') + 10
	}
	return int(b-'a') + 36
}

// layerSVG draws one layer as a <g> with one path per colour. Each run is a 1 px stroke along the
// middle of its pixel row (M x y.5 h w), which covers exactly the run's pixels with crisp edges.
func layerSVG(palette, runs string) string {
	n := len(palette) / 6
	paths := make([]strings.Builder, n)
	for i := 0; i+3 < len(runs); i += 4 {
		p := &paths[dec(runs[i+3])]
		p.WriteString("M")
		p.WriteString(num[dec(runs[i])])
		p.WriteString(" ")
		p.WriteString(num[dec(runs[i+1])])
		p.WriteString(".5h")
		p.WriteString(num[dec(runs[i+2])+1])
	}
	var sb strings.Builder
	sb.WriteString("<g>")
	for i := 0; i < n; i++ {
		if paths[i].Len() == 0 {
			continue
		}
		sb.WriteString(`<path stroke="#`)
		sb.WriteString(palette[i*6 : i*6+6])
		sb.WriteString(`" d="`)
		sb.WriteString(paths[i].String())
		sb.WriteString(`"/>`)
	}
	sb.WriteString("</g>")
	return sb.String()
}

package taproom

// Leaderboards: net coins, sharpest guesses, longest streak, points and style. Stats are kept on
// each Player, and each board is a sorted index (an avl tree) updated whenever a listed stat moves,
// so reading the top rows costs the same however many players there are.

import (
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

const (
	maxBoardRows = 50
	boardCount   = 5
)

// boards in display order: key, title, column heading.
var boards = [boardCount][3]string{
	{"points", "Points", "Lifetime points"},
	{"net", "Net coins", "Net GNOT"},
	{"sharp", "Sharpest guesses", "Avg distance"},
	{"streak", "Longest streak", "Weeks"},
	{"style", "Style", "Style score"},
}

type boardRow struct {
	addr address
	p    *Player
}

// styleOf sums rarity values of equipped items: common 1, rare 3, epic 6, legendary 10.
func styleOf(equipped [4]int) int64 {
	var s int64
	for _, id := range equipped {
		switch itemPrice(id) {
		case 40:
			s += 1
		case 150:
			s += 3
		case 400:
			s += 6
		case 1000:
			s += 10
		}
	}
	return s
}

// sharp100 is the average distance to the target in hundredths; -1 before any completed round.
func sharp100(p *Player) int64 {
	if p.Scored == 0 {
		return -1
	}
	return p.DistSum100 / p.Scored
}

// boardIdx holds one sorted index per board: boardKey -> address.
var boardIdx = newBoardIdx()

func newBoardIdx() [boardCount]*avl.Tree {
	var t [boardCount]*avl.Tree
	for i := range t {
		t[i] = avl.NewTree()
	}
	return t
}

// boardKey orders a player on board i, best first; ties go by address. ok is false when the
// player is not listed: before their first Join, or on Sharpest guesses before a completed round.
func boardKey(i int, a address, p *Player) (key string, ok bool) {
	if !p.Joined {
		return "", false
	}
	var v int64
	lowerIsBetter := false
	switch boards[i][0] {
	case "points":
		v = p.Lifetime
	case "net":
		v = p.Net
	case "sharp":
		if p.Scored == 0 {
			return "", false
		}
		v, lowerIsBetter = sharp100(p), true
	case "streak":
		v = p.BestStreak
	case "style":
		v = styleOf(p.Equipped)
	}
	k := uint64(v) ^ (1 << 63) // signed order as unsigned order
	if !lowerIsBetter {
		k = ^k
	}
	h := strconv.FormatUint(k, 16)
	for len(h) < 16 {
		h = "0" + h
	}
	return h + ":" + a.String(), true
}

// reindex moves a player's rows in the board indexes after their stats change.
func reindex(a address) {
	p := getPlayer(a)
	for i := 0; i < boardCount; i++ {
		k, ok := boardKey(i, a, p)
		if k == p.boardKeys[i] {
			continue
		}
		if p.boardKeys[i] != "" {
			boardIdx[i].Remove(p.boardKeys[i])
		}
		if ok {
			boardIdx[i].Set(k, a)
		}
		p.boardKeys[i] = k
	}
}

// board returns the top rows of a board, best first.
func board(name string, limit int) []boardRow {
	idx := -1
	for i, b := range boards {
		if b[0] == name {
			idx = i
		}
	}
	if idx < 0 {
		panic("unknown board: use points, net, sharp, streak or style")
	}
	if limit <= 0 || limit > maxBoardRows {
		limit = maxBoardRows
	}
	var rows []boardRow
	boardIdx[idx].Iterate("", "", func(_ string, v any) bool {
		a := v.(address)
		rows = append(rows, boardRow{addr: a, p: players.Get(a.String()).(*Player)})
		return len(rows) >= limit
	})
	return rows
}

// LeaderboardJSON returns the top rows (at most 50) of a board: points, net, sharp, streak or style.
// Each row carries every stat, so one call can fill any column.
func LeaderboardJSON(name string, limit int) string {
	var sb strings.Builder
	sb.WriteString("[")
	for i, r := range board(name, limit) {
		if i > 0 {
			sb.WriteString(",")
		}
		sharp := "null"
		if s := sharp100(r.p); s >= 0 {
			sharp = i64(s)
		}
		sb.WriteString(`{"rank":` + strconv.Itoa(i+1) + `,"addr":"` + r.addr.String() + `","points":` + i64(r.p.Lifetime))
		sb.WriteString(`,"net":` + i64(r.p.Net) + `,"wins":` + i64(r.p.Wins) + `,"sharp100":` + sharp)
		sb.WriteString(`,"bestStreak":` + i64(r.p.BestStreak) + `,"style":` + i64(styleOf(r.p.Equipped)) + `,"equipped":`)
		writeInts(&sb, r.p.Equipped[:])
		sb.WriteString("}")
	}
	sb.WriteString("]")
	return sb.String()
}

package taproom

// Render pages for gnoweb. Avatars are SVG data URIs from the avatar package, which gnoweb
// allows in markdown images. Paths: "" (home), "board/<name>", "player/<address>", "round/<id>".

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/avatar/v0"
)

// boardPageRows caps a board page: each avatar costs about 100M gas, and a Render query may use 3B.
const boardPageRows = 10

var rankNames = []string{"Newcomer", "Regular", "Sharp", "Oracle", "Legend"}
var rankAt = []int64{0, 100, 500, 1500, 4000}

func Render(path string) string {
	parts := strings.Split(strings.Trim(path, "/"), "/")
	switch {
	case path == "":
		return renderHome()
	case len(parts) == 2 && parts[0] == "board":
		return renderBoard(parts[1])
	case len(parts) == 2 && parts[0] == "player":
		return renderPlayer(address(parts[1]))
	case len(parts) == 2 && parts[0] == "round":
		if id, err := strconv.Atoi(parts[1]); err == nil && id >= 0 && id < roundCount {
			return renderRound(getRound(id))
		}
	}
	return "# Not found\n\nNo such page. [Back to the taproom](" + link("") + ")\n"
}

func renderHome() string {
	var sb strings.Builder
	t := now()
	sb.WriteString("# Taproom\n\nA tavern of short mind games. Seal a number from 0 to 100; the pick closest to two thirds of the crowd's average takes the pot. 1 GNOT a seat, 0.5% to the tavern on completed rounds.\n\n")

	sb.WriteString("## Open tables\n\n")
	open := 0
	openRounds.ReverseIterate("", "", func(k string, _ any) bool {
		id, _ := strconv.Atoi(k)
		r := getRound(id)
		open++
		sb.WriteString("- [Round " + strconv.Itoa(r.ID) + "](" + link("round/"+strconv.Itoa(r.ID)) + "): " +
			strconv.Itoa(r.Seal.Count()) + " of " + strconv.Itoa(maxPlayers) + " seats, pot " + gnot(r.Pot) + ", " + phaseLine(r, t) + "\n")
		return open >= 10
	})
	if open == 0 {
		sb.WriteString("No open tables right now.\n")
	}

	sb.WriteString("\n## Recent results\n\n")
	shown := 0
	for i := len(recentSettled) - 1; i >= 0; i-- {
		r := getRound(recentSettled[i])
		shown++
		sb.WriteString("- [Round " + strconv.Itoa(r.ID) + "](" + link("round/"+strconv.Itoa(r.ID)) + "): " + resultLine(r) + "\n")
	}
	if shown == 0 {
		sb.WriteString("No settled rounds yet.\n")
	}

	sb.WriteString("\n## Leaderboards\n\n")
	writeBoardTable(&sb, "points", 5)
	sb.WriteString("\nAll boards:")
	for i, b := range boards {
		if i > 0 {
			sb.WriteString(" ·")
		}
		sb.WriteString(" [" + b[1] + "](" + link("board/"+b[0]) + ")")
	}
	sb.WriteString("\n")
	return sb.String()
}

func renderBoard(name string) string {
	for _, b := range boards {
		if b[0] == name {
			var sb strings.Builder
			sb.WriteString("# " + b[1] + "\n\n")
			writeBoardTable(&sb, name, boardPageRows)
			sb.WriteString("\n[Back to the taproom](" + link("") + ")\n")
			return sb.String()
		}
	}
	// the name comes from the URL, so it is not echoed back into the page
	return "# Not found\n\nNo such board: use points, net, sharp, streak or style. [Back to the taproom](" + link("") + ")\n"
}

func writeBoardTable(sb *strings.Builder, name string, limit int) {
	var col string
	for _, b := range boards {
		if b[0] == name {
			col = b[2]
		}
	}
	rows := board(name, limit)
	if len(rows) == 0 {
		sb.WriteString("Nobody on this board yet.\n")
		return
	}
	sb.WriteString("| # | | Regular | " + col + " |\n|---|---|---|---|\n")
	for i, r := range rows {
		var v string
		switch name {
		case "points":
			v = i64(r.p.Lifetime)
		case "net":
			v = gnot(r.p.Net)
		case "sharp":
			v = hundredths(sharp100(r.p))
		case "streak":
			v = i64(r.p.BestStreak)
		case "style":
			v = i64(styleOf(r.p.Equipped))
		}
		sb.WriteString("| " + strconv.Itoa(i+1) + " | " + gnome(r.addr, r.p.Equipped) + " | [" + short(r.addr) + "](" + link("player/"+r.addr.String()) + ") | " + v + " |\n")
	}
}

func renderPlayer(a address) string {
	v := players.Get(a.String())
	if v == nil {
		return "# Not found\n\nThis address has not played yet. [Back to the taproom](" + link("") + ")\n"
	}
	p := v.(*Player)
	rank := 0
	for i, at := range rankAt {
		if p.Lifetime >= at {
			rank = i
		}
	}
	var sb strings.Builder
	sb.WriteString("# Regular " + short(a) + "\n\n" + gnome(a, p.Equipped) + "\n\n")
	sb.WriteString("- Rank: " + rankNames[rank] + "\n")
	sb.WriteString("- Points: " + i64(p.Lifetime) + " lifetime, " + i64(p.Lifetime-p.Spent) + " to spend\n")
	sb.WriteString("- Weekly streak: " + i64(p.Streak) + " (best " + i64(p.BestStreak) + "), freezes held: " + strconv.Itoa(p.Freezes) + "\n")
	sb.WriteString("- Wins: " + i64(p.Wins) + "\n")
	sb.WriteString("- Net coins: " + gnot(p.Net) + "\n")
	if p.Scored > 0 {
		sb.WriteString("- Average distance to the target: " + hundredths(sharp100(p)) + " over " + i64(p.Scored) + plural(p.Scored, " round", " rounds") + "\n")
	}
	sb.WriteString("- Style score: " + i64(styleOf(p.Equipped)) + "\n\n[Back to the taproom](" + link("") + ")\n")
	return sb.String()
}

func renderRound(r *Round) string {
	var sb strings.Builder
	t := now()
	sb.WriteString("# Round " + strconv.Itoa(r.ID) + "\n\n")
	sb.WriteString(strconv.Itoa(r.Seal.Count()) + " of " + strconv.Itoa(maxPlayers) + " seats, pot " + gnot(r.Pot) + ", " + phaseLine(r, t) + ".\n\n")
	if r.Settled {
		sb.WriteString(resultLine(r) + "\n\n")
		if len(r.Winners) > 0 {
			sum, n := revealedSum(r)
			sb.WriteString("Target: " + hundredths(round2(r.Num*sum*100, r.Den*n)) + " (2/3 of the average " + hundredths(round2(sum*100, n)) + ")\n\n")
		}
	}
	sb.WriteString("| | Regular | Pick | Status |\n|---|---|---|---|\n")
	for _, p := range r.Seal.Players() {
		pick, status := "sealed", "sealed"
		if v := r.Entries.Get(p.String()); v != nil {
			pick = i64(v.(*Entry).Pick)
			status = "revealed"
		}
		if r.Settled {
			switch {
			case isWinner(r, p):
				status = "winner"
			case len(r.Winners) == 0:
				status = "refunded"
			case status == "sealed":
				status = "forfeit"
				pick = "not revealed"
			}
		}
		var equipped [4]int
		if v := players.Get(p.String()); v != nil {
			equipped = v.(*Player).Equipped
		}
		sb.WriteString("| " + gnome(p, equipped) + " | [" + short(p) + "](" + link("player/"+p.String()) + ") | " + pick + " | " + status + " |\n")
	}
	sb.WriteString("\n[Back to the taproom](" + link("") + ")\n")
	return sb.String()
}

// ---------- helpers ----------

func phaseLine(r *Round, t int64) string {
	if r.Settled {
		return "settled"
	}
	switch {
	case t < r.Seal.CommitEnd:
		return "sealing until " + clock(r.Seal.CommitEnd)
	case t < r.Seal.RevealEnd:
		return "revealing until " + clock(r.Seal.RevealEnd)
	}
	return "ready to settle (anyone can settle)"
}

func resultLine(r *Round) string {
	if len(r.Winners) == 0 {
		return "cancelled, fewer than 2 revealed; everyone refunded, no fee"
	}
	var names []string
	for _, w := range r.Winners {
		names = append(names, "["+short(w)+"]("+link("player/"+w.String())+") with "+i64(r.Entries.Get(w.String()).(*Entry).Pick))
	}
	return "won by " + strings.Join(names, " and ") + ", pot " + gnot(r.Pot) + ", fee " + gnot(r.Fee)
}

func revealedSum(r *Round) (sum, n int64) {
	for _, o := range r.Seal.Revealed() {
		sum += r.Entries.Get(o.Who.String()).(*Entry).Pick
		n++
	}
	return sum, n
}

func isWinner(r *Round, a address) bool {
	for _, w := range r.Winners {
		if w == a {
			return true
		}
	}
	return false
}

func gnome(a address, equipped [4]int) string {
	return "![gnome](" + avatar.DataURI(a, equipped) + ")"
}

// link points at a page of this realm in gnoweb.
func link(sub string) string {
	p := "/" + strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), "gno.land/")
	if sub == "" {
		return p
	}
	return p + ":" + sub
}

func short(a address) string {
	s := a.String()
	if len(s) <= 12 {
		return s
	}
	return s[:6] + "…" + s[len(s)-4:]
}

// gnot formats ugnot as GNOT without trailing zeros: 2985000 -> "2.985 GNOT".
func gnot(u int64) string {
	sign := ""
	if u < 0 {
		sign, u = "-", -u
	}
	s := sign + i64(u/1000000)
	if frac := u % 1000000; frac != 0 {
		f := strconv.FormatInt(frac+1000000, 10)[1:]
		s += "." + strings.TrimRight(f, "0")
	}
	return s + " GNOT"
}

// round2 divides num by den rounded to the nearest integer (both positive).
func round2(num, den int64) int64 {
	if den == 0 {
		return 0
	}
	return (num*10/den + 5) / 10
}

// hundredths formats 1778 as "17.78".
func hundredths(h int64) string {
	if h < 0 {
		return "-"
	}
	f := strconv.FormatInt(h%100+100, 10)[1:]
	return i64(h/100) + "." + f
}

func clock(ts int64) string {
	return time.Unix(ts, 0).UTC().Format("Jan 2 15:04 UTC")
}

func plural(n int64, one, many string) string {
	if n == 1 {
		return one
	}
	return many
}

package taproom

// Taproom realm: 2/3 Game round engine with stakes, permissionless settlement, pull payouts,
// and a time-window weekly streak. The commit-reveal lifecycle of each round (windows, sealed
// picks, reveals, who did not reveal) runs on the commitreveal package.

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/commitreveal/v0"
	"gno.land/p/nt/avl/v0"
)

const (
	denom       = "ugnot"
	weekSeconds = int64(604800)
	// Unix time zero fell on a Thursday; 4 days shifts week boundaries to Monday 00:00 UTC.
	weekOffset = int64(345600)

	pointsPlay = int64(10)
	pointsWin  = int64(30)
	streakStep = int64(4)
	streakCap  = int64(20)
	freezeCost = int64(40)
	maxFreezes = 2

	// Caps: players per round, open rounds per creator, window bounds.
	maxPlayers    = 10
	maxOpenRounds = 3
	minWindow     = int64(60)
	maxWindow     = int64(86400)

	// Cosmetic slots: hat, outfit, held item, companion (Player.Equipped order).
	slotCount = 4

	// Board skins: 0 = Oak table (free, owned by everyone), 1 = Moonlit, 2 = Gold-trim.
	skinCount = 3

	// Target fraction of the average: fixed at 2/3 in the MVP, stored per round.
	entryFee = int64(1000000) // 1 GNOT per seat

	// Salts shorter than this let anyone guess a pick from its hash (there are only 101 picks).
	minSaltLen = 16
	maxSaltLen = 128 // salts are kept and shown in RoundJSON, so they stay short and printable

	targetNum = int64(2)
	targetDen = int64(3)

	// Protocol fee in basis points (50 = 0.5%), taken from the pot of a completed round only.
	feeBps   = int64(50)
	bpsTotal = int64(10000)
)

// skinPrice is the points price per board skin ID; Oak (0) is free.
var skinPrice = []int64{0, 150, 400}

var (
	feeRecipient address // set once at deploy; can only withdraw accrued fees
	feesAccrued  int64
)

func init() {
	feeRecipient = unsafe.OriginCaller()
}

// nowOverride lets tests control time; zero means use the block time.
var nowOverride int64

// Entry is what the realm keeps for a revealed pick; the commit itself lives in the round's Seal.
type Entry struct {
	Pick  int64
	Salt  string // public once revealed, so anyone can re-check the commit
	Bonus int64  // streak bonus earned at reveal; paid only if the round completes
}

type Round struct {
	ID        int
	Creator   address
	Start     int64
	Seal      *commitreveal.Session // windows, commits, reveals and join order
	Entries   *avl.Tree             // address -> *Entry, for revealed players
	Commits   *avl.Tree             // address -> commit hash, kept for RoundJSON so anyone can re-check reveals
	Settled   bool
	Pot       int64
	Fee       int64
	Winners   []address
	BoardSkin int
	Num, Den  int64 // target fraction of the average; 2/3 in the MVP
}

type Player struct {
	Lifetime  int64
	Spent     int64
	HasPlayed bool
	LastWeek  int64
	Streak    int64
	Freezes   int
	Skins     []int  // owned board skins other than the free Oak table
	Owned     []int  // cosmetic item IDs
	Equipped  [4]int // item ID per slot (hat, outfit, held, companion); 0 = nothing

	// Leaderboard stats, updated at Join and Settle.
	Net        int64 // ugnot credited minus entry fees paid
	Wins       int64 // completed rounds won (a split win counts)
	Scored     int64 // revealed picks in completed rounds
	DistSum100 int64 // sum of distances to the target in those rounds, in hundredths
	BestStreak int64 // longest weekly streak reached

	Joined    bool               // has joined a round; only such players are listed on boards
	boardKeys [boardCount]string // this player's key in each board index; "" = not listed
}

var (
	roundTree     = avl.NewTree() // roundKey(id) -> *Round
	roundCount    int
	openRounds    = avl.NewTree() // roundKey(id) -> true while the round is not settled
	openByCreator = avl.NewTree() // address -> int, open rounds per creator (the 3-round cap)
	recentSettled []int           // the last 5 settled round IDs, oldest first
	players       = avl.NewTree() // address -> *Player
	claimable     = avl.NewTree() // address -> int64
)

// roundKey pads round IDs so the tree keeps them in numeric order.
func roundKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

func openCount(a address) int {
	if v := openByCreator.Get(a.String()); v != nil {
		return v.(int)
	}
	return 0
}

// visibleASCII reports whether s has only printable ASCII characters other than space.
func visibleASCII(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] < 0x21 || s[i] > 0x7e {
			return false
		}
	}
	return true
}

func now() int64 {
	if nowOverride != 0 {
		return nowOverride
	}
	return time.Now().Unix()
}

// weekIndex returns the Monday-00:00-UTC-aligned week number of a Unix timestamp.
func weekIndex(ts int64) int64 {
	d := ts - weekOffset
	w := d / weekSeconds
	if d%weekSeconds < 0 {
		w--
	}
	return w
}

// CommitHash is the value a player submits when joining round roundID:
// hex(sha256("<roundID>:<player address>:<pick>:<salt>")). Binding the round and the player means
// a hash copied from someone else's Join cannot be opened by the copier, nor reused in another round.
func CommitHash(roundID int, player address, pick int64, salt string) string {
	return commitreveal.Hash(sealedValue(roundID, player, pick), salt)
}

// sealedValue is what a round's Seal commits to for a player's pick.
func sealedValue(roundID int, player address, pick int64) string {
	return strconv.Itoa(roundID) + ":" + player.String() + ":" + strconv.FormatInt(pick, 10)
}

func mustUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("direct user call required")
	}
	return cur.Previous().Address()
}

func getRound(id int) *Round {
	if id < 0 || id >= roundCount {
		panic("unknown round")
	}
	return roundTree.Get(roundKey(id)).(*Round)
}

func getPlayer(a address) *Player {
	v := players.Get(a.String())
	if v == nil {
		p := &Player{}
		players.Set(a.String(), p)
		return p
	}
	return v.(*Player)
}

func credit(a address, amt int64) {
	cur := int64(0)
	if v := claimable.Get(a.String()); v != nil {
		cur = v.(int64)
	}
	claimable.Set(a.String(), cur+amt)
	getPlayer(a).Net += amt
}

// ownsSkin reports whether a may use a board skin: Oak (0) is free for everyone.
func ownsSkin(a address, skin int) bool {
	if skin == 0 {
		return true
	}
	v := players.Get(a.String())
	if v == nil {
		return false
	}
	for _, s := range v.(*Player).Skins {
		if s == skin {
			return true
		}
	}
	return false
}

// NewRound opens a round. commitSecs and revealSecs are window lengths in seconds.
// The creator must own boardSkin (Oak table, ID 0, is owned by everyone).
func NewRound(cur realm, commitSecs, revealSecs int64, boardSkin int) int {
	creator := mustUser(cur)
	if commitSecs < minWindow || revealSecs < minWindow || commitSecs > maxWindow || revealSecs > maxWindow {
		panic("windows must be 1 minute to 24 hours")
	}
	if boardSkin < 0 || boardSkin >= skinCount {
		panic("unknown board skin")
	}
	if !ownsSkin(creator, boardSkin) {
		panic("creator does not own this board skin")
	}
	open := openCount(creator)
	if open >= maxOpenRounds {
		panic("you already have 3 open rounds")
	}
	t := now()
	r := &Round{
		ID:        roundCount,
		Creator:   creator,
		Start:     t,
		Seal:      commitreveal.New(t, commitSecs, revealSecs),
		Entries:   avl.NewTree(),
		Commits:   avl.NewTree(),
		BoardSkin: boardSkin,
		Num:       targetNum,
		Den:       targetDen,
	}
	roundTree.Set(roundKey(r.ID), r)
	roundCount++
	openRounds.Set(roundKey(r.ID), true)
	openByCreator.Set(creator.String(), open+1)
	return r.ID
}

// Join deposits the entry fee and stores a hidden pick.
func Join(cur realm, roundID int, commit string) {
	caller := mustUser(cur)
	r := getRound(roundID)
	t := now()
	if r.Seal.Phase(t) != commitreveal.CommitPhase {
		panic("commit window closed")
	}
	if r.Seal.Has(caller) {
		panic("already joined")
	}
	if r.Seal.Count() >= maxPlayers {
		panic("round is full")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != denom || sent[0].Amount != entryFee {
		panic("must send exactly the entry fee in ugnot")
	}
	if err := r.Seal.Commit(t, caller, commit); err != nil {
		panic(err.Error())
	}
	r.Commits.Set(caller.String(), commit)
	r.Pot += entryFee
	pl := getPlayer(caller)
	pl.Net -= entryFee
	pl.Joined = true
	reindex(caller)
}

// Reveal opens the pick; it must match the commit. It moves the streak (in block-time order)
// and records the bonus; points are paid at Settle, and only if the round completes.
func Reveal(cur realm, roundID int, pick int64, salt string) {
	caller := mustUser(cur)
	r := getRound(roundID)
	t := now()
	if pick < 0 || pick > 100 {
		panic("pick must be 0..100")
	}
	if len(salt) < minSaltLen || len(salt) > maxSaltLen || !visibleASCII(salt) {
		panic("salt must be 16 to 128 visible ASCII characters")
	}
	if err := r.Seal.Reveal(t, caller, sealedValue(roundID, caller, pick), salt); err != nil {
		panic(err.Error())
	}
	r.Entries.Set(caller.String(), &Entry{Pick: pick, Salt: salt, Bonus: updateStreak(caller, t)})
	reindex(caller)
}

// Settle can be called by anyone once the reveal window has closed.
func Settle(cur realm, roundID int) {
	r := getRound(roundID)
	if now() < r.Seal.RevealEnd {
		panic("reveal window still open")
	}
	if r.Settled {
		panic("already settled")
	}
	r.Settled = true // effects before any payout bookkeeping
	openRounds.Remove(roundKey(r.ID))
	openByCreator.Set(r.Creator.String(), openCount(r.Creator)-1)
	recentSettled = append(recentSettled, r.ID)
	if len(recentSettled) > 5 {
		recentSettled = recentSettled[len(recentSettled)-5:]
	}
	defer func() { // board positions move with the credits and points below
		for _, p := range r.Seal.Players() {
			reindex(p)
		}
	}()

	var revealers []address
	var sum int64
	for _, o := range r.Seal.Revealed() { // join order
		revealers = append(revealers, o.Who)
		sum += r.Entries.Get(o.Who.String()).(*Entry).Pick
	}
	n := int64(len(revealers))

	// Fewer than two reveals: void round, everyone is refunded. No points.
	if n < 2 {
		for _, p := range r.Seal.Players() {
			credit(p, entryFee)
		}
		return
	}

	// Completed round: every revealer gets play points plus the bonus recorded at reveal.
	for _, p := range revealers {
		getPlayer(p).Lifetime += pointsPlay + r.Entries.Get(p.String()).(*Entry).Bonus
	}

	// Winner is closest to num/den of the average: minimise |den*n*pick - num*sum| (integer math).
	best := int64(-1)
	var winners []address
	for _, p := range revealers {
		e := r.Entries.Get(p.String()).(*Entry)
		d := r.Den*n*e.Pick - r.Num*sum
		if d < 0 {
			d = -d
		}
		// distance to the target = d / (den*n); kept in hundredths for the Sharpest guesses board
		pl := getPlayer(p)
		pl.Scored++
		pl.DistSum100 += (d*200 + r.Den*n) / (2 * r.Den * n) // rounded to the nearest hundredth
		if best < 0 || d < best {
			best = d
			winners = []address{p}
		} else if d == best {
			winners = append(winners, p)
		}
	}

	// Completed round (at least two reveals): take the fee, split the rest.
	fee := r.Pot * feeBps / bpsTotal
	r.Fee = fee
	feesAccrued += fee
	prize := r.Pot - fee

	count := int64(len(winners))
	share := prize / count
	rem := prize - share*count
	for i, w := range winners {
		amt := share
		if i == 0 {
			amt += rem
		}
		credit(w, amt)
		getPlayer(w).Lifetime += pointsWin - pointsPlay
		getPlayer(w).Wins++
	}
	r.Winners = winners
}

// Claim pays out the caller's balance (pull payment).
func Claim(cur realm) {
	caller := mustUser(cur)
	v := claimable.Get(caller.String())
	if v == nil || v.(int64) <= 0 {
		panic("nothing to claim")
	}
	amt := v.(int64)
	claimable.Set(caller.String(), int64(0)) // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

// WithdrawFees sends accrued protocol fees to the fee recipient. It touches nothing else.
func WithdrawFees(cur realm) {
	caller := mustUser(cur)
	if caller != feeRecipient {
		panic("only the fee recipient can withdraw fees")
	}
	amt := feesAccrued
	if amt <= 0 {
		panic("no fees to withdraw")
	}
	feesAccrued = 0 // effects before interaction
	bnk := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	bnk.SendCoins(cur.Address(), caller, chain.NewCoins(chain.NewCoin(denom, amt)))
}

// updateStreak moves the weekly streak for a play at ts and returns that play's bonus.
// Calls arrive in block-time order because Reveal calls it.
func updateStreak(a address, ts int64) int64 {
	p := getPlayer(a)
	w := weekIndex(ts)
	if !p.HasPlayed {
		p.Streak = 1
		p.LastWeek = w
	} else {
		g := w - p.LastWeek
		if g >= 1 {
			if p.Streak == 0 {
				// the streak was already reset for missed weeks: start again, keep any freezes
				p.Streak = 1
			} else if g == 1 {
				p.Streak++
			} else {
				missed := int(g - 1)
				if p.Freezes >= missed {
					p.Freezes -= missed
					p.Streak++
				} else {
					// not enough freezes: the streak resets and every held freeze is used up
					p.Streak = 1
					p.Freezes = 0
				}
			}
			p.LastWeek = w
		}
	}
	if p.Streak > p.BestStreak {
		p.BestStreak = p.Streak
	}
	p.HasPlayed = true
	bonus := streakStep * p.Streak
	if bonus > streakCap {
		bonus = streakCap
	}
	return bonus
}

// applyMissedWeeks spends freezes on weeks already missed before week w, as the next Reveal would.
// With too few freezes the streak drops to 0 and every freeze is used up; the next play starts week 1.
func applyMissedWeeks(p *Player, w int64) {
	if !p.HasPlayed || p.Streak == 0 {
		return
	}
	missed := int(w - p.LastWeek - 1)
	if missed <= 0 {
		return
	}
	if p.Freezes >= missed {
		p.Freezes -= missed
	} else {
		p.Streak = 0
		p.Freezes = 0
	}
	p.LastWeek = w - 1
}

// BuyFreeze spends points on a streak freeze (max 2 held). Weeks already missed are applied first,
// so a new freeze cannot cover a past week and a stale count cannot block the purchase.
func BuyFreeze(cur realm) {
	caller := mustUser(cur)
	p := getPlayer(caller)
	applyMissedWeeks(p, weekIndex(now()))
	if p.Freezes >= maxFreezes {
		panic("freeze limit reached")
	}
	if p.Lifetime-p.Spent < freezeCost {
		panic("not enough points")
	}
	p.Spent += freezeCost
	p.Freezes++
}

// BuySkin spends points on a board skin (Moonlit or Gold-trim). Oak is free and always owned.
func BuySkin(cur realm, skin int) {
	caller := mustUser(cur)
	if skin <= 0 || skin >= skinCount {
		panic("unknown or free board skin")
	}
	if ownsSkin(caller, skin) {
		panic("skin already owned")
	}
	p := getPlayer(caller)
	price := skinPrice[skin]
	if p.Lifetime-p.Spent < price {
		panic("not enough points")
	}
	p.Spent += price
	p.Skins = append(p.Skins, skin)
}

// itemPrice returns the points price of a cosmetic item, or -1 for an unknown ID.
// itemID = slotBase + n with slotBase 100 hat, 200 outfit, 300 held, 400 companion and n = 1..12.
// Rarity by n: 1, 5, 6 common 40; 2, 7, 8 rare 150; 3, 9, 10 epic 400; 4, 11, 12 legendary 1000.
func itemPrice(id int) int64 {
	slot, n := id/100, id%100
	if slot < 1 || slot > slotCount || n < 1 || n > 12 {
		return -1
	}
	switch n {
	case 1, 5, 6:
		return 40
	case 2, 7, 8:
		return 150
	case 3, 9, 10:
		return 400
	}
	return 1000
}

func ownsItem(p *Player, id int) bool {
	for _, o := range p.Owned {
		if o == id {
			return true
		}
	}
	return false
}

// BuyItem spends points on a cosmetic item. Items cannot be traded and never affect outcomes.
func BuyItem(cur realm, itemID int) {
	caller := mustUser(cur)
	price := itemPrice(itemID)
	if price < 0 {
		panic("unknown item")
	}
	p := getPlayer(caller)
	if ownsItem(p, itemID) {
		panic("item already owned")
	}
	if p.Lifetime-p.Spent < price {
		panic("not enough points")
	}
	p.Spent += price
	p.Owned = append(p.Owned, itemID)
}

// Equip wears an owned item in its slot (0 hat, 1 outfit, 2 held, 3 companion); itemID 0 takes it off.
func Equip(cur realm, slot int, itemID int) {
	caller := mustUser(cur)
	if slot < 0 || slot >= slotCount {
		panic("unknown slot")
	}
	p := getPlayer(caller)
	if itemID != 0 {
		if !ownsItem(p, itemID) {
			panic("item not owned")
		}
		if itemID/100 != slot+1 {
			panic("item does not fit this slot")
		}
	}
	p.Equipped[slot] = itemID
	reindex(caller)
}

// Views (non-crossing)

func OwnsSkin(a address, skin int) bool { return ownsSkin(a, skin) }

func Claimable(a address) int64 {
	if v := claimable.Get(a.String()); v != nil {
		return v.(int64)
	}
	return 0
}

func PlayerStats(a address) (lifetime, spendable, streak int64, freezes int) {
	v := players.Get(a.String())
	if v == nil {
		return 0, 0, 0, 0
	}
	p := v.(*Player)
	return p.Lifetime, p.Lifetime - p.Spent, p.Streak, p.Freezes
}

package taproom

// Read-only views for the web UI, returned as compact JSON strings so a client can read them
// with one vm/qeval call. Addresses are bech32 and numbers are plain integers, so no escaping is needed.

import (
	"strconv"
	"strings"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/avatar/v0"
)

func RoundCount() int { return roundCount }

// AvatarSVG draws a player's gnome wearing their equipped items (see the avatar package).
func AvatarSVG(a address) string {
	var equipped [4]int
	if v := players.Get(a.String()); v != nil {
		equipped = v.(*Player).Equipped
	}
	return avatar.Render(a, equipped)
}

func FeeRecipient() address { return feeRecipient }

func FeesAccrued() int64 { return feesAccrued }

// RoundsJSON returns rounds [offset, offset+limit) as a JSON array (limit capped at 100).
func RoundsJSON(offset, limit int) string {
	if limit > 100 {
		limit = 100
	}
	var sb strings.Builder
	sb.WriteString("[")
	for i := offset; i >= 0 && i < roundCount && i < offset+limit; i++ {
		if i > offset {
			sb.WriteString(",")
		}
		writeRound(&sb, getRound(i))
	}
	sb.WriteString("]")
	return sb.String()
}

func RoundJSON(id int) string {
	var sb strings.Builder
	writeRound(&sb, getRound(id))
	return sb.String()
}

// PlayerJSON reports a player as the next Reveal would see them: weeks already missed are applied
// to a copy (freezes spent, or the streak shown as 0). It never changes state.
func PlayerJSON(a address) string {
	p := Player{}
	if v := players.Get(a.String()); v != nil {
		p = *v.(*Player)
	}
	applyMissedWeeks(&p, weekIndex(now()))

	var sb strings.Builder
	sb.WriteString(`{"addr":"` + a.String() + `","lifetime":` + i64(p.Lifetime) + `,"spent":` + i64(p.Spent))
	sb.WriteString(`,"streak":` + i64(p.Streak) + `,"lastWeek":`)
	if p.HasPlayed {
		sb.WriteString(i64(p.LastWeek))
	} else {
		sb.WriteString("null")
	}
	sb.WriteString(`,"freezes":` + strconv.Itoa(p.Freezes) + `,"owned":`)
	writeInts(&sb, p.Owned)
	sb.WriteString(`,"equipped":`)
	writeInts(&sb, p.Equipped[:])
	sb.WriteString(`,"skins":`)
	writeInts(&sb, append([]int{0}, p.Skins...))
	sb.WriteString(`,"claimable":` + i64(Claimable(a)) + "}")
	return sb.String()
}

func writeRound(sb *strings.Builder, r *Round) {
	sb.WriteString(`{"id":` + strconv.Itoa(r.ID) + `,"creator":"` + r.Creator.String() + `","skin":` + strconv.Itoa(r.BoardSkin))
	sb.WriteString(`,"start":` + i64(r.Start) + `,"commitEnd":` + i64(r.Seal.CommitEnd) + `,"revealEnd":` + i64(r.Seal.RevealEnd))
	sb.WriteString(`,"num":` + i64(r.Num) + `,"den":` + i64(r.Den) + `,"settled":` + strconv.FormatBool(r.Settled))
	sb.WriteString(`,"pot":` + i64(r.Pot) + `,"fee":` + i64(r.Fee) + `,"winners":[`)
	for i, w := range r.Winners {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(`"` + w.String() + `"`)
	}
	sb.WriteString(`],"entries":[`)
	for i, p := range r.Seal.Players() {
		if i > 0 {
			sb.WriteString(",")
		}
		// a pick and its salt stay hidden until their owner reveals them
		pick, salt, bonus := "null", "null", int64(0)
		if v := r.Entries.Get(p.String()); v != nil {
			e := v.(*Entry)
			pick, salt, bonus = i64(e.Pick), strconv.Quote(e.Salt), e.Bonus
		}
		commit, _ := r.Commits.Get(p.String()).(string)
		sb.WriteString(`{"addr":"` + p.String() + `","commit":"` + commit + `","revealed":` + strconv.FormatBool(r.Seal.IsRevealed(p)))
		sb.WriteString(`,"pick":` + pick + `,"salt":` + salt + `,"bonus":` + i64(bonus) + "}")
	}
	sb.WriteString("]}")
}

func writeInts(sb *strings.Builder, xs []int) {
	sb.WriteString("[")
	for i, x := range xs {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(strconv.Itoa(x))
	}
	sb.WriteString("]")
}

func i64(x int64) string { return strconv.FormatInt(x, 10) }

// Package sealedpoll runs sealed polls: anyone opens a question with 2 to 8 options, voters
// seal a choice (only its hash goes on chain), then open it in the reveal window. The tally
// counts opened votes only, and the realm reports how many sealed votes were never opened.
//
// It is a second realm built on the commitreveal package: the session handles the windows,
// one vote per address, reveal checks and who never opened. This realm holds no coins.
package sealedpoll

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/g1vxsg6ht4nklaud70yaszcgkhc9ttancr9nlzzq/commitreveal/v0"
	"gno.land/p/nt/avl/v0"
)

const (
	maxOptions     = 8
	maxQuestionLen = 140
	maxOptionLen   = 40
	minWindow      = int64(60)     // 1 minute
	maxWindow      = int64(604800) // 7 days
	minSaltLen     = 16            // shorter salts let anyone guess a vote from its hash
	pageSize       = 10            // polls per Render page
)

type Poll struct {
	ID       int
	Creator  address
	Question string
	Options  []string
	Seal     *commitreveal.Session
}

var (
	polls     = avl.NewTree() // pollKey(id) -> *Poll
	pollCount int
)

// pollKey pads poll IDs so the tree keeps them in numeric order.
func pollKey(id int) string {
	s := strconv.Itoa(id)
	for len(s) < 10 {
		s = "0" + s
	}
	return s
}

// mustUser returns the caller, who must be a wallet calling directly (not another realm or a script).
func mustUser(cur realm) address {
	if !cur.Previous().IsUserCall() {
		panic("direct user call required")
	}
	return cur.Previous().Address()
}

// nowOverride lets tests control time; zero means use the block time.
var nowOverride int64

func now() int64 {
	if nowOverride != 0 {
		return nowOverride
	}
	return time.Now().Unix()
}

// NewPoll opens a poll. options is a comma-separated list of 2 to 8 distinct choices (no ':', which
// separates the option from the salt in a vote's hash); commitSecs and revealSecs are the voting and
// opening windows in seconds, each 1 minute to 7 days.
func NewPoll(cur realm, question, options string, commitSecs, revealSecs int64) int {
	creator := mustUser(cur)
	if commitSecs < minWindow || revealSecs < minWindow || commitSecs > maxWindow || revealSecs > maxWindow {
		panic("windows must be 1 minute to 7 days")
	}
	question = strings.TrimSpace(question)
	if question == "" || len(question) > maxQuestionLen || !printable(question) {
		panic("question must be 1 to 140 printable characters")
	}
	var opts []string
	for _, o := range strings.Split(options, ",") {
		o = strings.TrimSpace(o)
		if o == "" || len(o) > maxOptionLen || !printable(o) || strings.Contains(o, ":") {
			panic("each option must be 1 to 40 printable characters, without ':'")
		}
		for _, seen := range opts {
			if seen == o {
				panic("options must be different")
			}
		}
		opts = append(opts, o)
	}
	if len(opts) < 2 || len(opts) > maxOptions {
		panic("a poll needs 2 to 8 options")
	}
	p := &Poll{
		ID:       pollCount,
		Creator:  creator,
		Question: question,
		Options:  opts,
		Seal:     commitreveal.New(now(), commitSecs, revealSecs),
	}
	polls.Set(pollKey(p.ID), p)
	pollCount++
	return p.ID
}

// Vote seals a choice: hash is commitreveal.Hash(option, salt), computed by the voter's client.
func Vote(cur realm, id int, hash string) {
	voter := mustUser(cur)
	p := getPoll(id)
	if err := p.Seal.Commit(now(), voter, hash); err != nil {
		panic(voteError(err))
	}
}

// Open reveals a sealed vote with its option and salt during the opening window. The salt must be
// at least 16 characters; voters' clients should use a random one.
func Open(cur realm, id int, option, salt string) {
	voter := mustUser(cur)
	p := getPoll(id)
	if !p.hasOption(option) {
		panic("unknown option")
	}
	if len(salt) < minSaltLen {
		panic("salt must be at least 16 characters")
	}
	if err := p.Seal.Reveal(now(), voter, option, salt); err != nil {
		panic(voteError(err))
	}
}

// PollCount is the number of polls.
func PollCount() int { return pollCount }

// Tally returns a poll's state as JSON: phase (vote, open or closed), sealed votes, opened votes,
// counts per option in option order, and votes sealed but never opened.
func Tally(id int) string {
	p := getPoll(id)
	counts := p.counts()
	opened := p.Seal.Revealed()
	var sb strings.Builder
	sb.WriteString(`{"id":` + strconv.Itoa(p.ID) + `,"question":` + strconv.Quote(p.Question))
	sb.WriteString(`,"phase":"` + phaseName(p.Seal.Phase(now())) + `","votes":` + strconv.Itoa(p.Seal.Count()))
	sb.WriteString(`,"opened":` + strconv.Itoa(len(opened)) + `,"counts":{`)
	for i, o := range p.Options {
		if i > 0 {
			sb.WriteString(",")
		}
		sb.WriteString(strconv.Quote(o) + ":" + strconv.Itoa(counts[i]))
	}
	sb.WriteString(`},"unopened":` + strconv.Itoa(p.Seal.Count()-len(opened)) + "}")
	return sb.String()
}

// Render lists polls newest first, 10 per page ("" is page 1, "page/2" the next); counts appear
// once votes start opening. Poll text is escaped, so it cannot add links or headings to the page.
func Render(path string) string {
	page := 1
	if strings.HasPrefix(path, "page/") {
		n, err := strconv.Atoi(strings.TrimPrefix(path, "page/"))
		if err != nil || n < 1 {
			return "# Not found\n"
		}
		page = n
	}
	var sb strings.Builder
	sb.WriteString("# Sealed polls\n\nVotes stay sealed until their owners open them. Built on commitreveal.\n\n")
	if pollCount == 0 {
		sb.WriteString("No polls yet.\n")
		return sb.String()
	}
	t := now()
	first := pollCount - 1 - (page-1)*pageSize
	for i := first; i >= 0 && i > first-pageSize; i-- {
		p := getPoll(i)
		phase := p.Seal.Phase(t)
		opened := len(p.Seal.Revealed())
		sb.WriteString("## " + strconv.Itoa(p.ID) + ". " + escape(p.Question) + "\n\n")
		switch phase {
		case commitreveal.CommitPhase:
			sb.WriteString("Voting is open: " + strconv.Itoa(p.Seal.Count()) + " sealed votes. Options: " + escape(strings.Join(p.Options, ", ")) + ".\n\n")
			continue
		case commitreveal.RevealPhase:
			sb.WriteString("Opening votes: " + strconv.Itoa(opened) + " of " + strconv.Itoa(p.Seal.Count()) + " opened so far.\n\n")
		default:
			sb.WriteString("Closed: " + strconv.Itoa(p.Seal.Count()) + " sealed votes, " + strconv.Itoa(opened) + " opened.\n\n")
		}
		for j, c := range p.counts() {
			sb.WriteString("- " + escape(p.Options[j]) + ": " + strconv.Itoa(c) + "\n")
		}
		if phase == commitreveal.ClosedPhase {
			if n := p.Seal.Count() - opened; n > 0 {
				noun := "votes"
				if n == 1 {
					noun = "vote"
				}
				sb.WriteString("\n" + strconv.Itoa(n) + " sealed " + noun + " never opened.\n")
			}
		}
		sb.WriteString("\n")
	}
	if first < 0 {
		sb.WriteString("No polls on this page.\n")
	}
	if first-pageSize >= 0 {
		sb.WriteString("[Older polls](" + link("page/"+strconv.Itoa(page+1)) + ")\n")
	}
	return sb.String()
}

// link points at a page of this realm in gnoweb.
func link(sub string) string {
	return "/" + strings.TrimPrefix(unsafe.CurrentRealm().PkgPath(), "gno.land/") + ":" + sub
}

// escape backslash-escapes markdown punctuation so user text shows as typed.
func escape(s string) string {
	var sb strings.Builder
	for _, r := range s {
		if strings.ContainsRune("\\`*_{}[]()<>#+-.!|~", r) {
			sb.WriteByte('\\')
		}
		sb.WriteRune(r)
	}
	return sb.String()
}

func getPoll(id int) *Poll {
	if id < 0 || id >= pollCount {
		panic("unknown poll")
	}
	return polls.Get(pollKey(id)).(*Poll)
}

func (p *Poll) hasOption(o string) bool {
	for _, x := range p.Options {
		if x == o {
			return true
		}
	}
	return false
}

// counts returns opened votes per option, in option order.
func (p *Poll) counts() []int {
	counts := make([]int, len(p.Options))
	for _, o := range p.Seal.Revealed() {
		for i, x := range p.Options {
			if x == o.Value {
				counts[i]++
			}
		}
	}
	return counts
}

// voteError words the session's errors for voters.
func voteError(err error) string {
	switch err {
	case commitreveal.ErrCommitClosed:
		return "voting is closed"
	case commitreveal.ErrAlreadyCommitted:
		return "already voted"
	case commitreveal.ErrNotCommitted:
		return "you did not vote in this poll"
	case commitreveal.ErrAlreadyRevealed:
		return "already opened"
	}
	return err.Error()
}

func phaseName(ph commitreveal.Phase) string {
	switch ph {
	case commitreveal.CommitPhase:
		return "vote"
	case commitreveal.RevealPhase:
		return "open"
	}
	return "closed"
}

// printable rejects invalid UTF-8 and control characters, so Tally's JSON stays valid.
func printable(s string) bool {
	if !utf8.ValidString(s) {
		return false
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return false
		}
	}
	return true
}

package census

import (
	"chain"
	"chain/runtime"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/g1st947gecd43mklw0l87x5f9x3a6fxen9m3hnu0/cairnfold/v1"
	"gno.land/p/nt/avl/v0"
)

const (
	StageOpen           = "OPEN"
	StageFrozenSnapshot = "FROZEN_SNAPSHOT"
)

// DefaultOwner is the Onyx testnet operator address that deploys and funds roster storage deposits.
const DefaultOwner = address("g1st947gecd43mklw0l87x5f9x3a6fxen9m3hnu0")

const (
	maxBatchSize      = 200
	maxSnapshotURILen = 256
)

type epochRecord struct {
	id               uint64
	root             []byte
	leafCount        int
	purpose          string
	sealedHeight     int64
	snapshotURI      string
	snapshotVerified bool
	folded           bool
}

var (
	owner        = DefaultOwner
	activeRoster = avl.NewTree()
	epochs       []*epochRecord
)

func frozenEpoch() *epochRecord {
	if len(epochs) == 0 {
		return nil
	}
	last := epochs[len(epochs)-1]
	if last.folded {
		return nil
	}
	return last
}

func assertOwner(cur realm) {
	prev := cur.Previous()
	if prev.PkgPath() != "" || prev.Address() != owner {
		panic("ERR_UNAUTHORIZED: caller is not census owner")
	}
}

func assertOpen() {
	if frozenEpoch() != nil {
		panic("ERR_STAGE_FROZEN: roster is frozen awaiting verified fold")
	}
}

func isValidSnapshotURI(uri string) bool {
	if !strings.HasPrefix(uri, "https://") || len(uri) <= len("https://") || len(uri) > maxSnapshotURILen {
		return false
	}
	for i := 0; i < len(uri); i++ {
		c := uri[i]
		if c <= 0x20 || c > 0x7e || c == ')' || c == ']' || c == '<' || c == '>' {
			return false
		}
	}
	return true
}

func epochToView(ep *epochRecord) cairnfold.EpochView {
	rootCopy := make([]byte, len(ep.root))
	copy(rootCopy, ep.root)
	return cairnfold.EpochView{
		ID:               ep.id,
		Root:             rootCopy,
		RootHex:          hex.EncodeToString(ep.root),
		LeafCount:        ep.leafCount,
		Purpose:          ep.purpose,
		SealedHeight:     ep.sealedHeight,
		SnapshotURI:      ep.snapshotURI,
		SnapshotVerified: ep.snapshotVerified,
		Folded:           ep.folded,
	}
}

func Owner() address { return owner }

func Stage() string {
	if frozenEpoch() != nil {
		return StageFrozenSnapshot
	}
	return StageOpen
}

func ActiveRosterSize() int { return activeRoster.Size() }

func EpochCount() uint64 { return uint64(len(epochs)) }

// UpsertMember inserts or updates a single member in the draft AVL roster while OPEN.
func UpsertMember(cur realm, addr address, weight uint64, role string) {
	assertOwner(cur)
	assertOpen()
	if !cairnfold.IsCanonicalAddress(addr) {
		panic("ERR_INVALID_MEMBER: invalid canonical lowercase gno address")
	}
	if weight == 0 {
		panic("ERR_INVALID_MEMBER: weight must be >= 1")
	}
	if !cairnfold.IsValidRole(role) {
		panic("ERR_INVALID_MEMBER: invalid role")
	}
	activeRoster.Set(string(addr), cairnfold.Member{
		Addr:   addr,
		Weight: weight,
		Role:   role,
	})
}

// RemoveMember removes a member from the draft AVL roster while OPEN.
func RemoveMember(cur realm, addr address) bool {
	assertOwner(cur)
	assertOpen()
	if !cairnfold.IsCanonicalAddress(addr) {
		panic("ERR_INVALID_MEMBER: invalid canonical lowercase gno address")
	}
	_, removed := activeRoster.Remove(string(addr))
	return removed
}

// SeedRosterBatch atomically validates and upserts up to 200 "addr,weight,role" lines while OPEN.
func SeedRosterBatch(cur realm, csvLines string) int {
	assertOwner(cur)
	assertOpen()
	rawLines := strings.Split(strings.ReplaceAll(csvLines, "\r\n", "\n"), "\n")
	parsed := make([]cairnfold.Member, 0, len(rawLines))
	for _, ln := range rawLines {
		ln = strings.TrimSpace(ln)
		if ln == "" {
			continue
		}
		parts := strings.Split(ln, ",")
		if len(parts) != 3 {
			panic("ERR_INVALID_BATCH: each line must be addr,weight,role")
		}
		addr := address(strings.TrimSpace(parts[0]))
		w, err := strconv.ParseUint(strings.TrimSpace(parts[1]), 10, 64)
		if err != nil || w == 0 {
			panic("ERR_INVALID_BATCH: invalid weight")
		}
		role := strings.TrimSpace(parts[2])
		if !cairnfold.IsCanonicalAddress(addr) || !cairnfold.IsValidRole(role) {
			panic("ERR_INVALID_BATCH: invalid address or role")
		}
		parsed = append(parsed, cairnfold.Member{Addr: addr, Weight: w, Role: role})
		if len(parsed) > maxBatchSize {
			panic("ERR_INVALID_BATCH: batch exceeds 200 entries")
		}
	}
	if len(parsed) == 0 {
		panic("ERR_INVALID_BATCH: empty batch")
	}
	for _, m := range parsed {
		activeRoster.Set(string(m.Addr), m)
	}
	return len(parsed)
}

// SealEpoch computes the Tendermint Merkle root over the sorted AVL roster, appends an immutable
// epoch anchor, and locks edits in FROZEN_SNAPSHOT until verified and folded.
func SealEpoch(cur realm, purpose string) uint64 {
	assertOwner(cur)
	assertOpen()
	if activeRoster.Size() == 0 {
		panic("ERR_EMPTY_ROSTER: cannot seal an empty roster")
	}
	if activeRoster.Size() > cairnfold.MaxLeafCount {
		panic("ERR_ROSTER_TOO_LARGE: roster exceeds MaxLeafCount")
	}
	if !cairnfold.IsValidPurpose(purpose) {
		panic("ERR_INVALID_PURPOSE: purpose must be 1..64 printable ASCII chars without '|' or outer spaces")
	}
	nextID := uint64(len(epochs)) + 1
	members := make([]cairnfold.Member, 0, activeRoster.Size())
	var sumWeight uint64
	activeRoster.Iterate("", "", func(_ string, v interface{}) bool {
		m := v.(cairnfold.Member)
		if sumWeight > ^uint64(0)-m.Weight {
			panic("ERR_WEIGHT_OVERFLOW: sum of epoch weights exceeds uint64")
		}
		sumWeight += m.Weight
		members = append(members, m)
		return false
	})
	root, err := cairnfold.ComputeRoot(nextID, members)
	if err != nil {
		panic("ERR_SEAL_FAILED: " + err.Error())
	}
	rootHex := hex.EncodeToString(root)
	height := runtime.ChainHeight()
	ep := &epochRecord{
		id:           nextID,
		root:         root,
		leafCount:    len(members),
		purpose:      purpose,
		sealedHeight: height,
	}
	epochs = append(epochs, ep)
	chain.Emit(
		"EpochSealed",
		"epoch_id", strconv.FormatUint(nextID, 10),
		"root_hex", rootHex,
		"leaf_count", strconv.Itoa(len(members)),
		"sealed_height", strconv.FormatInt(height, 10),
	)
	return nextID
}

// ExportCanonicalSnapshot outputs canonical CSV rows while FROZEN_SNAPSHOT, or SnapshotURI guidance afterward.
func ExportCanonicalSnapshot(epochID uint64) string {
	if epochID == 0 || epochID > uint64(len(epochs)) {
		return "ERR_EPOCH_NOT_FOUND"
	}
	ep := epochs[epochID-1]
	rootHex := hex.EncodeToString(ep.root)
	if frozen := frozenEpoch(); frozen != nil && frozen.id == epochID {
		var sb strings.Builder
		sb.WriteString("# epoch_id=" + strconv.FormatUint(ep.id, 10) +
			",schema_id=1,leaf_count=" + strconv.Itoa(ep.leafCount) +
			",root_hex=" + rootHex +
			",purpose=" + ep.purpose + "\n")
		sb.WriteString("index,addr,weight,role\n")
		idx := 0
		activeRoster.Iterate("", "", func(_ string, v interface{}) bool {
			m := v.(cairnfold.Member)
			sb.WriteString(strconv.Itoa(idx) + "," +
				string(m.Addr) + "," +
				strconv.FormatUint(m.Weight, 10) + "," +
				m.Role + "\n")
			idx++
			return false
		})
		return sb.String()
	}
	return "FOLDED: canonical snapshot archived at " + ep.snapshotURI + " (root_hex=" + rootHex + ")"
}

// ConfirmSnapshotVerified verifies an off-chain-rebuilt canary cf1:... proof on-chain against the
// sealed epoch anchor before unlocking FoldRoster.
func ConfirmSnapshotVerified(cur realm, epochID uint64, snapshotURI string, canaryToken string) {
	assertOwner(cur)
	ep := frozenEpoch()
	if ep == nil || ep.id != epochID {
		panic("ERR_NOT_FROZEN: epoch is not currently frozen awaiting fold")
	}
	if !isValidSnapshotURI(snapshotURI) {
		panic("ERR_INVALID_URI: snapshotURI must be a valid https:// URL")
	}
	tok, decRes := cairnfold.DecodeProofToken(canaryToken)
	if !decRes.OK() {
		panic("ERR_CANARY_INVALID: " + decRes.Code + ": " + decRes.Message)
	}
	view := epochToView(ep)
	if _, res := cairnfold.VerifyToken(canaryToken, tok.Addr, &view, nil); !res.OK() {
		panic("ERR_CANARY_INVALID: " + res.Code + ": " + res.Message)
	}
	ep.snapshotURI = snapshotURI
	ep.snapshotVerified = true
	chain.Emit(
		"SnapshotVerified",
		"epoch_id", strconv.FormatUint(epochID, 10),
		"snapshot_uri", snapshotURI,
		"canary_index", strconv.Itoa(tok.Index),
	)
}

// FoldRoster deletes every entry from activeRoster after snapshot verification to release GnoVM
// storage deposits (100 ugnot/byte) and returns the realm to OPEN for the next epoch.
func FoldRoster(cur realm, epochID uint64) int {
	assertOwner(cur)
	ep := frozenEpoch()
	if ep == nil || ep.id != epochID {
		panic("ERR_NOT_FROZEN: epoch is not currently frozen awaiting fold")
	}
	if !ep.snapshotVerified || ep.snapshotURI == "" {
		panic("ERR_SNAPSHOT_UNVERIFIED: call ConfirmSnapshotVerified before FoldRoster")
	}
	keys := make([]string, 0, activeRoster.Size())
	activeRoster.Iterate("", "", func(k string, _ interface{}) bool {
		keys = append(keys, k)
		return false
	})
	for _, k := range keys {
		activeRoster.Remove(k)
	}
	activeRoster = avl.NewTree()
	ep.folded = true
	chain.Emit(
		"RosterFolded",
		"epoch_id", strconv.FormatUint(epochID, 10),
		"removed", strconv.Itoa(len(keys)),
		"remaining", "0",
	)
	return len(keys)
}

// GetEpoch returns a defensive read-only EpochView for downstream consumer realms.
func GetEpoch(epochID uint64) (cairnfold.EpochView, bool) {
	if epochID == 0 || epochID > uint64(len(epochs)) {
		return cairnfold.EpochView{}, false
	}
	return epochToView(epochs[epochID-1]), true
}

func modeBanner() string {
	cid := runtime.ChainID()
	if cid == "" || cid == "dev" {
		return "MODE: DETERMINISTIC_REPLAY (`chain_id=" + cid + "`, local dev/test)"
	}
	return "MODE: LIVE (`chain_id=" + cid + "`, `height=" + strconv.FormatInt(runtime.ChainHeight(), 10) + "`)"
}

func escapeMDCell(s string) string {
	s = strings.ReplaceAll(s, "|", "/")
	s = strings.ReplaceAll(s, "\n", " ")
	return s
}

func Render(_ string) string {
	var sb strings.Builder
	sb.WriteString("# CairnFold — Epoch Census Producer (`census/v1`)\n\n")
	sb.WriteString("> " + modeBanner() + " | Stage: `" + Stage() + "` | Active AVL Entries: `" + strconv.Itoa(activeRoster.Size()) + "` | Sealed Epochs: `" + strconv.Itoa(len(epochs)) + "`\n\n")
	sb.WriteString("Seal on-chain AVL rosters into immutable Tendermint Merkle roots (`crypto/merkle`), verify an off-chain canonical snapshot canary, and call `FoldRoster` to release `100 ugnot/byte` GnoVM storage deposits while downstream `gate/v1` keeps historical epochs claimable.\n\n")
	sb.WriteString("<gno-button href=\"/r/" + string(owner) + "/gate/v1\" label=\"Open Claim Gate (gate/v1)\" variant=\"success\" />\n\n")

	sb.WriteString("## Sealed Epochs\n\n")
	if len(epochs) == 0 {
		sb.WriteString("_No epochs sealed yet._\n\n")
	} else {
		sb.WriteString("| Epoch | Purpose | Leaves | Root (16 hex) | Height | Snapshot | Roster Folded |\n")
		sb.WriteString("| --- | --- | ---: | --- | ---: | --- | --- |\n")
		for _, ep := range epochs {
			shortRoot := hex.EncodeToString(ep.root)
			if len(shortRoot) > 16 {
				shortRoot = shortRoot[:16] + "..."
			}
			snapCell := "pending"
			if ep.snapshotURI != "" {
				snapCell = "[snapshot](" + ep.snapshotURI + ")"
			}
			foldedCell := "no (AVL live)"
			if ep.folded {
				foldedCell = "YES (AVL cleared)"
			}
			sb.WriteString("| " + strconv.FormatUint(ep.id, 10) +
				" | " + escapeMDCell(ep.purpose) +
				" | " + strconv.Itoa(ep.leafCount) +
				" | `" + shortRoot + "`" +
				" | " + strconv.FormatInt(ep.sealedHeight, 10) +
				" | " + snapCell +
				" | " + foldedCell + " |\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## Storage Audit Commands (`onyx-1`)\n\n")
	sb.WriteString("```sh\n")
	sb.WriteString("gnokey query vm/qstorage -data \"gno.land/r/" + string(owner) + "/census/v1\" -remote https://rpc.onyx.testnets.gno.land:443\n")
	sb.WriteString("gnokey query vm/qeval -data \"gno.land/r/" + string(owner) + "/census/v1.ExportCanonicalSnapshot(1)\" -remote https://rpc.onyx.testnets.gno.land:443\n")
	sb.WriteString("```\n")
	return sb.String()
}

package gate

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"

	"gno.land/p/g1st947gecd43mklw0l87x5f9x3a6fxen9m3hnu0/cairnfold/v1"
	"gno.land/p/nt/avl/v0"
	"gno.land/r/g1st947gecd43mklw0l87x5f9x3a6fxen9m3hnu0/census/v1"
)

// ClaimStats summarizes compact bitmap redemption accounting for an epoch.
type ClaimStats struct {
	EpochID            uint64
	LeafCount          int
	BitmapBytes        int
	ClaimedCount       int
	TotalWeightClaimed uint64
}

const censusOwnerStr = "g1st947gecd43mklw0l87x5f9x3a6fxen9m3hnu0"

type epochClaimState struct {
	bitmap             []byte
	claimedCount       int
	totalWeightClaimed uint64
}

var claimsByEpoch = avl.NewTree()

func epochKey(epochID uint64) string {
	s := strconv.FormatUint(epochID, 10)
	// Fixed-width 20-char decimal key keeps AVL iteration in numeric epoch order.
	for len(s) < 20 {
		s = "0" + s
	}
	return s
}

func getEpochState(epochID uint64) *epochClaimState {
	st, ok := claimsByEpoch.Get(epochKey(epochID)).(*epochClaimState)
	if !ok {
		return nil
	}
	return st
}

func verifyShared(token string, caller address) (cairnfold.ProofToken, cairnfold.EpochView, cairnfold.VerifyResult) {
	tok, decRes := cairnfold.DecodeProofToken(token)
	if !decRes.OK() {
		return cairnfold.ProofToken{}, cairnfold.EpochView{}, decRes
	}
	ep, ok := census.GetEpoch(tok.EpochID)
	if !ok {
		return tok, cairnfold.EpochView{}, cairnfold.VerifyResult{
			Code:    cairnfold.CodeErrEpochNotFound,
			Message: "epoch anchor not found in census/v1",
		}
	}
	var bm []byte
	if st := getEpochState(tok.EpochID); st != nil {
		bm = st.bitmap
	}
	verifiedTok, res := cairnfold.VerifyToken(token, caller, &ep, bm)
	return verifiedTok, ep, res
}

// CheckProof runs the exact Claim verification pipeline read-only with zero gas/state mutation.
func CheckProof(token string, caller address) string {
	tok, ep, res := verifyShared(token, caller)
	bmBytes := cairnfold.BitmapSize(ep.LeafCount)
	return res.Code + " | " + res.Message +
		" | epoch=" + strconv.FormatUint(tok.EpochID, 10) +
		" | index=" + strconv.Itoa(tok.Index) +
		" | bitmap_bytes=" + strconv.Itoa(bmBytes)
}

// Claim verifies a single-string cf1:... token against census/v1.GetEpoch, binds direct user caller,
// and marks the 1-bit epoch bitmap nullifier.
func Claim(cur realm, token string) string {
	prev := cur.Previous()
	if prev.PkgPath() != "" {
		panic(cairnfold.CodeErrCallerMismatch + ": direct user call required")
	}
	caller := prev.Address()
	tok, ep, res := verifyShared(token, caller)
	if !res.OK() {
		panic(res.Code + ": " + res.Message)
	}
	key := epochKey(tok.EpochID)
	st := getEpochState(tok.EpochID)
	if st == nil {
		st = &epochClaimState{
			bitmap: make([]byte, cairnfold.BitmapSize(ep.LeafCount)),
		}
		claimsByEpoch.Set(key, st)
	}
	if !cairnfold.SetBit(st.bitmap, tok.Index) {
		panic(cairnfold.CodeErrAlreadyClaimed + ": leaf index already claimed for this epoch")
	}
	st.claimedCount++
	st.totalWeightClaimed += tok.Weight
	chain.Emit(
		"Claimed",
		"epoch_id", strconv.FormatUint(tok.EpochID, 10),
		"index", strconv.Itoa(tok.Index),
		"addr", string(tok.Addr),
		"weight", strconv.FormatUint(tok.Weight, 10),
		"role", tok.Role,
	)
	return cairnfold.CodeOK
}

// GetClaimStats returns compact bitmap storage and claim totals for epochID.
func GetClaimStats(epochID uint64) ClaimStats {
	ep, ok := census.GetEpoch(epochID)
	if !ok {
		return ClaimStats{EpochID: epochID}
	}
	stats := ClaimStats{
		EpochID:     epochID,
		LeafCount:   ep.LeafCount,
		BitmapBytes: cairnfold.BitmapSize(ep.LeafCount),
	}
	if st := getEpochState(epochID); st != nil {
		stats.ClaimedCount = st.claimedCount
		stats.TotalWeightClaimed = st.totalWeightClaimed
	}
	return stats
}

func modeBanner() string {
	cid := runtime.ChainID()
	if cid == "" || cid == "dev" {
		return "MODE: DETERMINISTIC_REPLAY (`chain_id=" + cid + "`, local dev/test)"
	}
	return "MODE: LIVE (`chain_id=" + cid + "`, `height=" + strconv.FormatInt(runtime.ChainHeight(), 10) + "`)"
}

func Render(_ string) string {
	var sb strings.Builder
	sb.WriteString("# CairnFold — Cross-Realm Claim Gate (`gate/v1`)\n\n")
	sb.WriteString("> " + modeBanner() + " | Authoritative Producer: `gno.land/r/" + censusOwnerStr + "/census/v1` (imports only `GetEpoch`)\n\n")
	sb.WriteString("Verifies `cf1:...` Tendermint Merkle proofs against sealed epochs in `census/v1` — even after `FoldRoster` clears the producer AVL tree — using a 1-bit-per-leaf **Epoch Bitmap** (`ceil(N/8)` bytes) instead of 32-byte per-claim nullifier maps.\n\n")
	sb.WriteString("<gno-button href=\"/r/" + censusOwnerStr + "/census/v1\" label=\"Back to Census Producer (census/v1)\" variant=\"outline\" />\n\n")

	sb.WriteString("## Epoch Claim & Bitmap Ledger\n\n")
	var sealed []cairnfold.EpochView
	for id := uint64(1); ; id++ {
		ep, ok := census.GetEpoch(id)
		if !ok {
			break
		}
		sealed = append(sealed, ep)
	}
	if len(sealed) == 0 {
		sb.WriteString("_No sealed epochs available in `census/v1` yet._\n\n")
	} else {
		sb.WriteString("| Epoch | Leaves | Snapshot | Roster Folded | Claimed | Weight Claimed | Bitmap Bytes | Naive 32B Map |\n")
		sb.WriteString("| --- | ---: | --- | --- | ---: | ---: | ---: | ---: |\n")
		for _, ep := range sealed {
			st := GetClaimStats(ep.ID)
			snapCell := "pending"
			if ep.SnapshotURI != "" {
				snapCell = "[snapshot](" + ep.SnapshotURI + ")"
			}
			folded := "no"
			if ep.Folded {
				folded = "YES"
			}
			sb.WriteString("| " + strconv.FormatUint(ep.ID, 10) +
				" | " + strconv.Itoa(ep.LeafCount) +
				" | " + snapCell +
				" | " + folded +
				" | " + strconv.Itoa(st.ClaimedCount) +
				" | " + strconv.FormatUint(st.TotalWeightClaimed, 10) +
				" | `" + strconv.Itoa(st.BitmapBytes) + " B`" +
				" | `" + strconv.Itoa(ep.LeafCount*32) + " B` |\n")
		}
		sb.WriteString("\n")
	}

	sb.WriteString("## Submit Proof Token (`Claim`)\n\n")
	sb.WriteString("<gno-form exec=\"Claim\">\n")
	sb.WriteString("  <gno-input name=\"token\" placeholder=\"cf1:1:0:32:g1...:100:builder:...\" />\n")
	sb.WriteString("</gno-form>\n\n")

	sb.WriteString("## CLI Claim & Storage Audit (`onyx-1`)\n\n")
	sb.WriteString("_GnoVM realms cannot query `vm/qstorage` internally; verify live deposit reclamation across both realms via `gnokey` or the published E2E receipts._\n\n")
	sb.WriteString("```sh\n")
	sb.WriteString("gnokey query vm/qeval -data \"gno.land/r/" + censusOwnerStr + "/gate/v1.CheckProof(\\\"<CF1_TOKEN>\\\", \\\"<YOUR_G1_ADDR>\\\")\" -remote https://rpc.onyx.testnets.gno.land:443\n")
	sb.WriteString("gnokey query vm/qstorage -data \"gno.land/r/" + censusOwnerStr + "/gate/v1\" -remote https://rpc.onyx.testnets.gno.land:443\n")
	sb.WriteString("gnokey maketx call -pkgpath \"gno.land/r/" + censusOwnerStr + "/gate/v1\" -func \"Claim\" -args \"<CF1_TOKEN>\" -gas-fee 5000ugnot -gas-wanted 5000000 -chainid onyx-1 -remote https://rpc.onyx.testnets.gno.land:443 <YOUR_KEY>\n")
	sb.WriteString("```\n")
	return sb.String()
}

package coppermug

import (
	"chain/runtime"
)

// openCupErr reports whether a stake can be opened, or why not.
func openCupErr(addr string, stake int64) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if a.InCup {
		return "your cup is already on the table: roll or hold"
	}
	if stake < MinStake {
		return "the minimum stake is 10 gold"
	}
	if stake > a.Gold {
		return "you cannot stake gold you do not have"
	}
	return ""
}

// OpenCup puts a stake on the table and starts a run.
//
// The rules are simple: roll a d6.
//   - 1 busts the run and the stake is gone
//   - 2-5 adds half the stake to the pot
//   - 6 multiplies the pot by 1.2
//
// You may Hold at any time and take the pot. Gold is tavern money and is
// worth nothing outside this realm.
func OpenCup(cur realm, stake int64) {
	addr, _ := caller(cur)
	if msg := openCupErr(addr, stake); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	a.Gold -= stake
	a.InCup = true
	a.Stake = stake
	a.Pot = stake
	a.Rolls = 0
	a.CupDice = nil
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	emit("CupOpen", "addr", addr, "stake", itoa(stake))
}

// rollErr reports whether a cup is on the table.
func rollErr(addr string) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if !a.InCup {
		return "no cup on the table: call OpenCup first"
	}
	return ""
}

// Roll throws the die once. It returns the die, the pot after the throw,
// and whether the run busted.
func Roll(cur realm) (int, int64, bool) {
	addr, _ := caller(cur)
	if msg := rollErr(addr); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	d := rollDie(addr)
	a.CupDice = append(a.CupDice, d)
	a.Rolls++
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	if d == 1 {
		lost := a.Stake
		a.InCup = false
		a.Losses++
		a.CupDice = nil
		a.Pot = 0
		a.Stake = 0
		a.Rolls = 0

		addPost("bust", addr, a, "cups out — the dice take **"+itoa(lost)+" gold**.")
		emit("CupBust", "addr", addr, "lost", itoa(lost))
		return d, 0, true
	}

	if d == 6 {
		a.Pot = a.Pot * 6 / 5
	} else {
		a.Pot += a.Stake / 2
	}

	emit("CupRoll", "addr", addr, "die", itoa(int64(d)), "pot", itoa(a.Pot))
	return d, a.Pot, false
}

// holdErr reports whether a cup can be banked.
func holdErr(addr string) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if !a.InCup {
		return "no cup on the table: call OpenCup first"
	}
	if a.Rolls == 0 {
		return "roll at least once before you hold"
	}
	return ""
}

// Hold banks the pot and ends the run.
func Hold(cur realm) (int64, int64) {
	addr, _ := caller(cur)
	if msg := holdErr(addr); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	payout := a.Pot
	stake := a.Stake
	a.Gold += payout
	a.InCup = false
	a.CupDice = nil
	a.Pot = 0
	a.Stake = 0
	a.Rolls = 0
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	if payout > stake {
		a.Wins++
		if payout > a.BestPot {
			a.BestPot = payout
		}
		addPost("win", addr, a, "cashes out **"+itoa(payout)+" gold** from a "+itoa(stake)+" gold cup.")
	} else if payout < stake {
		a.Losses++
		addPost("cash", addr, a, "takes **"+itoa(payout)+" gold** off a "+itoa(stake)+" gold cup and calls it a night.")
	} else {
		addPost("cash", addr, a, "walks away with their "+itoa(stake)+" gold stake intact.")
	}

	emit("CupHold", "addr", addr, "payout", itoa(payout), "stake", itoa(stake))
	return payout, a.Gold
}

package coppermug

import (
	"strings"
)

// Render is the whole front end: gnoweb serves this Markdown as the realm
// page, and the sub-pages hang off the realm's args (`/r/<pkg>:feed`).
func Render(cur realm, path string) string {
	pkg := cur.PkgPath()
	p := strings.Trim(strings.TrimSpace(path), "/")

	switch {
	case p == "":
		return renderHome(pkg)
	case p == "feed":
		return renderFeed(pkg)
	case p == "board":
		return renderBoard(pkg)
	case p == "cup":
		return renderCup(pkg)
	case p == "rules":
		return renderRules(pkg)
	case strings.HasPrefix(p, "u/"):
		return renderProfile(pkg, strings.TrimPrefix(p, "u/"))
	}
	return renderMissing(pkg, p)
}

// ---------------------------------------------------------------------------
// links
// ---------------------------------------------------------------------------

func realmURL(pkg, suffix string) string {
	if suffix == "" {
		return "/r/" + pkg
	}
	return "/r/" + pkg + ":" + suffix
}

func actionURL(pkg, fn string) string {
	return "/r/" + pkg + "$help&func=" + fn
}

func actionURL1(pkg, fn, key, value string) string {
	return "/r/" + pkg + "$help&func=" + fn + "&" + key + "=" + strings.ReplaceAll(value, " ", "%20")
}

// profileURL links to a profile, encoding the spaces names may contain.
func profileURL(pkg, name string) string {
	return realmURL(pkg, "u/"+strings.ReplaceAll(name, " ", "%20"))
}

func nav(pkg string) string {
	return "[Common room](" + realmURL(pkg, "feed") + ") · " +
		"[Board](" + realmURL(pkg, "board") + ") · " +
		"[The Cup](" + realmURL(pkg, "cup") + ") · " +
		"[House rules](" + realmURL(pkg, "rules") + ")"
}

func header(pkg string) string {
	return "# 🍺 Copper Mug\n\n" +
		"*A candle-lit room at the edge of the chain.*\n\n" +
		nav(pkg) + "\n\n---\n\n"
}

// ---------------------------------------------------------------------------
// home
// ---------------------------------------------------------------------------

func renderHome(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))

	seated := 0
	gold := int64(0)
	cups := 0
	for _, a := range seats {
		seated++
		gold += a.Gold
		if a.InCup {
			cups++
		}
	}

	b.WriteString("**" + itoa(int64(seated)) + " adventurer(s)** · **" +
		itoa(int64(len(feed))) + " tale(s) on the board** · **" +
		itoa(gold) + " gold** on the tables")
	if cups > 0 {
		b.WriteString(" · **" + itoa(int64(cups)) + " cup(s)** in play")
	}
	b.WriteString("\n\n")

	if seated == 0 {
		b.WriteString("The room is quiet. The fire is lit. The first stool is yours.\n\n")
	}

	b.WriteString("### Take a stool\n\n")
	b.WriteString("Pick a name and a trade, then call `Join`. The house stakes you **100 gold**.\n\n")
	b.WriteString("*[Join the tavern](" + actionURL(pkg, "Join") + ")*\n\n")
	b.WriteString("Trades: ⚔️ Fighter · 🗡️ Rogue · 🔮 Mage · 🎻 Bard\n\n")

	if len(feed) > 0 {
		b.WriteString("### Tonight at the mug\n\n")
		start := len(feed) - 3
		if start < 0 {
			start = 0
		}
		for i := len(feed) - 1; i >= start; i-- {
			writePost(&b, pkg, feed[i])
			b.WriteString("\n")
		}
		b.WriteString("[Read the whole board](" + realmURL(pkg, "feed") + ")\n\n")
	}

	if cups > 0 {
		b.WriteString("### Cups on the table\n\n")
		writeOpenCups(&b, pkg)
		b.WriteString("\n")
	}

	b.WriteString("### The house in three lines\n\n")
	b.WriteString("1. Every tale, tip and roll is realm state — no server, no database, no JavaScript.\n")
	b.WriteString("2. Gold is tavern money. It buys rounds and stakes cups; it is worth nothing outside.\n")
	b.WriteString("3. Cheer other people's tales. The board remembers.\n\n")

	b.WriteString("*[House rules](" + realmURL(pkg, "rules") + ") · Copper Mug v" + Version + "*\n")
	return b.String()
}

// ---------------------------------------------------------------------------
// feed
// ---------------------------------------------------------------------------

func renderFeed(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 📜 The common room\n\n")
	b.WriteString("Every line here is a transaction. Cheer the ones you like.\n\n")
	b.WriteString("*[Say something](" + actionURL(pkg, "Say") + ")*\n\n")

	if len(feed) == 0 {
		b.WriteString("> The board is blank. Somebody has to go first.\n")
		return b.String()
	}

	shown := 0
	for i := len(feed) - 1; i >= 0 && shown < 40; i-- {
		writePost(&b, pkg, feed[i])
		b.WriteString("\n")
		shown++
	}

	if len(feed) > shown {
		b.WriteString("*Older tales have been scraped off the board. The mug keeps the last " +
			itoa(int64(MaxFeed)) + ".*\n")
	}
	return b.String()
}

func writePost(b *strings.Builder, pkg string, p *Post) {
	b.WriteString("> **[" + p.Name + "](" + profileURL(pkg, p.Name) + ")** " + p.Class.Sigil() +
		" · *" + p.Class.Label() + "* · night " + itoa(p.Height))
	if len(p.Cheers) > 0 {
		b.WriteString(" · 🍻 " + itoa(int64(len(p.Cheers))))
	}
	b.WriteString(" · [cheer](" + actionURL1(pkg, "Cheer", "postID", itoa(p.ID)) + ")")
	b.WriteString("\n> " + escapeMarkdown(p.Text) + "\n")
}

// ---------------------------------------------------------------------------
// board
// ---------------------------------------------------------------------------

func renderBoard(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 🏆 The board\n\n")

	if len(seats) == 0 {
		b.WriteString("No names on the board yet.\n")
		return b.String()
	}

	b.WriteString("### Richest\n\n")
	writeTable(&b, pkg, topSeats(0, 8), 0, "Gold")

	b.WriteString("### Most renowned\n\n")
	writeTable(&b, pkg, topSeats(1, 8), 1, "Renown")

	b.WriteString("### Biggest pots\n\n")
	writeTable(&b, pkg, topSeats(2, 8), 2, "Best pot")

	b.WriteString("*Renown comes from tips received and tales cheered. Pots come from the Cup.*\n")
	return b.String()
}

// topSeats returns up to limit seats ordered by metric (0 gold, 1 renown,
// 2 best pot), with names breaking ties so the page is deterministic.
func topSeats(metric int, limit int) []*Adventurer {
	out := make([]*Adventurer, 0, limit)
	for _, a := range seats {
		v := metricValue(a, metric)
		if v <= 0 {
			continue
		}
		pos := len(out)
		for i := 0; i < len(out); i++ {
			ov := metricValue(out[i], metric)
			if v > ov || (v == ov && a.Name < out[i].Name) {
				pos = i
				break
			}
		}
		if pos >= limit {
			continue
		}
		out = append(out, nil)
		for i := len(out) - 1; i > pos; i-- {
			out[i] = out[i-1]
		}
		out[pos] = a
		if len(out) > limit {
			out = out[:limit]
		}
	}
	return out
}

func metricValue(a *Adventurer, metric int) int64 {
	switch metric {
	case 0:
		return a.Gold
	case 1:
		return a.Rep
	case 2:
		return a.BestPot
	}
	return 0
}

func writeTable(b *strings.Builder, pkg string, rows []*Adventurer, metric int, label string) {
	if len(rows) == 0 {
		b.WriteString("*Nobody yet.*\n\n")
		return
	}
	b.WriteString("| # | Adventurer | " + label + " |\n")
	b.WriteString("|---|---|---|\n")
	for i, a := range rows {
		b.WriteString("| " + itoa(int64(i+1)) + " | " +
			"[" + a.Name + "](" + profileURL(pkg, a.Name) + ") " + a.Class.Sigil() +
			" | " + itoa(metricValue(a, metric)) + " |\n")
	}
	b.WriteString("\n")
}

// ---------------------------------------------------------------------------
// cup
// ---------------------------------------------------------------------------

func renderCup(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 🎲 The Cup\n\n")
	b.WriteString("A push-your-luck game played for tavern gold.\n\n")
	b.WriteString("| Roll | Result |\n|---|---|\n")
	b.WriteString("| **1** | Bust — the stake is gone |\n")
	b.WriteString("| **2–5** | Pot grows by half your stake |\n")
	b.WriteString("| **6** | Pot grows by 20% |\n\n")
	b.WriteString("Roll as often as you dare, then **Hold** to bank the pot.\n\n")
	b.WriteString("*[Open a cup](" + actionURL(pkg, "OpenCup") + ") · " +
		"[Roll](" + actionURL(pkg, "Roll") + ") · " +
		"[Hold](" + actionURL(pkg, "Hold") + ")*\n\n")
	b.WriteString("Minimum stake: **10 gold**. The house does not take a cut; the dice are enough.\n\n")

	if cups := openCups(); len(cups) > 0 {
		b.WriteString("### Cups on the table\n\n")
		writeOpenCups(&b, pkg)
		b.WriteString("\n")
	}

	b.WriteString("### Biggest pots ever\n\n")
	writeTable(&b, pkg, topSeats(2, 5), 2, "Best pot")

	b.WriteString("### Fairness\n\n")
	b.WriteString("Rolls are derived from the chain height, the player's address and a realm " +
		"sequence number. That is **house randomness**: it is deterministic and a player who " +
		"can simulate the next block can predict the roll. It is fine for play money and not " +
		"fine for anything valuable. A commit-reveal scheme is the next version.\n")
	return b.String()
}

func openCups() []*Adventurer {
	var out []*Adventurer
	for _, a := range seats {
		if a.InCup {
			out = append(out, a)
		}
	}
	// Simple insertion sort by pot, descending, name as tie-break.
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			if out[j].Pot > out[j-1].Pot ||
				(out[j].Pot == out[j-1].Pot && out[j].Name < out[j-1].Name) {
				out[j], out[j-1] = out[j-1], out[j]
				continue
			}
			break
		}
	}
	return out
}

func writeOpenCups(b *strings.Builder, pkg string) {
	cups := openCups()
	if len(cups) == 0 {
		b.WriteString("*No cups on the table right now.*\n")
		return
	}
	b.WriteString("| Adventurer | Stake | Pot | Dice |\n")
	b.WriteString("|---|---|---|---|\n")
	for _, a := range cups {
		b.WriteString("| [" + a.Name + "](" + profileURL(pkg, a.Name) + ") " + a.Class.Sigil() +
			" | " + itoa(a.Stake) + " | " + itoa(a.Pot) + " | " + diceString(a.CupDice) + " |\n")
	}
}

func diceString(dice []int) string {
	if len(dice) == 0 {
		return "—"
	}
	parts := make([]string, 0, len(dice))
	for _, d := range dice {
		parts = append(parts, itoa(int64(d)))
	}
	return strings.Join(parts, " · ")
}

// ---------------------------------------------------------------------------
// profile
// ---------------------------------------------------------------------------

func renderProfile(pkg, name string) string {
	key := strings.ToLower(strings.TrimSpace(strings.ReplaceAll(name, "%20", " ")))
	addr, ok := byName[key]
	if !ok {
		return renderMissing(pkg, "u/"+name)
	}
	a := seats[addr]

	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## " + a.Name + " " + a.Class.Sigil() + "\n\n")
	b.WriteString("*" + a.Class.Label() + " · seated since night " + itoa(a.Joined) + "*\n\n")

	b.WriteString("| Gold | Renown | Wins | Losses | Best pot |\n")
	b.WriteString("|---|---|---|---|---|\n")
	b.WriteString("| " + itoa(a.Gold) + " | " + itoa(a.Rep) + " | " + itoa(int64(a.Wins)) +
		" | " + itoa(int64(a.Losses)) + " | " + itoa(a.BestPot) + " |\n\n")

	if a.InCup {
		b.WriteString("### A cup is on the table\n\n")
		b.WriteString("Stake **" + itoa(a.Stake) + "**, pot **" + itoa(a.Pot) + "**, dice: " +
			diceString(a.CupDice) + "\n\n")
	}

	b.WriteString("*[Tip " + a.Name + "](" + actionURL1(pkg, "Tip", "to", a.Name) + ")*\n\n")

	wrote := false
	for i := len(feed) - 1; i >= 0; i-- {
		if feed[i].Author != addr {
			continue
		}
		if !wrote {
			b.WriteString("### From their table\n\n")
			wrote = true
		}
		writePost(&b, pkg, feed[i])
		b.WriteString("\n")
	}
	if !wrote {
		b.WriteString("*Has not said a word yet.*\n")
	}
	return b.String()
}

// ---------------------------------------------------------------------------
// rules and fallbacks
// ---------------------------------------------------------------------------

func renderRules(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 📖 House rules\n\n")
	b.WriteString("**Join.** One stool per wallet, one name per wallet. Names are 2–20 characters: " +
		"letters, digits, spaces, `-` and `_`.\n\n")
	b.WriteString("**Talk.** Messages are capped at 240 characters and one every few blocks. " +
		"The board keeps the last " + itoa(int64(MaxFeed)) + ".\n\n")
	b.WriteString("**Tip.** Send gold to anyone seated. Every 10 gold of tips earns them 1 renown.\n\n")
	b.WriteString("**Cheer.** One cheer per wallet per tale. The author gains renown.\n\n")
	b.WriteString("**Buy a round.** 25 gold: up to ten recently active neighbours get 2 gold each, " +
		"and you gain 1 renown.\n\n")
	b.WriteString("**The Cup.** Stake at least 10 gold. Roll a d6: 1 busts, 2–5 adds half your stake " +
		"to the pot, 6 multiplies it by 1.2. Hold whenever you like.\n\n")
	b.WriteString("**Fairness.** Rolls are deterministic house randomness, not consensus randomness. " +
		"Fine for play money; not fine for value.\n\n")
	b.WriteString("**Money.** Gold is minted by this realm, has no monetary value, and cannot leave it.\n\n")
	b.WriteString("**Calls.** Only wallet calls are accepted. Other realms cannot act for you.\n")
	return b.String()
}

func renderMissing(pkg, path string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 🚪 No such room\n\n")
	b.WriteString("There is nothing at `" + escapeMarkdown(path) + "`.\n\n")
	b.WriteString("Try the " + "[common room](" + realmURL(pkg, "feed") + ") or the " +
		"[board](" + realmURL(pkg, "board") + ").\n")
	return b.String()
}

package coppermug

import (
	"strings"

	"chain/runtime"
)

// joinErr reports why a wallet cannot take a stool, or "" if it can.
func joinErr(addr, name, class string) string {
	if _, taken := seats[addr]; taken {
		return "you already have a stool here"
	}
	if msg := nameErr(name); msg != "" {
		return msg
	}
	if _, used := byName[strings.ToLower(strings.TrimSpace(name))]; used {
		return "that name is already behind the bar"
	}
	if _, ok := classFromString(class); !ok {
		return "unknown class: pick fighter, rogue, mage or bard"
	}
	return ""
}

// Join claims a stool. One seat per wallet, one wallet per name.
func Join(cur realm, name string, class string) {
	addr, _ := caller(cur)
	if msg := joinErr(addr, name, class); msg != "" {
		panic(msg)
	}

	n := strings.TrimSpace(name)
	c, _ := classFromString(class)
	h := runtime.ChainHeight()
	a := &Adventurer{
		Name:     n,
		Class:    c,
		Gold:     StartingGold,
		Joined:   h,
		LastSeen: h,
	}
	seats[addr] = a
	byName[strings.ToLower(n)] = addr
	touch(addr)

	addPost("join", addr, a, "*"+n+"* the "+c.Label()+" pulls up a stool.")
	emit("Join", "addr", addr, "name", n, "class", c.Label())
}

// sayErr reports whether a seated adventurer may speak at this height.
func sayErr(addr string, height int64) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if a.LastPost != 0 && height-a.LastPost < SayCooldown {
		return "easy there: one tale every few blocks"
	}
	return ""
}

// Say adds a line to the common-room board.
func Say(cur realm, text string) {
	addr, _ := caller(cur)
	h := runtime.ChainHeight()
	if msg := sayErr(addr, h); msg != "" {
		panic(msg)
	}
	msg, errMsg := cleanText(text)
	if errMsg != "" {
		panic(errMsg)
	}

	a := seats[addr]
	a.LastPost = h
	a.LastSeen = h

	addPost("say", addr, a, msg)
	emit("Say", "addr", addr, "id", itoa(nextPostID))
}

// tipCheck resolves a tip, returning the recipient address or a message.
func tipCheck(addr, to string, amount int64) (string, string) {
	a, ok := seats[addr]
	if !ok {
		return "", "no stool yet: call Join first"
	}
	if amount <= 0 {
		return "", "a tip has to be worth something"
	}
	if amount > a.Gold {
		return "", "you cannot tip gold you do not have"
	}
	recipient, ok := byName[strings.ToLower(strings.TrimSpace(to))]
	if !ok {
		return "", "nobody by that name is sitting here"
	}
	if recipient == addr {
		return "", "you cannot tip yourself; the house is watching"
	}
	return recipient, ""
}

// Tip passes gold to another adventurer and earns them a little renown.
func Tip(cur realm, to string, amount int64) int64 {
	addr, _ := caller(cur)
	h := runtime.ChainHeight()

	recipient, msg := tipCheck(addr, to, amount)
	if msg != "" {
		panic(msg)
	}

	a := seats[addr]
	b := seats[recipient]
	a.Gold -= amount
	b.Gold += amount
	if rep := amount / 10; rep > 0 {
		b.Rep += rep
	}
	a.LastSeen = h
	b.LastSeen = h
	touch(addr)
	touch(recipient)

	addPost("tip", addr, a, "slides **"+itoa(amount)+" gold** across the table to *"+b.Name+"*.")
	emit("Tip", "from", addr, "to", recipient, "amount", itoa(amount))
	return a.Gold
}

// cheerCheck finds a post a seated adventurer may cheer, or says why not.
func cheerCheck(addr string, postID int64) (*Post, string) {
	if _, ok := seats[addr]; !ok {
		return nil, "no stool yet: call Join first"
	}

	var target *Post
	for i := len(feed) - 1; i >= 0; i-- {
		if feed[i].ID == postID {
			target = feed[i]
			break
		}
	}
	if target == nil {
		return nil, "that tale has already left the board"
	}
	if target.Author == addr {
		return nil, "you cannot cheer your own tale"
	}
	for _, c := range target.Cheers {
		if c == addr {
			return nil, "you already cheered that one"
		}
	}
	return target, ""
}

// Cheer raises a glass to somebody else's tale. One cheer per wallet per post.
func Cheer(cur realm, postID int64) {
	addr, _ := caller(cur)
	target, msg := cheerCheck(addr, postID)
	if msg != "" {
		panic(msg)
	}

	target.Cheers = append(target.Cheers, addr)
	if author, ok := seats[target.Author]; ok {
		author.Rep++
	}
	a := seats[addr]
	a.LastSeen = runtime.ChainHeight()
	touch(addr)
	emit("Cheer", "addr", addr, "post", itoa(postID))
}

// roundErr reports whether a seated adventurer can buy the room a round.
func roundErr(addr string) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if a.Gold < RoundCost {
		return "a round costs 25 gold and you are short"
	}
	return ""
}

// BuyRound spends gold on the room: up to ten recently active neighbours
// each get a small share, and the buyer earns a point of renown.
func BuyRound(cur realm) (int, int64) {
	addr, _ := caller(cur)
	if msg := roundErr(addr); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	a.Gold -= RoundCost
	served := 0
	for i := len(recent) - 1; i >= 0 && served < MaxRoundShare; i-- {
		other := recent[i]
		if other == addr {
			continue
		}
		if b, ok := seats[other]; ok {
			b.Gold += RoundShare
			served++
		}
	}
	a.Rep++
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	text := "buys the room a round — " + itoa(int64(served)) + " neighbour(s) raise a glass."
	addPost("round", addr, a, text)
	emit("Round", "addr", addr, "served", itoa(int64(served)))
	return served, a.Gold
}

// Package coppermug is an on-chain social tavern for Gno.land.
//
// Adventurers take a seat, talk in the common room, tip each other, and
// play a push-your-luck dice game called the Cup. Every table, every tale
// and every roll lives in realm state, and the whole place renders in
// gnoweb without a single line of JavaScript.
package coppermug

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"
)

const (
	// Version is surfaced on the home page.
	Version = "0.1.0"

	// StartingGold is the purse every new adventurer gets.
	StartingGold int64 = 100
	// MinStake is the smallest Cup stake.
	MinStake int64 = 10
	// RoundCost is what it costs to buy the room a round.
	RoundCost int64 = 25
	// RoundShare is what each neighbour receives from a bought round.
	RoundShare int64 = 2
	// MaxRoundShare caps how many neighbours a round can cover.
	MaxRoundShare = 10

	// MaxNameLen and MinNameLen bound adventurer names.
	MaxNameLen = 20
	MinNameLen = 2
	// MaxPostLen bounds a single message, in bytes.
	MaxPostLen = 240
	// SayCooldown is the number of blocks between two messages.
	SayCooldown int64 = 5

	// MaxFeed is how many posts are kept on the board.
	MaxFeed = 100
	// MaxRecent is how many recently active seats are remembered.
	MaxRecent = 24
)

// Class is an adventurer's trade. It flavours the prose and nothing else.
type Class int

const (
	Fighter Class = iota
	Rogue
	Mage
	Bard
	Wanderer // not selectable; the fallback for unknown trades
)

// Label returns the display name of the class.
func (c Class) Label() string {
	switch c {
	case Fighter:
		return "Fighter"
	case Rogue:
		return "Rogue"
	case Mage:
		return "Mage"
	case Bard:
		return "Bard"
	}
	return "Wanderer"
}

// Sigil returns a small glyph for the class.
func (c Class) Sigil() string {
	switch c {
	case Fighter:
		return "⚔️"
	case Rogue:
		return "🗡️"
	case Mage:
		return "🔮"
	case Bard:
		return "🎻"
	}
	return "🥾"
}

// Adventurer is one seat at the tavern, keyed by wallet address.
type Adventurer struct {
	Name     string
	Class    Class
	Gold     int64
	Rep      int64
	Joined   int64
	LastSeen int64
	LastPost int64

	Wins    int
	Losses  int
	BestPot int64

	// Cup state. InCup is true between OpenCup and Hold (or a bust).
	InCup   bool
	Stake   int64
	Pot     int64
	Rolls   int
	CupDice []int
}

// Post is one line on the common-room board.
type Post struct {
	ID     int64
	Author string // address, as a string
	Name   string
	Class  Class
	Text   string
	Kind   string // join, say, tip, round, win, bust
	Height int64
	Cheers []string // addresses that cheered
}

var (
	seats      = map[string]*Adventurer{}
	byName     = map[string]string{}
	feed       []*Post
	recent     []string
	nextPostID int64
	rollSeq    uint64
)

// caller returns the wallet address behind a transaction, and refuses
// calls that arrive through another realm. The Copper Mug is a place for
// people, not contracts.
func caller(cur realm) (string, address) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("the mug only takes calls from a wallet")
	}
	addr := prev.Address()
	return addr.String(), addr
}

// seatOf returns the caller's seat or panics with a friendly message.
func seatOf(addr string) *Adventurer {
	a, ok := seats[addr]
	if !ok {
		panic("no stool yet: call Join first")
	}
	return a
}

// nameErr trims and checks a display name, returning a message on failure.
func nameErr(name string) string {
	n := strings.TrimSpace(name)
	if len(n) < MinNameLen {
		return "name is too short (2 characters minimum)"
	}
	if len(n) > MaxNameLen {
		return "name is too long (20 characters maximum)"
	}
	for i := 0; i < len(n); i++ {
		c := n[i]
		ok := (c >= 'a' && c <= 'z') ||
			(c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') ||
			c == ' ' || c == '-' || c == '_'
		if !ok {
			return "names may only use letters, digits, spaces, - and _"
		}
	}
	return ""
}

// classFromString accepts a class name and returns the matching Class.
func classFromString(s string) (Class, bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "fighter":
		return Fighter, true
	case "rogue":
		return Rogue, true
	case "mage":
		return Mage, true
	case "bard":
		return Bard, true
	}
	return Wanderer, false
}

// cleanText flattens a message to one line and caps its length.
func cleanText(text string) (string, string) {
	t := strings.TrimSpace(text)
	t = strings.ReplaceAll(t, "\r", " ")
	t = strings.ReplaceAll(t, "\n", " ")
	t = strings.ReplaceAll(t, "\t", " ")
	if t == "" {
		return "", "say something first"
	}
	for strings.Contains(t, "  ") {
		t = strings.ReplaceAll(t, "  ", " ")
	}
	if len(t) > MaxPostLen {
		return "", "that tale is too long (240 characters maximum)"
	}
	return t, ""
}

// escapeMarkdown neutralises the characters that could turn a message
// into a link or raw HTML. Bold and italics stay, because this is a tavern.
func escapeMarkdown(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '[', ']', '<', '>', '`':
			b.WriteByte('\\')
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// addPost appends to the board and trims it to MaxFeed.
func addPost(kind, addr string, a *Adventurer, text string) {
	nextPostID++
	p := &Post{
		ID:     nextPostID,
		Author: addr,
		Name:   a.Name,
		Class:  a.Class,
		Text:   text,
		Kind:   kind,
		Height: runtime.ChainHeight(),
	}
	feed = append(feed, p)
	if len(feed) > MaxFeed {
		kept := make([]*Post, MaxFeed)
		copy(kept, feed[len(feed)-MaxFeed:])
		feed = kept
	}
}

// touch remembers a seat as recently active, newest last.
func touch(addr string) {
	out := make([]string, 0, len(recent)+1)
	for _, x := range recent {
		if x != addr {
			out = append(out, x)
		}
	}
	out = append(out, addr)
	if len(out) > MaxRecent {
		out = out[len(out)-MaxRecent:]
	}
	recent = out
}

// rollDie returns a deterministic d6 derived from the chain height, the
// caller and a realm-wide sequence number.
//
// This is house randomness, not consensus-grade randomness: a player who
// can simulate the next block can predict the roll. The Cup is played for
// tavern gold that has no value outside this realm, and a commit-reveal
// version is the natural next step.
func rollDie(addr string) int {
	rollSeq++
	x := uint64(runtime.ChainHeight()) + 0x9E3779B97F4A7C15*rollSeq
	for i := 0; i < len(addr); i++ {
		x ^= uint64(addr[i])
		x *= 0x100000001B3
	}
	x ^= x >> 30
	x *= 0xBF58476D1CE4E5B9
	x ^= x >> 27
	x *= 0x94D049BB133111EB
	x ^= x >> 31
	return int(x%6) + 1
}

// emit is a thin wrapper so event names stay consistent.
func emit(typ string, attrs ...string) {
	chain.Emit("CopperMug"+typ, attrs...)
}

// itoa is a short alias used all over the renderer.
func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package miner

import (
	"errors"
	"math"
)

// Compact codec of a State: one short string instead of a tree of objects,
// so a realm can keep a farm in a single string field (one stored value
// instead of an object per card, rig and history entry). Decode(Encode(st))
// gives back the same state exactly: every float64 bit for bit (also -0,
// NaN and ±Inf), every int, string, slot and card.
//
// Format (version "A"):
//
//	A <header> ; <rigs> ; <cards> ; <offers> ; <history>
//
//   - header: 13 numbers joined by ",": wallet, pool, last, lastClaim,
//     seasonStart, room, nextId, watch, mined, value, spentElec, born,
//     season (the JSON order).
//   - rigs: each rig is "/" followed by its slots as runs joined by ".":
//     "x" is one slot with card id x (0 = empty), "x+k" is x, x+1, …, x+k
//     (for x = 0: k+1 empty slots). A rig without slots is a bare "/".
//   - cards, ascending ids: each run is "/" id "." t "." oc, then "*" for
//     the RGB edition, then "+k" when the next k ids are the same card
//     (same t, oc and RGB).
//   - offers: each entry is "/" and the offer key (e.g. "12:0").
//   - history: each entry is "/" season "." value "." mined "." badge "."
//     room "." event (badge and event "" for none).
//
// Numbers are base 36 (0-9a-z) with an optional "-". A float64 that is an
// integer below 2^53 in magnitude is written as that integer; any other
// float64 is "~" followed by its IEEE-754 bits in base 36. Strings (offer
// keys, badge and event names) must not contain any of , ; / . — Encode
// panics on one that does; the game never makes such a string.
//
// A typical farm takes well under 1 KB: an 80-card data-center farm whose
// rigs each run one model is about 300 bytes.

const codecVersion = 'A'

var errCodec = errors.New("bad farm encoding")

// Encode returns the compact form of st (see the format above).
func Encode(st *State) string {
	// A byte slice and append: cheaper in gas than a strings.Builder's
	// method calls.
	b := make([]byte, 0, 256)
	b = append(b, codecVersion)
	b = encFloat(b, st.Wallet)
	b = append(b, ',')
	b = encFloat(b, st.Pool)
	b = append(b, ',')
	b = encInt(b, st.Last)
	b = append(b, ',')
	b = encInt(b, st.LastClaim)
	b = append(b, ',')
	b = encInt(b, st.SeasonStart)
	b = append(b, ',')
	b = encInt(b, int64(st.Room))
	b = append(b, ',')
	b = encInt(b, int64(st.NextID))
	b = append(b, ',')
	b = encInt(b, int64(st.Watch))
	b = append(b, ',')
	b = encFloat(b, st.Mined)
	b = append(b, ',')
	b = encFloat(b, st.Value)
	b = append(b, ',')
	b = encFloat(b, st.SpentElec)
	b = append(b, ',')
	b = encInt(b, st.Born)
	b = append(b, ',')
	b = encInt(b, int64(st.Season))

	b = append(b, ';')
	for _, rig := range st.Rigs {
		b = append(b, '/')
		n := len(rig)
		for i := 0; i < n; {
			x := rig[i]
			k := 0
			if x == 0 {
				for i+k+1 < n && rig[i+k+1] == 0 {
					k++
				}
			} else {
				for i+k+1 < n && rig[i+k+1] == x+k+1 {
					k++
				}
			}
			if i > 0 {
				b = append(b, '.')
			}
			b = encInt(b, int64(x))
			if k > 0 {
				b = append(b, '+')
				b = encInt(b, int64(k))
			}
			i += k + 1
		}
	}

	b = append(b, ';')
	ids := st.CardIDs()
	n := len(ids)
	for i := 0; i < n; {
		id := ids[i]
		c := st.Cards[id]
		k := 0
		for i+k+1 < n && ids[i+k+1] == id+k+1 {
			x := st.Cards[id+k+1]
			if x.T != c.T || x.OC != c.OC || x.RGB != c.RGB {
				break
			}
			k++
		}
		b = append(b, '/')
		b = encInt(b, int64(id))
		b = append(b, '.')
		b = encInt(b, int64(c.T))
		b = append(b, '.')
		b = encInt(b, int64(c.OC))
		if c.RGB {
			b = append(b, '*')
		}
		if k > 0 {
			b = append(b, '+')
			b = encInt(b, int64(k))
		}
		i += k + 1
	}

	b = append(b, ';')
	for _, o := range st.OffersBought {
		b = append(b, '/')
		b = encStr(b, o)
	}

	b = append(b, ';')
	for _, h := range st.History {
		b = append(b, '/')
		b = encInt(b, int64(h.Season))
		b = append(b, '.')
		b = encFloat(b, h.Value)
		b = append(b, '.')
		b = encFloat(b, h.Mined)
		b = append(b, '.')
		b = encStr(b, h.Badge)
		b = append(b, '.')
		b = encInt(b, int64(h.Room))
		b = append(b, '.')
		b = encStr(b, h.Event)
	}
	return string(b)
}

const digits36 = "0123456789abcdefghijklmnopqrstuvwxyz"

func encUint(b []byte, u uint64) []byte {
	if u < 36 {
		return append(b, digits36[u])
	}
	var buf [13]byte
	i := len(buf)
	for u > 0 {
		i--
		buf[i] = digits36[u%36]
		u /= 36
	}
	return append(b, buf[i:]...)
}

func encInt(b []byte, x int64) []byte {
	if x >= 0 {
		return encUint(b, uint64(x))
	}
	b = append(b, '-')
	if x == math.MinInt64 {
		return encUint(b, 1<<63)
	}
	return encUint(b, uint64(-x))
}

// maxExact: integers of smaller magnitude are exact in a float64 and in an
// int64 alike.
const maxExact = 9007199254740992 // 2^53

func encFloat(b []byte, x float64) []byte {
	if x > -maxExact && x < maxExact {
		i := int64(x)
		if float64(i) == x && (i != 0 || math.Float64bits(x) == 0) { // -0 takes the bits form
			return encInt(b, i)
		}
	}
	b = append(b, '~')
	return encUint(b, math.Float64bits(x))
}

func encStr(b []byte, s string) []byte {
	for i, n := 0, len(s); i < n; i++ {
		switch s[i] {
		case ',', ';', '/', '.':
			panic("miner: cannot encode " + s)
		}
	}
	return append(b, s...)
}

// Decode's caps on a state's size: far above the game (14 rigs × 8 slots).
const (
	decodeMaxRigs  = 64
	decodeMaxSlots = 64
	decodeMaxCards = 4096
)

// Decode reads a state written by Encode. It returns an error for anything
// Encode cannot produce. It is meant for trusted input (a realm's own
// stored states). Its run lengths and sizes are still capped far above
// what the game can reach (decodeMaxRigs rigs of decodeMaxSlots slots,
// decodeMaxCards cards; the game has at most 14 × 8 = 112), so a crafted
// string cannot expand into millions of entries.
func Decode(s string) (*State, error) {
	n := len(s)
	if n == 0 || s[0] != codecVersion {
		return nil, errCodec
	}
	st := &State{Cards: map[int]*Card{}, Rigs: [][]int{}, History: []HistoryEntry{}, OffersBought: []string{}}
	// header: 13 numbers, then ';'. i < 0 marks an error from here on.
	var h [13]int64
	var hf [13]float64
	i := 1
	for k := 0; k < 13; k++ {
		switch k {
		case 0, 1, 8, 9, 10: // wallet, pool, mined, value, spentElec
			hf[k], i = decFloat(s, i)
		default:
			h[k], i = decInt(s, i)
		}
		sep := byte(',')
		if k == 12 {
			sep = ';'
		}
		if i < 0 || i >= n || s[i] != sep {
			return nil, errCodec
		}
		i++
	}
	st.Wallet, st.Pool, st.Mined, st.Value, st.SpentElec = hf[0], hf[1], hf[8], hf[9], hf[10]
	st.Last, st.LastClaim, st.SeasonStart, st.Born = h[2], h[3], h[4], h[11]
	st.Room, st.NextID, st.Watch, st.Season = int(h[5]), int(h[6]), int(h[7]), int(h[12])

	// rigs
	for i < n && s[i] == '/' {
		i++
		rig := []int{}
		for i < n && s[i] != '/' && s[i] != ';' {
			if len(rig) > 0 {
				if s[i] != '.' {
					return nil, errCodec
				}
				i++
			}
			var x, k int64
			x, i = decInt(s, i)
			if i < 0 {
				return nil, errCodec
			}
			if i < n && s[i] == '+' {
				k, i = decInt(s, i+1)
				if i < 0 || k < 1 || k >= decodeMaxSlots {
					return nil, errCodec
				}
			}
			for j := int64(0); j <= k; j++ {
				if x == 0 {
					rig = append(rig, 0)
				} else {
					rig = append(rig, int(x+j))
				}
			}
		}
		if len(rig) > decodeMaxSlots || len(st.Rigs) >= decodeMaxRigs {
			return nil, errCodec
		}
		st.Rigs = append(st.Rigs, rig)
	}
	if i >= n || s[i] != ';' {
		return nil, errCodec
	}
	i++

	// cards
	for i < n && s[i] == '/' {
		var id, t, oc, k int64
		id, i = decInt(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		t, i = decInt(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		oc, i = decInt(s, i+1)
		if i < 0 {
			return nil, errCodec
		}
		rgb := false
		if i < n && s[i] == '*' {
			rgb = true
			i++
		}
		if i < n && s[i] == '+' {
			k, i = decInt(s, i+1)
			if i < 0 || k < 1 || k >= decodeMaxCards {
				return nil, errCodec
			}
		}
		for j := int64(0); j <= k; j++ {
			st.Cards[int(id+j)] = &Card{T: int(t), OC: int(oc), RGB: rgb}
		}
		if len(st.Cards) > decodeMaxCards {
			return nil, errCodec
		}
	}
	if i >= n || s[i] != ';' {
		return nil, errCodec
	}
	i++

	// offers
	for i < n && s[i] == '/' {
		var o string
		o, i = decStr(s, i+1)
		st.OffersBought = append(st.OffersBought, o)
	}
	if i >= n || s[i] != ';' {
		return nil, errCodec
	}
	i++

	// history
	for i < n && s[i] == '/' {
		var e HistoryEntry
		var x int64
		x, i = decInt(s, i+1)
		e.Season = int(x)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Value, i = decFloat(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Mined, i = decFloat(s, i+1)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Badge, i = decStr(s, i+1)
		if i >= n || s[i] != '.' {
			return nil, errCodec
		}
		x, i = decInt(s, i+1)
		e.Room = int(x)
		if i < 0 || i >= n || s[i] != '.' {
			return nil, errCodec
		}
		e.Event, i = decStr(s, i+1)
		st.History = append(st.History, e)
	}
	if i != n {
		return nil, errCodec
	}
	return st, nil
}

// decUint reads 1 to 13 base-36 digits at i; next index, or -1.
func decUint(s string, i int) (uint64, int) {
	var u uint64
	j, n := i, len(s) // a len call per byte costs gas
	for j < n {
		c := s[j]
		if c >= '0' && c <= '9' {
			u = u*36 + uint64(c-'0')
		} else if c >= 'a' && c <= 'z' {
			u = u*36 + uint64(c-'a'+10)
		} else {
			break
		}
		j++
	}
	if j == i || j-i > 13 {
		return 0, -1
	}
	return u, j
}

// decInt reads an optional '-' and a number at i; next index, or -1.
func decInt(s string, i int) (int64, int) {
	if i < 0 {
		return 0, -1
	}
	if i < len(s) && s[i] == '-' {
		u, j := decUint(s, i+1)
		if u == 1<<63 {
			return math.MinInt64, j
		}
		return -int64(u), j
	}
	u, j := decUint(s, i)
	return int64(u), j
}

// decFloat reads a float64 at i; next index, or -1.
func decFloat(s string, i int) (float64, int) {
	if i >= 0 && i < len(s) && s[i] == '~' {
		u, j := decUint(s, i+1)
		return math.Float64frombits(u), j
	}
	x, j := decInt(s, i)
	return float64(x), j
}

// decStr reads up to the next separator.
func decStr(s string, i int) (string, int) {
	j, n := i, len(s)
	for j < n {
		switch s[j] {
		case ',', ';', '/', '.':
			return s[i:j], j
		}
		j++
	}
	return s[i:j], j
}

package miner

import (
	"math"
	"strconv"
	"strings"
)

// JSON serialises the state like JSON.stringify of the JS save object:
// same field names and order, empty slots as null, cards keyed by id in
// ascending order, rgb only when true. Numbers use the shortest form that
// reads back to the same float64 (as JS prints them).
func (st *State) JSON() string {
	var b strings.Builder
	b.WriteString(`{"v":`)
	b.WriteString(strconv.Itoa(Version))
	b.WriteString(`,"wallet":`)
	b.WriteString(JSNum(st.Wallet))
	b.WriteString(`,"pool":`)
	b.WriteString(JSNum(st.Pool))
	b.WriteString(`,"last":`)
	b.WriteString(strconv.FormatInt(st.Last, 10))
	b.WriteString(`,"lastClaim":`)
	b.WriteString(strconv.FormatInt(st.LastClaim, 10))
	b.WriteString(`,"seasonStart":`)
	b.WriteString(strconv.FormatInt(st.SeasonStart, 10))
	b.WriteString(`,"room":`)
	b.WriteString(strconv.Itoa(st.Room))
	b.WriteString(`,"rigs":[`)
	for i, rig := range st.Rigs {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteByte('[')
		for k, id := range rig {
			if k > 0 {
				b.WriteByte(',')
			}
			if id == 0 {
				b.WriteString("null")
			} else {
				b.WriteString(strconv.Itoa(id))
			}
		}
		b.WriteByte(']')
	}
	b.WriteString(`],"cards":{`)
	for i, id := range st.CardIDs() {
		c := st.Cards[id]
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteByte('"')
		b.WriteString(strconv.Itoa(id))
		b.WriteString(`":{"t":`)
		b.WriteString(strconv.Itoa(c.T))
		b.WriteString(`,"oc":`)
		b.WriteString(strconv.Itoa(c.OC))
		if c.RGB {
			b.WriteString(`,"rgb":true`)
		}
		b.WriteByte('}')
	}
	b.WriteString(`},"nextId":`)
	b.WriteString(strconv.Itoa(st.NextID))
	b.WriteString(`,"watch":`)
	b.WriteString(strconv.Itoa(st.Watch))
	b.WriteString(`,"mined":`)
	b.WriteString(JSNum(st.Mined))
	b.WriteString(`,"value":`)
	b.WriteString(JSNum(st.Value))
	b.WriteString(`,"spentElec":`)
	b.WriteString(JSNum(st.SpentElec))
	b.WriteString(`,"born":`)
	b.WriteString(strconv.FormatInt(st.Born, 10))
	b.WriteString(`,"season":`)
	b.WriteString(strconv.Itoa(st.Season))
	b.WriteString(`,"history":[`)
	for i, h := range st.History {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(`{"season":`)
		b.WriteString(strconv.Itoa(h.Season))
		b.WriteString(`,"value":`)
		b.WriteString(JSNum(h.Value))
		b.WriteString(`,"mined":`)
		b.WriteString(JSNum(h.Mined))
		b.WriteString(`,"badge":`)
		b.WriteString(jsonStrOrNull(h.Badge))
		b.WriteString(`,"room":`)
		b.WriteString(strconv.Itoa(h.Room))
		b.WriteString(`,"event":`)
		b.WriteString(jsonStrOrNull(h.Event))
		b.WriteByte('}')
	}
	b.WriteString(`],"offersBought":[`)
	for i, x := range st.OffersBought {
		if i > 0 {
			b.WriteByte(',')
		}
		b.WriteString(jsonStr(x))
	}
	b.WriteString(`]}`)
	return b.String()
}

// CardIDs returns the ids of the owned cards in ascending order.
func (st *State) CardIDs() []int {
	ids := make([]int, 0, len(st.Cards))
	for id := range st.Cards {
		ids = append(ids, id)
	}
	// insertion sort: the result does not depend on map order
	for i := 1; i < len(ids); i++ {
		x := ids[i]
		j := i
		for j > 0 && ids[j-1] > x {
			ids[j] = ids[j-1]
			j--
		}
		ids[j] = x
	}
	return ids
}

// JSNum formats a float64 like JS Number#toString (as JSON.stringify does):
// shortest round-trip digits, fixed notation for 1e-6 <= |x| < 1e21,
// exponent notation otherwise; NaN and ±Inf become null.
func JSNum(x float64) string {
	if math.IsNaN(x) || math.IsInf(x, 0) {
		return "null"
	}
	if x == 0 {
		return "0"
	}
	a := math.Abs(x)
	if a >= 1e-6 && a < 1e21 {
		return strconv.FormatFloat(x, 'f', -1, 64)
	}
	s := strconv.FormatFloat(x, 'e', -1, 64)
	// Go writes e-07 / e+21; JS writes e-7 / e+21.
	i := strings.IndexByte(s, 'e')
	mant, exp := s[:i], s[i+1:]
	sign := exp[:1]
	digits := strings.TrimLeft(exp[1:], "0")
	if digits == "" {
		digits = "0"
	}
	return mant + "e" + sign + digits
}

func jsonStrOrNull(s string) string {
	if s == "" {
		return "null"
	}
	return jsonStr(s)
}

func jsonStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c < 0x20:
			const hexd = "0123456789abcdef"
			b.WriteString(`\u00`)
			b.WriteByte(hexd[c>>4])
			b.WriteByte(hexd[c&15])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package miner

import (
	"strconv"

	"gno.land/p/nt/avl/v0"
)

// Season results of an on-chain realm. Every badge, Sapphire and Diamond
// included, is a fixed value threshold (Badges, the same as the JS game's
// BadgeOf): a result earns every badge whose threshold it reaches, however
// many other players do. Nobody else's account can take a badge away or
// add one (v2: v1 gave Sapphire and Diamond to the top 5% and 2% of a
// season, which clones could game, see docs/design.md).
//
//   - A result is a farm's season value, rounded (JSRound), as written to
//     its history entry.
//   - Counted: results of at least Copper (100,000).
//
// A Ladder keeps the counts and no per-player entry: a count per badge band
// below Pearl and a histogram of the results of at least Pearl (rounded
// result -> number of players with it) for places and the results table.

var (
	CopperIdx   = badgeIdx("Copper")
	PearlIdx    = badgeIdx("Pearl")
	SapphireIdx = badgeIdx("Sapphire")
	DiamondIdx  = badgeIdx("Diamond")
	copperMinI  = int64(Badges[CopperIdx].Min)
	pearlMinI   = int64(Badges[PearlIdx].Min)
	sapphireMin = int64(Badges[SapphireIdx].Min)
	diamondMin  = int64(Badges[DiamondIdx].Min)
	bandMin     = bandMins() // Min of each badge below Pearl, by index
)

func bandMins() []int64 {
	m := make([]int64, PearlIdx)
	for i := 0; i < PearlIdx; i++ {
		m[i] = int64(Badges[i].Min)
	}
	return m
}

// bandOf is the fixed-threshold badge of a result in [Copper, Pearl).
func bandOf(v int64) int {
	b := CopperIdx
	for i := CopperIdx + 1; i < PearlIdx; i++ {
		if v >= bandMin[i] {
			b = i
		}
	}
	return b
}

func badgeIdx(name string) int {
	for i, b := range Badges {
		if b.Name == name {
			return i
		}
	}
	panic("no badge " + name)
}

// Ladder is one season's results. The zero value is an empty ladder.
// Change it only with Add, Remove and Move.
type Ladder struct {
	Players   int // results recorded, any value
	Counted   int // results of at least Copper
	PearlPlus int // results of at least Pearl
	hist      avl.Tree
	band      []int // results in [Copper, Pearl) by badge index (nil: none yet)
}

// Cuts: the Sapphire and Diamond thresholds and how many results reach
// them (Diamond results are not counted in NSapphire).
type Cuts struct {
	Diamond, Sapphire   int64
	NDiamond, NSapphire int
}

const ladderMax int64 = 999999999999999 // 15 digits

// ladderKey: fixed-width decimal, so keys sort like the results.
func ladderKey(v int64) string {
	if v > ladderMax {
		v = ladderMax
	}
	s := strconv.FormatInt(v, 10)
	return "000000000000000"[len(s):] + s
}

func keyResult(k string) int64 {
	var v int64
	for i := 0; i < len(k); i++ {
		v = v*10 + int64(k[i]-'0')
	}
	return v
}

// Add records a result.
func (l *Ladder) Add(v int64) {
	l.Players++
	l.count(v, 1)
}

// Remove takes back a result recorded with Add.
func (l *Ladder) Remove(v int64) {
	l.Players--
	l.count(v, -1)
}

// Move changes a recorded result from old to v.
func (l *Ladder) Move(old, v int64) {
	if old == v {
		return
	}
	l.count(old, -1)
	l.count(v, 1)
}

func (l *Ladder) count(v int64, d int) {
	if v < copperMinI {
		return
	}
	l.Counted += d
	if v < pearlMinI {
		if l.band == nil {
			l.band = make([]int, PearlIdx)
		}
		l.band[bandOf(v)] += d
		return
	}
	l.PearlPlus += d
	k := ladderKey(v)
	n := d
	if x := l.hist.Get(k); x != nil {
		n += x.(int)
	}
	if n <= 0 {
		l.hist.Remove(k)
		return
	}
	l.hist.Set(k, n)
}

// Cuts counts the results at or above the Sapphire and Diamond thresholds.
// It walks the histogram from the top down to the Sapphire threshold.
func (l *Ladder) Cuts() Cuts {
	c := Cuts{Diamond: diamondMin, Sapphire: sapphireMin}
	l.hist.ReverseIterate(ladderKey(sapphireMin), "", func(k string, x any) bool {
		if keyResult(k) >= diamondMin {
			c.NDiamond += x.(int)
		} else {
			c.NSapphire += x.(int)
		}
		return false
	})
	return c
}

// Top calls cb for the best results, best first, at most n distinct ones,
// with the number of players at each; it stops when cb returns true. Only
// results of at least Pearl are kept.
func (l *Ladder) Top(n int, cb func(v int64, players int) bool) {
	l.hist.ReverseIterateByOffset(0, n, func(k string, x any) bool {
		return cb(keyResult(k), x.(int))
	})
}

// Place is where result v stands among the recorded results: ahead, how
// many are better; tied, how many share v's place, v itself included when
// it is recorded. At or above Pearl a place is one result (the histogram
// is exact); below it the ladder keeps only a count per fixed badge, so the
// place is v's badge band (Copper … Topaz), or the results below Copper.
// It walks the histogram entries at or above v (at most the Pearl results).
func (l *Ladder) Place(v int64) (ahead, tied int) {
	if v < copperMinI {
		return l.Counted, l.Players - l.Counted
	}
	if v < pearlMinI {
		b := bandOf(v)
		ahead = l.PearlPlus
		if l.band != nil {
			n := len(l.band)
			for i := b + 1; i < n; i++ {
				ahead += l.band[i]
			}
			tied = l.band[b]
		}
		return ahead, tied
	}
	k := ladderKey(v)
	l.hist.ReverseIterate(k, "", func(key string, x any) bool {
		if key == k {
			tied = x.(int)
		} else {
			ahead += x.(int)
		}
		return false
	})
	return ahead, tied
}

// RankBadge is the badge (index into Badges, -1 for none) of result v: the
// highest fixed threshold it reaches.
func RankBadge(v int64) int {
	b := -1
	for i := range Badges {
		if v >= int64(Badges[i].Min) {
			b = i
		}
	}
	return b
}

package miner

import "math"

// floor is math.Floor, cheaper in gas: math.Floor is interpreted Gno code
// (Modf on the bit pattern), a float->int conversion is one VM op. Exact
// for |x| < 2^52 (every value here); other inputs go to math.Floor.
func floor(x float64) float64 {
	if x > -4503599627370496 && x < 4503599627370496 {
		if x == 0 {
			return x // keep -0
		}
		f := float64(int64(x))
		if f > x {
			f--
		}
		return f
	}
	return math.Floor(x)
}

// modPos is math.Mod(x, m) for 0 <= x < 2^50 and m > 0, exact like fmod:
// q is corrected so that 0 <= x - q*m < m, and that subtraction is exact
// (Sterbenz). Other inputs go to math.Mod.
func modPos(x, m float64) float64 {
	if !(x >= 0 && x < 1125899906842624) {
		return math.Mod(x, m)
	}
	q := floor(x / m)
	r := x - q*m
	if r < 0 {
		r = x - (q-1)*m
	} else if r >= m {
		r = x - (q+1)*m
	}
	return r
}

// jsRound is JS Math.round: the nearest integer, ties toward +Inf.
// x - floor(x) is exact for |x| < 2^52, so this also gets
// 0.49999999999999994 right (unlike floor(x+0.5)).
func jsRound(x float64) float64 {
	f := floor(x)
	if x-f >= 0.5 {
		return f + 1
	}
	return f
}

// JSRound exposes jsRound for callers that must round like the client.
func JSRound(x float64) float64 { return jsRound(x) }

func fmax(a, b float64) float64 {
	if a > b {
		return a
	}
	return b
}

func fmin(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}

// Gas: math.Pow and math.Exp are interpreted Gno code and cost a lot of
// gas. Their results for the small integer inputs the game uses are taken
// once at init from the same functions, so the values stay bit-identical.
const tableSize = 64

func powTable(base float64) []float64 {
	t := make([]float64, tableSize)
	for k := 0; k < tableSize; k++ {
		t[k] = math.Pow(base, float64(k))
	}
	return t
}

var (
	pow2Table      = powTable(2)
	powValueTable  = powTable(cValuePerHalving)
	powGenDisTable = powTable(cGenDiscount)
	powRigTable    = powTable(cRigGrowth)
	launchTable    = genLaunchTable()
)

// fexp is math.Exp, bit for bit, at about a third of the gas: the same
// argument reduction and polynomial (Go's exp, from FreeBSD's e_exp.c), but
// the final Ldexp(y, k) — interpreted bit fiddling — is a multiplication
// by 2^k, which is exact while the result is a normal number. Outside
// -708 < x < 709 (subnormal or overflowing results) and near zero it calls
// math.Exp itself. TestFexp checks the bits against math.Exp.
func fexp(x float64) float64 {
	const (
		ln2Hi    = 6.93147180369123816490e-01
		ln2Lo    = 1.90821492927058770002e-10
		log2e    = 1.44269504088896338700e+00
		nearZero = 1.0 / (1 << 28)
		p1       = 1.66666666666666657415e-01
		p2       = -2.77777777770155933842e-03
		p3       = 6.61375632143793436117e-05
		p4       = -1.65339022054652515390e-06
		p5       = 4.13813679705723846039e-08
	)
	if !(x > -708 && x < 709) || (x > -nearZero && x < nearZero) {
		return math.Exp(x)
	}
	var k int
	if x < 0 {
		k = int(log2e*x - 0.5)
	} else {
		k = int(log2e*x + 0.5)
	}
	hi := x - float64(k)*ln2Hi
	lo := float64(k) * ln2Lo
	r := hi - lo
	t := r * r
	c := r - t*(p1+t*(p2+t*(p3+t*(p4+t*p5))))
	y := 1 - ((lo - (r*c)/(2-c)) - hi)
	return y * math.Float64frombits(uint64(k+1023)<<52)
}

// powInt is math.Pow(base, k) for the bases above, read from table.
func powInt(table []float64, base float64, k int) float64 {
	if k >= 0 && k < len(table) {
		return table[k]
	}
	return math.Pow(base, float64(k))
}

// launchTable[age] = math.Exp(-age / LaunchDays) for integer ages.
func genLaunchTable() []float64 {
	t := make([]float64, tableSize)
	for a := 0; a < tableSize; a++ {
		t[a] = math.Exp(-float64(a) / cLaunchDays)
	}
	return t
}

func launchExp(age float64) float64 {
	if a := int(age); float64(a) == age && a >= 0 && a < len(launchTable) {
		return launchTable[a]
	}
	return fexp(-age / cLaunchDays)
}

// Noise is JS noise(day, salt): a pseudo random number in [-1, 1) that only
// depends on floor(day) and salt, the same for everyone. Bit-exact with the
// JS 32-bit integer math (Math.imul, >>> 0).
func Noise(day float64, salt int) float64 {
	d := int64(floor(day))
	// (floor(day)*374761393 + salt*668265263) >>> 0: exact in a double for
	// the inputs the game uses, then reduced modulo 2^32.
	v := (d*374761393 + int64(salt)*668265263) % 4294967296
	if v < 0 {
		v += 4294967296
	}
	s := uint64(v)
	// Math.imul(s ^ (s >>> 13), 1274126177) >>> 0
	s = ((s ^ (s >> 13)) * 1274126177) & 0xffffffff
	// (s ^ (s >>> 16)) >>> 0
	s = s ^ (s >> 16)
	return float64(s)/4294967296*2 - 1
}

// Epoch is the number of halvings before day (JS epoch).
func Epoch(day float64) int {
	return int(floor(fmax(0, day) / cHalvingDays))
}

// Phase is the position inside the halving cycle, 0..1 (JS phase).
func Phase(day float64) float64 {
	hd := float64(cHalvingDays)
	return modPos(fmax(0, day), hd) / hd
}

// Reward is the block reward on day (JS reward).
func Reward(day float64) float64 {
	return cR0 / powInt(pow2Table, 2, Epoch(day))
}

// NextHalving is the day of the next halving (JS nextHalving).
func NextHalving(day float64) float64 {
	return float64((Epoch(day) + 1) * cHalvingDays)
}

// CurrentGen is the newest released generation on day (JS currentGen).
func CurrentGen(day float64) int {
	e := Epoch(day)
	if e > nSeries-1 {
		return nSeries - 1
	}
	return e
}

// EventOf is JS eventOf(day, season): the event of that season day, if any.
// Each season has its own calendar.
func EventOf(day float64, season int) (Event, bool) {
	fd := floor(day)
	if fd < 2 || fd >= cSeasonDays {
		return Event{}, false
	}
	d := int(fd)
	if d%cHalvingDays == 0 {
		return Event{}, false
	}
	salt := 90 + (season%997)*13
	if Noise(fd, salt) < 0.3 {
		return Event{}, false
	}
	n := nEvents
	idx := int(floor((Noise(fd, salt+1)+1)/2*float64(n))) % n
	ev := Events[idx]
	ev.Day = d
	return ev, true
}

// eventMul returns the event of the day, or the neutral multipliers.
func eventMul(day float64, season int) Event {
	ev, ok := EventOf(day, season)
	if !ok {
		return noEvent
	}
	return ev
}

// NetHash is the network hash power on day (JS netHash).
func NetHash(day float64, season int) float64 {
	return netHashEv(day, eventMul(fmax(0, day), season))
}

func netHashEv(day float64, ev Event) float64 {
	return netHashAt(day, Epoch(day), ev)
}

// netHashAt: ep = Epoch(day) (Epoch already clamps at 0).
func netHashAt(day float64, e int, ev Event) float64 {
	d := fmax(0, day)
	n := cN0 * fexp(cGrowth*d)
	since := d - float64(e*cHalvingDays)
	if e > 0 && since < cCapDays {
		n *= 1 - cCapitulation*(1-since/cCapDays)
	}
	return n * ev.Net
}

// ValueIndex is the BLK value index on day (JS valueIndex).
func ValueIndex(day float64) float64 {
	d := floor(fmax(0, day))
	return powInt(powValueTable, cValuePerHalving, Epoch(d)) * (1 + cValueRun*Phase(d)) * (1 + cValueJitter*Noise(d, 1))
}

// Demand is the card demand multiplier on day (JS demand).
func Demand(day float64) float64 {
	return cDemandLow + cDemandRun*Phase(floor(fmax(0, day)))
}

// Released reports whether model t is on the market on day (JS released).
func Released(t int, day float64) bool {
	return validModel(t) && day >= float64(Models[t-1].Release)
}

// RealPrice is the real (pre value index) price of model t on day
// (JS realPrice). It panics on an unknown model, like JS does.
func RealPrice(t int, day float64, season int) float64 {
	return realPriceEv(t, day, eventMul(floor(fmax(0, day)), season).Price)
}

// realPriceEv is RealPrice with the day's event price multiplier given.
func realPriceEv(t int, day, evPrice float64) float64 {
	c := &Models[t-1]
	d := floor(fmax(0, day))
	age := d - float64(c.Release)
	launch := 1 + cLaunch*launchExp(fmax(0, age))
	behind := CurrentGen(d) - c.Gen
	if behind < 0 {
		behind = 0
	}
	return c.Price * launch * powInt(powGenDisTable, cGenDiscount, behind) * Demand(d) *
		(1 + cJitter*Noise(d, 10+t)) * evPrice
}

// Package miner is the economy of Coblyn, a GPU mining game. It is
// the Gno twin of web/miner/economy.js: the season realm replays each
// player's logged actions with this package, so it must behave exactly like
// the JavaScript the browser runs.
//
// The golden vectors in z_vectors_test.gno are generated from economy.js by
// tools/miner-vectors.mjs. Change a rule in either file and regenerate them.
//
// Conventions kept from the JavaScript:
//   - Time is int64 milliseconds (now, Last, SeasonStart, ...).
//   - Money and value are float64, computed in the same order of operations.
//   - Math.round(x) is jsRound (nearest, ties toward +Inf), Math.floor is
//     math.Floor, `**` is math.Pow, Math.exp is math.Exp.
//   - JS throws Error(msg); here the same msg comes back as an error value.
//     As in JS, actions settle first, so on error the settle has already
//     been applied to the state.
//
// Differences on purpose:
//   - settle and Rates group installed cards by (model, overclock), so the
//     cost of one settle step grows with the number of distinct models, not
//     with the number of cards. Results equal the JS up to float rounding.
//   - Inputs that only crash the JS (unknown model, unknown card id for
//     overclock, unknown offer index) return errors here.
//   - migrate (save versions 1 and 2) and UI helpers are not ported; chain
//     state starts at version 3.
package miner

import "math"

// Token is the in-game currency name (working name).
const Token = "BLK"

// DisplayScale: network and block reward are shown scaled by this factor.
const DisplayScale = 1000

// Version of the state format (JS `v`).
const Version = 3

const (
	Hour int64 = 3600000
	Day  int64 = 24 * Hour
	// Step is the settle step: one hour, the same in JS.
	Step int64 = 60 * 60000
)

// Hot-path copies of the parameters below. Reading a package variable costs
// gas on every access, a constant costs nothing. Every use keeps a variable
// operand next to the constant, so no constant folding changes a result
// (1 + RGBCfg.Premium, for example, is left on the variable).
const (
	cR0           = 5.0
	cHalvingDays  = 7
	cN0           = 150.0
	cGrowth       = 0.07
	cCapitulation = 0.25
	cCapDays      = 3.0
	cSeasonDays   = 28

	cValuePerHalving = 1.8
	cValueRun        = 0.12
	cValueJitter     = 0.03

	cLaunch      = 0.35
	cLaunchDays  = 2.0
	cGenDiscount = 0.82
	cDemandLow   = 0.92
	cDemandRun   = 0.16
	cJitter      = 0.04

	cRigBase   = 400.0
	cRigGrowth = 1.9

	cOCMax  = 3
	cOCMH   = 0.12
	cOCW    = 0.22
	cOCCost = 0.3

	cRGBSellBack = 0.62
	cRGBMinCls   = 2

	cBoostX    = 3.0
	cBoostDays = 5.0
	cBoostFull = 14.0

	nSeries = 4
	nModels = 16
	nEvents = 6
)

// NetParams is JS NET.
type NetParams struct {
	R0           float64 // block reward (BLK / block), 1 block = 1 min
	HalvingDays  int
	N0           float64 // network hash at day 0 (MH/s)
	Growth       float64 // growth per day
	Capitulation float64 // share of the network that leaves after a halving
	CapDays      float64 // days to recover from the capitulation
	SeasonDays   int
}

var Net = NetParams{R0: cR0, HalvingDays: cHalvingDays, N0: cN0, Growth: cGrowth, Capitulation: cCapitulation, CapDays: cCapDays, SeasonDays: cSeasonDays}

// ValueParams is JS VALUE (the BLK value index).
type ValueParams struct{ PerHalving, Run, Jitter float64 }

var ValueCfg = ValueParams{PerHalving: cValuePerHalving, Run: cValueRun, Jitter: cValueJitter}

// MarketParams is JS MARKET.
type MarketParams struct {
	Launch, LaunchDays, GenDiscount, DemandLow, DemandRun, Jitter float64
}

var Market = MarketParams{Launch: cLaunch, LaunchDays: cLaunchDays, GenDiscount: cGenDiscount, DemandLow: cDemandLow, DemandRun: cDemandRun, Jitter: cJitter}

// SeriesInfo is one entry of JS SERIES (one card generation).
type SeriesInfo struct {
	Name  string
	Color int
}

var Series = []SeriesInfo{
	{"Spark", 0x9fb4c8},
	{"Volt", 0x6fbf8e},
	{"Storm", 0xb48ce0},
	{"Quasar", 0xf2a23a},
}

// ClassInfo is one entry of JS CLASSES.
type ClassInfo struct {
	Name   string
	MH     float64
	Eff    float64
	PPM    float64
	Unlock float64
}

var Classes = []ClassInfo{
	{"Lite", 8, 0.1, 3.1, 0},
	{"Core", 20, 0.15, 5.3, 300},
	{"Pro", 50, 0.22, 9.0, 3000},
	{"Max", 120, 0.32, 15.3, 20000},
}

// Per generation multipliers (JS GEN).
const (
	genMH     = 1.55
	genEff    = 1.6
	genUnlock = 3
)

// Model is one card model (an entry of JS CARDS). T = Gen*4 + Cls + 1.
type Model struct {
	T, Gen, Cls int
	Name        string
	MH          float64
	W           float64
	Price       float64
	Release     int // day the model is released
	Unlock      float64
	Color       int
	VT          int // visual size 1..7
}

// Models is JS CARDS: 16 models, index t-1.
var Models = genModels()

func genModels() []Model {
	out := []Model{}
	for g := 0; g < len(Series); g++ {
		s := Series[g]
		for k := 0; k < len(Classes); k++ {
			c := Classes[k]
			mh := jsRound(c.MH * math.Pow(genMH, float64(g)))
			eff := c.Eff * math.Pow(genEff, float64(g))
			vt := 1 + k + g
			if vt > 7 {
				vt = 7
			}
			out = append(out, Model{
				T:       g*4 + k + 1,
				Gen:     g,
				Cls:     k,
				Name:    s.Name + " " + c.Name,
				MH:      mh,
				W:       jsRound(mh / eff),
				Price:   jsRound(c.PPM * mh),
				Release: g * Net.HalvingDays,
				Unlock:  c.Unlock * math.Pow(genUnlock, float64(g)),
				Color:   s.Color,
				VT:      vt,
			})
		}
	}
	return out
}

// ModelOf is JS card(t); ok is false for an unknown model.
func ModelOf(t int) (Model, bool) {
	if t < 1 || t > len(Models) {
		return Model{}, false
	}
	return Models[t-1], true
}

func validModel(t int) bool { return t >= 1 && t <= nModels }

