	ErrNoOffer     = errors.New("No such offer")      // JS crashes instead
)

// NewState is JS newState(now): a fresh season 1 player.
func NewState(now int64) *State {
	return &State{
		Wallet:       StartWallet,
		Last:         now,
		LastClaim:    now,
		SeasonStart:  now,
		Room:         0,
		Rigs:         [][]int{{1, 0, 0, 0}},
		Cards:        map[int]*Card{1: {T: 1, OC: 0}},
		NextID:       2,
		Watch:        0,
		Born:         now,
		Season:       1,
		History:      []HistoryEntry{},
		OffersBought: []string{},
	}
}

func (st *State) season() int {
	if st.Season == 0 {
		return 1
	}
	return st.Season
}

// DayOf is JS dayOf(st, now): fractional season day of now.
func (st *State) DayOf(now int64) float64 {
	return float64(now-st.SeasonStart) / float64(Day)
}

// Px converts a real price to BLK on the day of now (JS px).
func (st *State) Px(now int64, base float64) float64 {
	vi, _ := st.viEv(st.DayOf(now))
	return pxVI(vi, base)
}

// viEv is ValueIndex(day) and eventMul(day, season) through the day cache:
// a Collect prices cards, overclocks and offers on the same few days the
// settles walk.
func (st *State) viEv(day float64) (float64, Event) {
	return st.dayInputs(floor(day), day, st.season())
}

// pxVI is Px with the value index of the day already known.
func pxVI(vi, base float64) float64 {
	return fmax(1, jsRound(base/vi))
}

// CardPrice is JS cardPrice(st, t, now). It panics on an unknown model.
func (st *State) CardPrice(t int, now int64) float64 {
	day := st.DayOf(now)
	vi, ev := st.viEv(day) // eventMul(floor(max(0, day))) is ev for day >= 0, none before
	if day < 0 {
		ev = noEvent
	}
	return pxVI(vi, realPriceEv(t, day, ev.Price))
}

// EditionPrice is JS editionPrice(st, t, now, rgb).
func (st *State) EditionPrice(t int, now int64, rgb bool) float64 {
	if rgb {
		return jsRound(st.CardPrice(t, now) * (1 + RGBCfg.Premium))
	}
	return st.CardPrice(t, now)
}

// CardStats is JS cardStats(c): hash (MH/s) and power (W) with overclock.
func CardStats(c Card) (mh, w float64) {
	b := &Models[c.T-1] // a pointer: copying the Model costs gas
	return b.MH * (1 + cOCMH*float64(c.OC)), b.W * (1 + cOCW*float64(c.OC))
}

// Boost is JS boost(st, day): the newcomer boost for a player who joined
// the season late.
func (st *State) Boost(day float64) float64 {
	joined := st.DayOf(st.Born)
	age := day - joined
	return 1 + cBoostX*fmin(1, joined/cBoostFull)*fmax(0, 1-age/cBoostDays)
}

// ElecPrice is JS elecPrice(st, day): BLK per kWh.
func (st *State) ElecPrice(day float64) float64 {
	return (Rooms[st.Room].Elec / ValueIndex(day)) * eventMul(day, st.season()).Elec
}

// Installed is JS installed(st): card ids in rig/slot order.
func (st *State) Installed() []int {
	out := []int{}
	for _, rig := range st.Rigs {
		for _, id := range rig {
			if id != 0 {
				out = append(out, id)
			}
		}
	}
	return out
}

// group is the installed cards of one (model, overclock) pair.
type group struct {
	t, oc, n int
	mh, w    float64 // per card
	wk       float64 // w/1000 (kW per card), the same division settle did per step
	hn, wn   float64 // n*mh, n*w
}

// groups returns the installed cards counted per (model, overclock). The
// first call walks the rigs in slot order; the result is kept in the state
// and the card methods (buy, sell, overclock, rig swap) update it in place,
// so a Collect that replays many actions walks the 80 cards of a big farm
// once instead of once per settle. The order of the groups (first seen,
// then added at the end) only changes float rounding, as grouping itself
// does (see the package comment). It is kept only while every card is
// installed (the game's invariant): otherwise a later overclock of a card
// outside the rigs could not be told apart, so it is walked every time.
func (st *State) groups() []group {
	if st.gsOK {
		return st.gs
	}
	gs, installed := st.walkGroups()
	if installed == len(st.Cards) {
		st.gs, st.gsOK = gs, true
	}
	return gs
}

// gAdd changes the count of group (t, oc) by d (cache only).
func (st *State) gAdd(t, oc, d int) {
	if !st.gsOK {
		return
	}
	gs := st.gs
	for i := range gs {
		g := &gs[i]
		if g.t == t && g.oc == oc {
			g.n += d
			if g.n == 0 {
				st.gs = append(gs[:i], gs[i+1:]...)
				return
			}
			g.hn = float64(g.n) * g.mh
			g.wn = float64(g.n) * g.w
			return
		}
	}
	if d < 0 { // not counted: the cache is wrong, drop it
		st.Touch()
		return
	}
	g := group{t: t, oc: oc, n: d}
	g.mh, g.w = CardStats(Card{T: t, OC: oc})
	g.wk = g.w / 1000
	g.hn = float64(g.n) * g.mh
	g.wn = float64(g.n) * g.w
	st.gs = append(gs, g)
}

// walkGroups walks the rigs in slot order and counts cards per (model,
// overclock); installed is the number of cards in the rigs. Gas: one map
// read and two field reads per card, no search.
func (st *State) walkGroups() (gs []group, installed int) {
	// Cards come from the actions, so 1 <= T <= 16 and OC >= 0; only OC
	// can leave the table (see OCMany), those cards go to the slow path.
	var cnt [8 * nModels]int
	order := make([]int, 0, 8)
	var odd []group
	for _, rig := range st.Rigs {
		for _, id := range rig {
			if id == 0 {
				continue
			}
			installed++
			c := st.Cards[id]
			oc := c.OC
			if oc < 8 {
				k := (c.T-1)*8 + oc
				if cnt[k] == 0 {
					order = append(order, k)
				}
				cnt[k]++
				continue
			}
			found := false
			for i := range odd {
				if odd[i].t == c.T && odd[i].oc == oc {
					odd[i].n++
					found = true
					break
				}
			}
			if !found {
				odd = append(odd, group{t: c.T, oc: oc, n: 1})
			}
		}
	}
	gs = make([]group, len(order), len(order)+len(odd))
	for i, k := range order {
		gs[i].t = k/8 + 1
		gs[i].oc = k % 8
		gs[i].n = cnt[k]
	}
	gs = append(gs, odd...)
	for i := range gs {
		g := &gs[i]
		g.mh, g.w = CardStats(Card{T: g.t, OC: g.oc})
		g.wk = g.w / 1000
		g.hn = float64(g.n) * g.mh
		g.wn = float64(g.n) * g.w
	}
	return gs, installed
}

// Rates is the result of JS rates(st, day). On lists the ids of the cards
// that run (profitable), in installed order.
type Rates struct {
	On    []int
	Hash  float64
	Watts float64
	Gross float64
	Elec  float64
	Net   float64
	PerMH float64
	R     float64
	N     float64
	Boost float64
}

// dayEnv holds the per-day inputs of a settle step.
type dayEnv struct {
	r, n, e, perMH, boost float64
}

// envAt: vi = ValueIndex(day), ev = the day's event multipliers,
// roomElec = Rooms[st.Room].Elec.
func (st *State) envAt(day, vi float64, ev Event, roomElec float64) dayEnv {
	ep := Epoch(day)
	r := cR0 / powInt(pow2Table, 2, ep)
	n := netHashAt(day, ep, ev)
	e := (roomElec / vi) * ev.Elec
	b := st.Boost(day)
	perMH := ((60 * r) / n) * b * ev.Hash
	return dayEnv{r: r, n: n, e: e, perMH: perMH, boost: b}
}

func (st *State) env(day float64) dayEnv {
	return st.envAt(day, ValueIndex(day), eventMul(day, st.season()), Rooms[st.Room].Elec)
}

// sumGroups adds up the running cards: total hash and watts.
func sumGroups(gs []group, env dayEnv) (h, w float64) {
	return sumGroupsAt(gs, env.perMH, env.e)
}

func sumGroupsAt(gs []group, perMH, e float64) (h, w float64) {
	for i := range gs {
		g := &gs[i]
		if g.mh*perMH > g.wk*e {
			h += g.hn
			w += g.wn
		}
	}
	return h, w
}

// Rates is JS rates(st, day).
func (st *State) Rates(day float64) Rates {
	env := st.env(day)
	gs := st.groups()
	h, w := sumGroups(gs, env)
	on := []int{}
	for _, id := range st.Installed() {
		mh, cw := CardStats(*st.Cards[id])
		if mh*env.perMH > (cw/1000)*env.e {
			on = append(on, id)
		}
	}
	gross := h * env.perMH
	elec := (w / 1000) * env.e
	return Rates{On: on, Hash: h, Watts: w, Gross: gross, Elec: elec, Net: gross - elec,
		PerMH: env.perMH, R: env.r, N: env.n, Boost: env.boost}
}

// Economics is the result of JS cardEconomics.
type Economics struct {
	Gross, Elec, Net float64
	Profitable       bool
}

// CardEconomics is JS cardEconomics(st, c, day): one card's hourly result.
func (st *State) CardEconomics(c Card, day float64) Economics {
	return cardEcon(c, st.env(day))
}

func cardEcon(c Card, env dayEnv) Economics {
	mh, w := CardStats(c)
	gross := mh * env.perMH
	elec := (w / 1000) * env.e
	return Economics{Gross: gross, Elec: elec, Net: gross - elec, Profitable: gross > elec}
}

// ---------- season ----------

// SeasonEnd is JS seasonEnd(st).
func (st *State) SeasonEnd() int64 {
	return st.SeasonStart + cSeasonDays*Day
}

// SeasonOver is JS seasonOver(st, now).
func (st *State) SeasonOver(now int64) bool { return now >= st.SeasonEnd() }

// BadgeOf is JS badgeOf(value): the highest badge reached, ok=false if none.
func BadgeOf(value float64) (Badge, bool) {
	var b Badge
	ok := false
	for _, x := range Badges {
		if value >= x.Min {
			b = x
			ok = true
		}
	}
	return b, ok
}

// NewSeason is JS newSeason(st, now, event): settles, writes the season to
// history and returns the next season's state (seasonStart = now, as in JS;
// a realm with shared seasons sets SeasonStart/Born itself). event "" is
// JS null.
func (st *State) NewSeason(now int64, event string) *State {
	st.Settle(now)
	badge, ok := BadgeOf(st.Value)
	name := ""
	start := []int{1}
	if ok {
		name = badge.Name
		start = badge.Start
	}
	history := []HistoryEntry{}
	history = append(history, st.History...)
	history = append(history, HistoryEntry{Season: st.season(), Value: jsRound(st.Value), Mined: jsRound(st.Mined),
		Badge: name, Room: st.Room, Event: event})
	next := NewState(now)
	next.Season = st.season() + 1
	next.History = history
	next.Cards = map[int]*Card{}
	next.Rigs = [][]int{{0, 0, 0, 0}}
	for k, t := range start {
		next.Cards[k+1] = &Card{T: t}
		next.Rigs[0][k] = k + 1
	}
	next.NextID = len(start) + 1
	return next
}

// ---------- time ----------

// WatchHours is JS watchHours(st).
func (st *State) WatchHours() int { return WatchTiers[st.Watch] }

// Settle is JS settle(st, now): mines from Last up to now, capped by the
// watch window after the last collect and by the season end, in one hour
// steps. Returns the BLK mined.
func (st *State) Settle(now int64) float64 {
	end := now
	if w := st.LastClaim + int64(st.WatchHours())*Hour; w < end {
		end = w
	}
	if se := st.SeasonEnd(); se < end {
		end = se
	}
	t := st.Last
	var got, elec, value float64
	if t < end {
		gs := st.groups()
		season := st.season()
		roomElec := Rooms[st.Room].Elec
		// boost(st, day) = 1 + X*min(1, joined/Full)*max(0, 1-(day-joined)/Days)
		joined := st.DayOf(st.Born)
		boostJ := cBoostX * fmin(1, joined/cBoostFull)
		ss := float64(st.SeasonStart)
		// The value index and the event change once a day (st.dc keeps
		// them across settles), the reward once an epoch. The day's bounds
		// [dayLo, dayHi) start empty so the first step fills them.
		dayLo, dayHi := 1.0, 0.0
		cacheEp := -1
		var vi, r, e, evHash, evNet float64
		// The step is netHashAt, boost and sumGroupsAt inlined (same
		// operations in the same order): function calls cost gas.
		for t < end {
			dt := Step
			if end-t < dt {
				dt = end - t
			}
			day := (float64(t) + float64(dt)/2 - ss) / float64(Day)
			if !(day >= dayLo && day < dayHi) {
				fd := floor(day)
				dayLo, dayHi = fd, fd+1
				var ev Event
				vi, ev = st.dayInputs(fd, day, season)
				e = (roomElec / vi) * ev.Elec
				evHash, evNet = ev.Hash, ev.Net
			}
			d := day // fmax(0, day)
			if 0 > day {
				d = 0
			}
			ep := int(d / cHalvingDays) // Epoch(day): d >= 0, so int() is floor
			if ep != cacheEp {
				cacheEp = ep
				r = cR0 / powInt(pow2Table, 2, ep)
			}
			n := cN0 * fexp(cGrowth*d)
			since := d - float64(ep*cHalvingDays)
			if ep > 0 && since < cCapDays {
				n *= 1 - cCapitulation*(1-since/cCapDays)
			}
			n = n * evNet
			x := 1 - (day-joined)/cBoostDays
			if 0 > x {
				x = 0
			}
			b := 1 + boostJ*x
			perMH := ((60 * r) / n) * b * evHash
			var h, w float64
			for i := range gs {
				g := &gs[i]
				if g.mh*perMH > g.wk*e {
					h += g.hn
					w += g.wn
				}
			}
			gross := h * perMH
			el := (w / 1000) * e
			net := gross - el
			fdt := float64(dt)
			q := (net * fdt) / float64(Hour)
			got += q
			value += q * vi
			elec += (el * fdt) / float64(Hour)
			t += dt
		}
	}
	st.Pool += got
	st.Mined += got
	st.Value = st.Value + value
	st.SpentElec += elec
	if now > st.Last {
		st.Last = now
	}
	return got
}

// dayCache keeps the inputs of one whole day (see dayInputs).
type dayCache struct {
	ok     bool
	fd     float64
	season int
	vi     float64
	ev     Event
}

// dayInputs returns ValueIndex(day) and eventMul(day, season), which only
// depend on fd = floor(day) and the season, from st.dc when that day was
// the last one asked for: the settle of each replayed action and the claim
// mostly fall on the same day.
func (st *State) dayInputs(fd, day float64, season int) (float64, Event) {
	c := &st.dc
	if c.ok && c.fd == fd && c.season == season {
		return c.vi, c.ev
	}
	vi, ev := ValueIndex(day), eventMul(day, season)
	*c = dayCache{ok: true, fd: fd, season: season, vi: vi, ev: ev}
	return vi, ev
}

// Stopped is JS stopped(st, now): mining has stopped until the next collect.
func (st *State) Stopped(now int64) bool {
	return now >= st.LastClaim+int64(st.WatchHours())*Hour
}

// Claim is JS claim(st, now): settles and moves the pool to the wallet.
func (st *State) Claim(now int64) float64 {
	st.Settle(now)
	got := st.Pool
	st.Wallet += got
	st.Pool = 0
	st.LastClaim = now
	return got
}

// ---------- market ----------

// Unlocked is JS unlocked(st, t).
func (st *State) Unlocked(t int) bool {
	return validModel(t) && st.Value >= Models[t-1].Unlock
}

// Available is JS available(st, t, now).
func (st *State) Available(t int, now int64) bool {
	return Released(t, st.DayOf(now)) && st.Unlocked(t)
}

func (st *State) spend(p float64) error {
	if st.Wallet < p {
		return ErrNotEnough
	}
	st.Wallet -= p
	return nil
}

// FreeSlot is JS freeSlot(st); ok=false when every slot is taken.
func (st *State) FreeSlot() (rig, slot int, ok bool) {
	for r, row := range st.Rigs {
		for s, id := range row {
			if id == 0 {
				return r, s, true
			}
		}
	}
	return 0, 0, false
}

// BuyCard is JS buyCard(st, t, now, null, false, rgb): buys model t at the
// market price into the first free slot. Returns the new card id.
func (st *State) BuyCard(t int, now int64, rgb bool) (int, error) {
	return st.buyCard(t, now, 0, false, false, rgb)
}

// BuyCardAt is JS buyCard with an explicit price (offer=true skips the lock).
func (st *State) BuyCardAt(t int, now int64, price float64, offer, rgb bool) (int, error) {
	return st.buyCard(t, now, price, true, offer, rgb)
}

func (st *State) buyCard(t int, now int64, price float64, hasPrice, offer, rgb bool) (int, error) {
	st.Settle(now)
	if !validModel(t) {
		return 0, ErrNoModel
	}
	if !Released(t, st.DayOf(now)) {
		return 0, ErrNotReleased
	}
	if rgb && !RGBOk(t) {
		return 0, ErrNoRGB
	}
	if !hasPrice {
		price = st.EditionPrice(t, now, rgb)
	}
	if !st.Unlocked(t) && !offer {
		return 0, ErrLocked
	}
	r, s, ok := st.FreeSlot()
	if !ok {
		return 0, ErrNoSlot
	}
	if err := st.spend(price); err != nil {
		return 0, err
	}
	id := st.NextID
	st.NextID++
	st.Cards[id] = &Card{T: t, RGB: rgb}
	st.Rigs[r][s] = id
	st.gAdd(t, 0, 1)
	return id, nil
}

// SellValue is JS sellValue(st, c, now).
func (st *State) SellValue(c Card, now int64) float64 {
	return sellValueAt(c, st.CardPrice(c.T, now))
}

func sellValueAt(c Card, cardPrice float64) float64 {
	back := SellBack
	if c.RGB {
		back = cRGBSellBack
	}
	return floor(cardPrice * back)
}

// SellCard is JS sellCard(st, id, now). Returns the BLK received.
func (st *State) SellCard(id int, now int64) (float64, error) {
	st.Settle(now)
	c, ok := st.Cards[id]
	if !ok {
		return 0, ErrNoCard
	}
	for _, rig := range st.Rigs {
		for i, x := range rig {
			if x == id {
				rig[i] = 0
				break
			}
		}
	}
	delete(st.Cards, id)
	st.gAdd(c.T, c.OC, -1)
	v := st.SellValue(*c, now)
	st.Wallet += v
	return v, nil
}

// OCPrice is JS ocPrice(st, c, now); ok=false at max overclock (JS null).
func (st *State) OCPrice(c Card, now int64) (float64, bool) {
	vi, _ := st.viEv(st.DayOf(now))
	return ocPriceVI(c, vi)
}

func ocPriceVI(c Card, vi float64) (float64, bool) {
	if c.OC >= cOCMax {
		return 0, false
	}
	return pxVI(vi, Models[c.T-1].Price*cOCCost*float64(c.OC+1)), true
}

// Overclock is JS overclock(st, id, now). Returns the price paid.
func (st *State) Overclock(id int, now int64) (float64, error) {
	st.Settle(now)
	c, ok := st.Cards[id]
	if !ok {
		return 0, ErrNoCard
	}
	p, ok := st.OCPrice(*c, now)
	if !ok {
		return 0, ErrMaxOC
	}
	if err := st.spend(p); err != nil {
		return 0, err
	}
	st.gAdd(c.T, c.OC, -1)
	c.OC++
	st.gAdd(c.T, c.OC, 1)
	return p, nil
}

// RigPrice is JS rigPrice(st, now); ok=false when the room is full.
func (st *State) RigPrice(now int64) (float64, bool) {
	if len(st.Rigs) >= Rooms[st.Room].Rigs {
		return 0, false
	}
	return st.Px(now, cRigBase*powInt(powRigTable, cRigGrowth, len(st.Rigs)-1)), true
}

// BuyRig is JS buyRig(st, now). Returns the price paid.
func (st *State) BuyRig(now int64) (float64, error) {
	st.Settle(now)
	p, ok := st.RigPrice(now)
	if !ok {
		return 0, ErrRoomFull
	}
	if err := st.spend(p); err != nil {
		return 0, err
	}
	st.Rigs = append(st.Rigs, make([]int, Rooms[st.Room].Slots))
	return p, nil
}

// RoomPrice is JS roomPrice(st, now); ok=false in the largest room.
func (st *State) RoomPrice(now int64) (float64, bool) {
	if st.Room+1 >= len(Rooms) {
		return 0, false
	}
	return st.Px(now, Rooms[st.Room+1].Price), true
}

// MoveRoom is JS moveRoom(st, now). Returns the price paid.
func (st *State) MoveRoom(now int64) (float64, error) {
	st.Settle(now)
	p, ok := st.RoomPrice(now)
	if !ok {
		return 0, ErrLargestRoom
	}
	if err := st.spend(p); err != nil {
		return 0, err
	}
	st.Room++
	slots := Rooms[st.Room].Slots
	for i, rig := range st.Rigs {
		for len(rig) < slots {
			rig = append(rig, 0)
		}
		st.Rigs[i] = rig
	}
	return p, nil
}

// WatchPrice is JS watchPrice(st, now); ok=false at the top tier.
func (st *State) WatchPrice(now int64) (float64, bool) {
	if st.Watch+1 >= len(WatchTierPrice) {
		return 0, false
	}
	return st.Px(now, WatchTierPrice[st.Watch+1]), true
}

// UpgradeWatch is JS upgradeWatch(st, now). Returns the price paid.
func (st *State) UpgradeWatch(now int64) (float64, error) {
	st.Settle(now)
	p, ok := st.WatchPrice(now)
	if !ok {
		return 0, ErrTopWatch
	}
	if err := st.spend(p); err != nil {
		return 0, err
	}
	st.Watch++
	return p, nil
}

// Offer is one daily offer (JS offers item).
type Offer struct {
	K     int
	Day   int
	T     int
	Price float64
	Early bool
	Off   float64
	RGB   bool
}

// Offers is JS offers(st, now): the same three offers for everyone each
// day; the third is early access to the next locked model when there is
// one. Returns nil before the season starts (JS crashes there).
func (st *State) Offers(now int64) []Offer {
	day := st.DayOf(now)
	fd := floor(day)
	d := int(fd)
	// available(st, t, now) and the first released locked model, in one
	// pass by index (copying each Model costs gas).
	open := []int{}
	next := 0
	for i := range Models {
		m := &Models[i]
		if day < float64(m.Release) {
			continue
		}
		if st.Value >= m.Unlock {
			open = append(open, m.T)
		} else if next == 0 {
			next = m.T
		}
	}
	if len(open) == 0 && next == 0 {
		return nil
	}
	pool := []int{}
	from := len(open) - 6
	if from < 0 {
		from = 0
	}
	pool = append(pool, open[from:]...)
	list := []Offer{}
	for k := 0; k < 3; k++ {
		early := k == 2 && next != 0
		div := len(pool)
		if div < 1 {
			div = 1
		}
		pick := int(floor((Noise(fd, 50+k)+1)/2*float64(len(pool)))) % div
		var t int
		if early {
			t = next
		} else if len(pool) > 0 {
			t = pool[pick]
			rest := []int{}
			for i, x := range pool {
				if i != pick {
					rest = append(rest, x)
				}
			}
			pool = rest
		} else if len(open) > 0 {
			t = open[0]
		} else {
			return nil
		}
		off := 0.0
		if !early {
			off = 0.15 + jsRound((Noise(fd, 60+k)+1)/2*4)*0.05
		}
		rgb := !early && RGBOk(t) && Noise(fd, 70+k) > 0.2
		mul := 1 - off
		if early {
			mul = 1.25
		}
		price := fmax(1, jsRound(st.EditionPrice(t, now, rgb)*mul))
		list = append(list, Offer{K: k, Day: d, T: t, Price: price, Early: early, Off: off, RGB: rgb})
	}
	return list
}

// BuyOffer is JS buyOffer(st, k, now). The offers are read before the
// settle, as in JS. Returns the new card id.
func (st *State) BuyOffer(k int, now int64) (int, error) {
	os := st.Offers(now)
	if k < 0 || k >= len(os) {
		return 0, ErrNoOffer
	}
	o := os[k]
	prefix := strconv.Itoa(o.Day) + ":"
	key := prefix + strconv.Itoa(k)
	for _, x := range st.OffersBought {
		if x == key {
			return 0, ErrOfferTaken
		}
	}
	id, err := st.buyCard(o.T, now, o.Price, true, true, o.RGB)
	if err != nil {
		return 0, err
	}
	kept := []string{}
	for _, x := range st.OffersBought {
		if strings.HasPrefix(x, prefix) {
			kept = append(kept, x)
		}
	}
	st.OffersBought = append(kept, key)
	return id, nil
}

// ---------- turn a rig into one model ----------

// RigPlan is the result of JS rigPlan (and rigSwap, with IDs).
type RigPlan struct {
	Buys   int
	Keep   int
	Sell   []int
	Refund float64
	Price  float64
	Cost   float64
	Net    float64
	LostOC int
	IDs    []int // new card ids (RigSwap only)
}

// RigPlan is JS rigPlan(st, r, t, now, rgb): fill rig r with model t.
func (st *State) RigPlan(r, t int, now int64, rgb bool) (RigPlan, error) {
	if r < 0 || r >= len(st.Rigs) {
		return RigPlan{}, ErrNoRig
	}
	if !validModel(t) {
		return RigPlan{}, ErrNoModel
	}
	if !Released(t, st.DayOf(now)) {
		return RigPlan{}, ErrNotReleased
	}
	if !st.Unlocked(t) {
		return RigPlan{}, ErrLocked
	}
	if rgb && !RGBOk(t) {
		return RigPlan{}, ErrNoRGB
	}
	price := st.EditionPrice(t, now, rgb)
	p := RigPlan{Sell: []int{}, Price: price}
	// card price per model, computed once (gas); same value every time
	var memo [17]float64
	for _, id := range st.Rigs[r] {
		var c *Card
		if id != 0 {
			c = st.Cards[id]
		}
		if c != nil && c.T == t && c.RGB == rgb {
			p.Keep++
			continue
		}
		if c != nil {
			if memo[c.T] == 0 {
				memo[c.T] = st.CardPrice(c.T, now)
			}
			p.Refund += sellValueAt(*c, memo[c.T])
			p.LostOC += c.OC
			p.Sell = append(p.Sell, id)
		}
		p.Buys++
	}
	p.Cost = float64(p.Buys) * price
	p.Net = float64(p.Buys)*price - p.Refund
	return p, nil
}

// RigSwap is JS rigSwap(st, r, t, now, rgb).
func (st *State) RigSwap(r, t int, now int64, rgb bool) (RigPlan, error) {
	st.Settle(now)
	p, err := st.RigPlan(r, t, now, rgb)
	if err != nil {
		return p, err
	}
	if p.Buys == 0 {
		return p, ErrSameModel
	}
	if st.Wallet < p.Net {
		return p, ErrNotEnough
	}
	rig := st.Rigs[r]
	for _, id := range p.Sell {
		for i, x := range rig {
			if x == id {
				rig[i] = 0
				break
			}
		}
		if c, ok := st.Cards[id]; ok {
			st.gAdd(c.T, c.OC, -1)
		}
		delete(st.Cards, id)
	}
	st.Wallet -= p.Net
	p.IDs = []int{}
	for k, id := range rig {
		if id != 0 {
			continue
		}
		nid := st.NextID
		st.NextID++
		st.Cards[nid] = &Card{T: t, RGB: rgb}
		st.gAdd(t, 0, 1)
		rig[k] = nid
		p.IDs = append(p.IDs, nid)
	}
	return p, nil
}

// ---------- overclock many ----------

// OCItem is one entry of an overclock plan.
type OCItem struct {
	ID    int
	Price float64
	Gain  float64
}

// OCPlan is the result of JS ocPlan.
type OCPlan struct {
	Items []OCItem
	Cost  float64
	Gain  float64
}

// OCPlan is JS ocPlan(st, ids, now): the cards whose next overclock level
// raises the hourly net, fastest payback first (stable, like JS sort).
// Duplicate ids are ignored after their first occurrence.
func (st *State) OCPlan(ids []int, now int64) OCPlan {
	day := st.DayOf(now)
	vi, ev := st.viEv(day)
	env := st.envAt(day, vi, ev, Rooms[st.Room].Elec)
	items := []OCItem{}
	// A card listed twice counts once (JS iterates new Set(ids): first
	// occurrence order).
	seen := make(map[int]bool, len(ids))
	for _, id := range ids {
		if seen[id] {
			continue
		}
		seen[id] = true
		c, ok := st.Cards[id]
		if !ok {
			continue
		}
		price, ok := ocPriceVI(*c, vi)
		if !ok {
			continue
		}
		before := cardEcon(*c, env)
		up := *c
		up.OC++
		after := cardEcon(up, env)
		a, b := 0.0, 0.0
		if after.Profitable {
			a = after.Net
		}
		if before.Profitable {
			b = before.Net
		}
		gain := a - b
		if gain > 0 {
			items = append(items, OCItem{ID: id, Price: price, Gain: gain})
		}
	}
	// stable insertion sort by price/gain
	for i := 1; i < len(items); i++ {
		x := items[i]
		j := i
		for j > 0 && x.Price/x.Gain-items[j-1].Price/items[j-1].Gain < 0 {
			items[j] = items[j-1]
			j--
		}
		items[j] = x
	}
	p := OCPlan{Items: items}
	for _, x := range items {
		p.Cost += x.Price
	}
	for _, x := range items {
		p.Gain += x.Gain
	}
	return p
}

// OCResult is the result of JS ocMany.
type OCResult struct {
	N    int
	Cost float64
	Gain float64
	IDs  []int
	All  int
}

// OCMany is JS ocMany(st, ids, now): overclocks as many of the planned
// cards as the wallet allows, in plan order.
func (st *State) OCMany(ids []int, now int64) (OCResult, error) {
	st.Settle(now)
	p := st.OCPlan(ids, now)
	if len(p.Items) == 0 {
		return OCResult{}, ErrNoOCGain
	}
	res := OCResult{IDs: []int{}, All: len(p.Items)}
	for _, x := range p.Items {
		if st.Wallet < x.Price {
			continue
		}
		st.Wallet -= x.Price
		c := st.Cards[x.ID]
		st.gAdd(c.T, c.OC, -1)
		c.OC++
		st.gAdd(c.T, c.OC, 1)
		res.N++
		res.Cost += x.Price
		res.Gain += x.Gain
		res.IDs = append(res.IDs, x.ID)
	}
	if res.N == 0 {
		return res, ErrNotEnough
	}
	return res, nil
}

package miner

import (
	"chain"
	"strings"
)

// Admin functions: the smallest honest upgrade path. None of them can edit a
// player's values, log, history or badges.
//
//   - Halt(reason): one way. Join and Collect panic with "Halted: <reason>"
//     from then on; nothing else changes. State, Season, PlayerSeason,
//     SeasonResult and Render keep working: every player's stored
//     projection is their result, and season results become final at the
//     season end as usual (computed on read, since no Collect stores the
//     cutoffs any more).
//   - SetSuccessor(path): records the package path of the realm that takes
//     over (shown by Render and Season()). It may be set before or after a
//     halt, and corrected.
//   - ProposeAdmin(addr), then AcceptAdmin() by addr: hands the admin role
//     over in two steps, so a typo cannot lose it.

const (
	MaxReasonBytes    = 200
	MaxSuccessorBytes = 128
)

var (
	halted       bool
	haltReason   string
	successor    string  // package path of the next realm, "" = none
	pendingAdmin address // proposed by ProposeAdmin, "" = none
)

func onlyAdmin(caller address) {
	if caller != admin {
		panic("admin only")
	}
}

func notHalted() {
	if halted {
		panic("Halted: " + haltReason)
	}
}

// Halt stops Join and Collect for good, with a reason shown to players
// (1 to MaxReasonBytes bytes, one line). Admin only.
func Halt(cur realm, reason string) {
	onlyAdmin(cur.Previous().Address())
	if halted {
		panic("already halted")
	}
	if reason == "" || len(reason) > MaxReasonBytes {
		panic("reason: 1 to 200 bytes")
	}
	for i := 0; i < len(reason); i++ {
		if reason[i] < 0x20 || reason[i] == 0x7f {
			panic("reason: one line, no control characters")
		}
	}
	halted = true
	haltReason = reason
	chain.Emit("Halt", "reason", reason)
}

// SetSuccessor records the package path of the realm that continues the
// game, e.g. "gno.land/r/…/coblyn/miner/v2"; "" clears it. Admin only.
func SetSuccessor(cur realm, path string) {
	onlyAdmin(cur.Previous().Address())
	if path != "" {
		if !strings.HasPrefix(path, "gno.land/r/") || len(path) > MaxSuccessorBytes {
			panic("successor: a realm path gno.land/r/…, at most 128 bytes")
		}
		for i := len("gno.land/r/"); i < len(path); i++ {
			c := path[i]
			if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '/' || c == '_' || c == '.' || c == '-') {
				panic("successor: only a-z 0-9 / _ . - in the path")
			}
		}
	}
	successor = path
	chain.Emit("Successor", "path", path)
}

// ProposeAdmin names the next admin; it takes effect when that address
// calls AcceptAdmin. Proposing again replaces the proposal. Admin only.
func ProposeAdmin(cur realm, addr address) {
	onlyAdmin(cur.Previous().Address())
	if !addr.IsValid() {
		panic("invalid address")
	}
	pendingAdmin = addr
	chain.Emit("AdminProposed", "admin", admin.String(), "proposed", addr.String())
}

// AcceptAdmin makes the caller the admin; only the proposed address may
// call it.
func AcceptAdmin(cur realm) {
	caller := cur.Previous().Address()
	if pendingAdmin == "" || caller != pendingAdmin {
		panic("not the proposed admin")
	}
	prev := admin
	admin = caller
	pendingAdmin = ""
	chain.Emit("AdminChanged", "from", prev.String(), "to", caller.String())
}

// Package miner is the on-chain season of Coblyn, a GPU mining
// game. The browser plays instantly and logs every action with its
// timestamp; "Collect" is a transaction that sends that log here. This realm
// replays the log with the same economy package the browser uses
// (p/…/coblyn/miner/v2), then collects at block time. The state kept here
// is canonical: the client replaces its own state with it after each
// Collect, so season values and badges can be checked by anyone.
//
// Seasons are global and consecutive: season n starts at
// start + (n-1)*28 days for everyone, and the daily event calendar depends
// on the season number. A player who joins mid-season gets the economy's
// newcomer boost; a returning player does not.
//
// Season end, to the second. A season's results are final at its end
// (seasonEnd, in ms): nothing changes an ended season afterwards.
//
//   - Projection: after every Join and Collect the realm settles a copy of
//     the farm up to min(lastClaim + monitoring window, season end) —
//     mining stops when the monitoring window runs out — and stores the
//     rounded value: what the farm's season ends at if the player does
//     nothing more. Since the window and the season end are fixed, it is
//     the exact final result unless the player collects again before the
//     end. A player who never comes back keeps it as their result.
//   - A logged line dated at or after the end of the farm's season is
//     skipped (ErrAfterSeason). A Collect whose block time is at or after
//     that end skips every line of the ended season too (ErrSeasonEnded):
//     actions must reach the chain before the season ends.
//   - The first Join or Collect after the farm's season ended rolls it
//     over: the stored projection becomes the season's result (it equals
//     settling the farm to the end, nothing could change it since), a
//     history entry {season, value, mined, badge, room} is added, and the
//     next farm starts in the current season at block time with the start
//     cards of the badge earned (Sapphire and Diamond included: the rank is
//     final at the end). Seasons the player skipped get no entry.
//
// Badges: Copper … Pearl by value threshold, Sapphire and Diamond by rank
// within the season (the rule is eco.Ladder's; season.gno keeps one ladder
// per season). Before a season ends its badges are what it would give "if
// the season ended now".
//
// Storage. A player is one small record: a few numbers and the farm as one
// compact string (eco.Encode, a few hundred bytes even for a big farm), not
// a tree of objects. A season keeps counts and a histogram of the results
// of at least Pearl, no per-player entry. Storage changes only through the
// player's own Join and Collect, so the storage deposit for a farm is paid,
// and refunded when it shrinks, by that player's own transaction: nobody
// else can close, shrink or grow another player's records.
//
// Log format: one action per line, "ts|op|args", ts in integer
// milliseconds. Ops (economy.js names):
//
//	b  buyCard       t,rgb      (rgb 0/1)
//	o  buyOffer      k
//	s  sellCard      id
//	c  overclock     id
//	C  ocMany        id;id;…    (may be empty; a-b is the ids a…b, a <= b)
//	w  rigSwap       r,t,rgb
//	r  buyRig        —
//	m  moveRoom      —
//	u  upgradeWatch  —
//
// Claims are not loggable: collecting happens only as the transaction
// itself, at block time, so the monitoring window cannot be faked.
//
// Which lines are replayed: a malformed log (bad syntax, unknown op, too
// long, a claim line, a timestamp more than MaxAhead past block time) aborts
// the whole Collect. Any other line that cannot be replayed is skipped and
// reported, and the Collect still collects at block time, so a stale log can
// never lock a player out: lines dated at or before the last Collect, out of
// order, more than MaxBackdate before block time, at or after the end of the
// farm's season, in a season that has already ended, or refused by the
// economy.
//
// The log is written by the client. The realm checks that every action is
// legal at its timestamp, not that a person made it then. Backdating gives
// no hindsight: prices, events, offers and the network are pure functions
// of the day and the season, so a whole season can be planned on day 1.
// What a script can do is play that plan perfectly, in real time or inside
// the MaxBackdate window, with the same result. Bot play is an open point
// for mainnet: it needs randomness the chain reveals over time, not a
// shorter window.
//
// Upgrade path (admin, see admin.gno): Halt stops Join and Collect for good,
// SetSuccessor names the next realm, ProposeAdmin/AcceptAdmin hand the admin
// role over. No admin function can edit player values, logs or badges.
//
// Gas and storage (filetests z1–z9, gno v1.8.0 tree fc79041, 2026-11-19).
// On chain every transaction also pays ≈ 4.4M for loading the economy
// package and 59k per store read: a daily Collect that is 23M here is ≈ 39M
// on a local chain (see docs/design.md). Join ≈ 2.8M gas and ≈ 3.1 KB
// (the first player of a season ≈ 5.4 KB, with the season record); the daily
// Collect of an 80-card data-center farm (10 actions over 24 h) ≈ 23M gas and
// +32 bytes; the whole 80-card farm ≈ 5.6 KB; the rollover of that farm
// ≈ 9M gas (+4.2 KB for the first entrant into a season: the season record;
// ≈ +50 bytes for everyone after); storing the cutoffs of a 1000-player
// season ≈ 7M gas. Of a Collect, about 3M is decoding the farm, 3M encoding
// it and about 3M the projection (one settle step per hour of the monitoring
// window). 500 short actions ≈ 0.46G for a new farm and ≈ 0.56G on the
// 80-card farm. Each logged action costs about 1–4M (it settles the farm
// first), an ocMany line about 0.06M more per listed card, and every log
// byte about 10k to parse: clients should Collect after a few dozen actions
// at most. A ladder histogram entry (a distinct result of at least Pearl) is
// an avl node of ≈ 2 KB.
package miner

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"

	eco "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2"
)

const (
	// RulesVersion is reported by Season() so the client can tell which
	// rules the realm replays with. 2: strict season end, projections,
	// rank badges at the season end (no FinalizeSeason).
	RulesVersion = 2

	MaxLogLines = 500
	MaxLogBytes = 20000
	// MaxCardIDs: card ids on one C line, ranges expanded.
	MaxCardIDs = 1000
	// MaxLogCardIDs: card ids in a whole log, ranges expanded (a farm has at
	// most 112 cards, so even a long day's log stays far below it).
	MaxLogCardIDs = 2000
	// MaxAhead: a device clock may run a little ahead of block time. Log
	// timestamps up to this many ms after block time are accepted and
	// replayed at block time.
	MaxAhead int64 = 120000
	// MaxBackdate: log lines dated more than this many ms before block time
	// are skipped ("Too old"). 72 h covers the longest monitoring window
	// (48 h) plus slack for a player who comes back late.
	MaxBackdate int64 = 72 * 3600 * 1000

	// Messages of skipped log lines (besides the economy's own).
	ErrBeforeCollect = "Before the last Collect"
	ErrOutOfOrder    = "Out of order"
	ErrTooOld        = "Too old"
	ErrAfterSeason   = "After your season ended"
	ErrSeasonEnded   = "Season ended"

	// TopN: rows of the top results on the main page; SeasonRows: on a
	// season page.
	TopN       = 20
	SeasonRows = 100
)

var (
	admin   = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")
	start   int64    // ms of season 1 start, 0 = not started
	players avl.Tree // address string -> *player

	seasonMs = int64(eco.Net.SeasonDays) * eco.Day

	testNow int64 // tests set this (ms); 0 = block time
)

// player is one wallet's record: primitive fields and the farm as one
// compact string.
type player struct {
	farm        string // eco.Encode of the farm (as of the last Join/Collect)
	season      int    // the farm's season
	proj        int64  // projected result of that season (see the package comment)
	lastCollect int64  // block time (ms) of the last Collect, or of the Join
	collects    int
}

// farmOf decodes the player's farm. The realm wrote it, so it always
// decodes.
func farmOf(p *player) *eco.State {
	st, err := eco.Decode(p.farm)
	if err != nil {
		panic("corrupt farm record")
	}
	return st
}

func now() int64 {
	if testNow != 0 {
		return testNow
	}
	return time.Now().UnixMilli()
}

// seasonAt is the season number at t (ms), 0 before the first season.
func seasonAt(t int64) int {
	if start == 0 || t < start {
		return 0
	}
	return int((t-start)/seasonMs) + 1
}

// seasonStartOf is the start (ms) of season n >= 1.
func seasonStartOf(n int) int64 {
	return start + int64(n-1)*seasonMs
}

// seasonEndOf is the end (ms) of season n >= 1: its results are final from
// this moment on.
func seasonEndOf(n int) int64 {
	return seasonStartOf(n) + seasonMs
}

// ended: season n is over at block time t (t >= its end; no overflow for
// any n).
func ended(n int, t int64) bool {
	return n < seasonAt(t)
}

// Start opens season 1 at startMs (unix ms, not in the past). Admin only;
// it can be changed until the first season has begun.
func Start(cur realm, startMs int64) {
	onlyAdmin(cur.Previous().Address())
	notHalted()
	if start != 0 && now() >= start {
		panic("season already running")
	}
	if startMs <= 0 {
		panic("bad start time")
	}
	if startMs < now() {
		panic("start time is in the past")
	}
	start = startMs
	chain.Emit("SeasonStart", "start", strconv.FormatInt(start, 10))
}

func mustOpen(t int64) int {
	n := seasonAt(t)
	if n == 0 {
		panic("the first season has not started yet")
	}
	return n
}

// Join creates the caller's farm at block time, in the current season, and
// returns its state JSON (the economy.js save format). A player who joins
// mid-season gets the newcomer boost. For an existing player it only rolls
// an ended season over (see the package comment) and returns the state;
// actions dated before that moment can no longer be replayed.
func Join(cur realm) string {
	if !cur.Previous().IsUserCall() {
		panic("join directly from a wallet")
	}
	notHalted()
	key := cur.Previous().Address().String()
	t := now()
	n := mustOpen(t)
	defer cacheLast(n)
	if v := players.Get(key); v != nil {
		p := v.(*player)
		st := farmOf(p)
		if p.season < n {
			st = rollover(key, p, st, n, t)
			p.lastCollect = t
			out := st.JSON()
			save(p, st, true)
			return out
		}
		return st.JSON()
	}
	st := eco.NewState(t) // Last = LastClaim = Born = t
	st.Season = n
	st.SeasonStart = seasonStartOf(n)
	p := &player{lastCollect: t}
	out := st.JSON()
	save(p, st, true)
	players.Set(key, p)
	chain.Emit("Join", "player", key, "season", strconv.Itoa(n), "projection", strconv.FormatInt(p.proj, 10))
	return out
}

// action is one parsed log line.
type action struct {
	ts   int64 // replay time: the logged time, clamped to block time
	raw  int64 // the logged time
	op   byte
	x    [3]int
	ids  []int
	line int
	err  string // set: the line is skipped with this message
}

// Collect replays the caller's action log, then collects at block time.
// It returns {"applied":n,"skipped":[{"i":k,"err":"…"}],"season":…,
// "projection":…}: season is the farm's season after it, projection its
// projected season result (see the package comment). The farm itself
// (wallet, value, …) is read with State: formatting its floats here would
// cost every Collect gas for numbers the client reads anyway. A malformed log aborts the
// whole transaction (see the package comment). Every other line that
// cannot be replayed is skipped and reported with its line index i
// (0-based) and a message: an economy refusal (for example "Not enough
// BLK" after a tiny rounding difference), ErrBeforeCollect, ErrOutOfOrder,
// ErrTooOld, ErrAfterSeason (dated at or after the end of the farm's
// season) or ErrSeasonEnded (the farm's season ended before this Collect:
// the farm enters the current season at block time, after the replay).
func Collect(cur realm, log string) string {
	if !cur.Previous().IsUserCall() {
		panic("collect directly from a wallet")
	}
	notHalted()
	key := cur.Previous().Address().String()
	t := now()
	n := mustOpen(t)
	v := players.Get(key)
	if v == nil {
		panic("join first")
	}
	defer cacheLast(n)
	p := v.(*player)
	acts := parseLog(log, p.lastCollect, t)
	st := farmOf(p)

	applied := 0
	var skipped strings.Builder
	nSkipped := 0
	esc := map[string]string{} // escaped error texts (a handful of distinct ones)
	skip := func(line int, msg string) {
		e, ok := esc[msg]
		if !ok {
			e = jsonStr(msg)
			esc[msg] = e
		}
		if nSkipped > 0 {
			skipped.WriteByte(',')
		}
		skipped.WriteString(`{"i":`)
		skipped.WriteString(strconv.Itoa(line))
		skipped.WriteString(`,"err":`)
		skipped.WriteString(e)
		skipped.WriteByte('}')
		nSkipped++
	}
	end := seasonEndOf(p.season)
	over := t >= end // the farm's season has ended: nothing changes it now
	for _, a := range acts {
		switch {
		case a.err != "":
			skip(a.line, a.err)
		case a.raw >= end:
			skip(a.line, ErrAfterSeason)
		case over:
			skip(a.line, ErrSeasonEnded)
		default:
			if err := apply(st, a); err != nil {
				skip(a.line, err.Error())
				continue
			}
			applied++
		}
	}
	if over {
		st = rollover(key, p, st, n, t)
	}
	st.Claim(t)
	p.lastCollect = t
	p.collects++

	season := strconv.Itoa(st.Season)
	save(p, st, over)
	proj := strconv.FormatInt(p.proj, 10)
	nApplied := strconv.Itoa(applied)
	chain.Emit("Collect",
		"player", key,
		"season", season,
		"applied", nApplied,
		"skipped", strconv.Itoa(nSkipped),
		"projection", proj)
	return `{"applied":` + nApplied + `,"skipped":[` + skipped.String() + `],"season":` + season +
		`,"projection":` + proj + `}`
}

func apply(st *eco.State, a action) error {
	var err error
	switch a.op {
	case 'b':
		_, err = st.BuyCard(a.x[0], a.ts, a.x[1] == 1)
	case 'o':
		_, err = st.BuyOffer(a.x[0], a.ts)
	case 's':
		_, err = st.SellCard(a.x[0], a.ts)
	case 'c':
		_, err = st.Overclock(a.x[0], a.ts)
	case 'C':
		_, err = st.OCMany(a.ids, a.ts)
	case 'w':
		_, err = st.RigSwap(a.x[0], a.x[1], a.ts, a.x[2] == 1)
	case 'r':
		_, err = st.BuyRig(a.ts)
	case 'm':
		_, err = st.MoveRoom(a.ts)
	case 'u':
		_, err = st.UpgradeWatch(a.ts)
	}
	return err
}

// parseLog checks the whole log before anything is applied, in one pass
// over its bytes (every byte touched costs gas). after: the previous
// Collect (or Join) time; t: block time. Timestamps up to MaxAhead past
// block time are clamped to block time (a.raw keeps the logged one). A
// line is marked skipped (a.err) when its timestamp is not after `after`,
// more than MaxBackdate before t, or before an earlier replayed line; it is
// still checked for syntax. One trailing newline is allowed.
func parseLog(log string, after, t int64) []action {
	n := len(log)
	if n == 0 {
		return nil
	}
	if n > MaxLogBytes {
		panic("log too long: at most " + strconv.Itoa(MaxLogBytes) + " bytes, Collect more often")
	}
	out := []action{}
	idsTotal := 0
	prev := after
	i := 0
	for line := 0; i < n; line++ {
		if line >= MaxLogLines {
			panic("log too long: at most " + strconv.Itoa(MaxLogLines) + " actions, Collect more often")
		}
		// ts
		var ts int64
		j := i
		for i < n {
			c := log[i]
			if c < '0' || c > '9' {
				break
			}
			ts = ts*10 + int64(c-'0')
			i++
		}
		if i == n || log[i] == '\n' {
			bad(line, "want ts|op|args")
		}
		if i == j || i-j > 15 || log[i] != '|' {
			bad(line, "timestamp must be an integer (ms)")
		}
		if ts > t+MaxAhead {
			bad(line, "timestamp is in the future")
		}
		raw := ts
		if ts > t {
			ts = t
		}
		a := action{ts: ts, raw: raw, line: line}
		switch {
		case ts <= after:
			a.err = ErrBeforeCollect
		case ts < t-MaxBackdate:
			a.err = ErrTooOld
		case ts < prev:
			a.err = ErrOutOfOrder
		default:
			prev = ts
		}
		// op
		i++
		if i+1 >= n || log[i] == '\n' {
			bad(line, "want ts|op|args")
		}
		a.op = log[i]
		i++
		if log[i] != '|' {
			bad(line, "unknown op")
		}
		i++
		// args, up to the end of the line
		switch a.op {
		case 'b', 'w', 'o', 's', 'c':
			k := 1
			if a.op == 'b' {
				k = 2
			} else if a.op == 'w' {
				k = 3
			}
			for m := 0; m < k; m++ {
				v, end := readUint(log, i, n)
				if end == i {
					bad(line, "arguments must be integers")
				}
				a.x[m] = v
				i = end
				last := m == k-1
				if i < n && log[i] == ',' && !last {
					i++
					continue
				}
				if (i == n || log[i] == '\n') && last {
					break
				}
				if i < n && log[i] != ',' && log[i] != '\n' {
					bad(line, "arguments must be integers")
				}
				bad(line, "want "+strconv.Itoa(k)+" comma separated integers")
			}
			if a.op == 'b' && a.x[1] > 1 || a.op == 'w' && a.x[2] > 1 {
				bad(line, "rgb must be 0 or 1")
			}
		case 'C':
			// The longest lines: the digits are read here, not by
			// readUint (a call per id costs gas).
			a.ids = []int{}
			for i < n {
				c := log[i]
				if c == '\n' {
					break
				}
				v, j := 0, i
				for c >= '0' && c <= '9' {
					v = v*10 + int(c-'0')
					i++
					if i == n {
						break
					}
					c = log[i]
				}
				if i == j || i-j > 9 {
					bad(line, "card ids must be integers")
				}
				if c == '-' && i < n { // a range v-w: v, v+1, …, w
					i++
					if i == n {
						bad(line, "card ids must be integers")
					}
					c = log[i]
					w := 0
					j = i
					for c >= '0' && c <= '9' {
						w = w*10 + int(c-'0')
						i++
						if i == n {
							break
						}
						c = log[i]
					}
					if i == j || i-j > 9 {
						bad(line, "card ids must be integers")
					}
					if w < v {
						bad(line, "a card id range must ascend")
					}
					if len(a.ids)+w-v >= MaxCardIDs {
						bad(line, "too many card ids: at most "+strconv.Itoa(MaxCardIDs))
					}
					for ; v <= w; v++ {
						a.ids = append(a.ids, v)
					}
				} else {
					if len(a.ids) >= MaxCardIDs {
						bad(line, "too many card ids: at most "+strconv.Itoa(MaxCardIDs))
					}
					a.ids = append(a.ids, v)
				}
				if i == n || c == '\n' {
					break
				}
				if c != ';' {
					bad(line, "card ids must be integers")
				}
				i++
				if i == n || log[i] == '\n' {
					bad(line, "card ids must be integers")
				}
			}
		case 'r', 'm', 'u':
			if i < n && log[i] != '\n' {
				bad(line, "this op takes no arguments")
			}
		case 'K':
			bad(line, "claims cannot be logged: the Collect transaction itself collects at block time")
		default:
			bad(line, "unknown op")
		}
		idsTotal += len(a.ids)
		if idsTotal > MaxLogCardIDs {
			bad(line, "too many card ids in one log: at most "+strconv.Itoa(MaxLogCardIDs)+", Collect more often")
		}
		out = append(out, a)
		i++ // the newline (or past the end)
	}
	return out
}

func bad(line int, why string) {
	panic("log entry " + strconv.Itoa(line) + ": " + why)
}

// readUint reads up to 9 decimal digits from s at i; n = len(s) (a len
// call per byte costs gas). end == i: no digit.
func readUint(s string, i, n int) (v, end int) {
	end = i
	for end < n && end-i < 10 {
		c := s[end]
		if c < '0' || c > '9' {
			break
		}
		v = v*10 + int(c-'0')
		end++
	}
	if end-i > 9 {
		return 0, i // too long: reported as not an integer
	}
	return v, end
}


// State returns the player's state JSON (the economy.js save format, as of
// the last Join or Collect), or "" for an address that has not joined.
func State(addr address) string {
	v := players.Get(addr.String())
	if v == nil {
		return ""
	}
	return farmOf(v.(*player)).JSON()
}

// Season returns the season clock as JSON:
// {"start","season","seasonStart","seasonEnd","day","players","rules",
// "halted","haltReason","successor"}. Times are unix ms; day is the
// current season day 1..28; seasonEnd is the second at which the current
// season's results become final. Before the first season, season,
// seasonStart, seasonEnd and day are 0. players: every address that has
// joined. halted: Join and Collect are stopped for good (see Halt);
// successor: the package path of the next realm, "" if none.
func Season() string {
	t := now()
	n := seasonAt(t)
	var ss, se int64
	day := 0
	if n > 0 {
		ss = seasonStartOf(n)
		se = ss + seasonMs
		day = int((t-ss)/eco.Day) + 1
	}
	return `{"start":` + strconv.FormatInt(start, 10) +
		`,"season":` + strconv.Itoa(n) +
		`,"seasonStart":` + strconv.FormatInt(ss, 10) +
		`,"seasonEnd":` + strconv.FormatInt(se, 10) +
		`,"day":` + strconv.Itoa(day) +
		`,"players":` + strconv.Itoa(players.Size()) +
		`,"rules":` + strconv.Itoa(RulesVersion) +
		`,"halted":` + strconv.FormatBool(halted) +
		`,"haltReason":` + jsonStr(haltReason) +
		`,"successor":` + jsonStr(successor) + `}`
}

func jsonStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c < 0x20:
			const hexd = "0123456789abcdef"
			b.WriteString(`\u00`)
			b.WriteByte(hexd[c>>4])
			b.WriteByte(hexd[c&15])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package miner

import (
	"strconv"
	"strings"
	"time"

	eco "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2"
)

// Render shows the current season (path ""), one season's results
// ("season/<n>") or one player's page ("<address>"). It reads the season
// records and at most one player; it never scans all players. Seasons keep
// no per-player index, so the result tables list results and how many
// players reached each, not who.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "season/") {
		n, err := strconv.Atoi(path[len("season/"):])
		if err != nil || n < 1 {
			return "# Not found\n\nNo such season.\n"
		}
		return renderSeason(n)
	}
	return renderPlayer(path)
}

// badgeRule explains the badge rule in one paragraph.
func badgeRule() string {
	var t strings.Builder
	for i, bd := range eco.Badges {
		if i > 0 {
			t.WriteString(" · ")
		}
		t.WriteString(bd.Name + " " + fmtInt(bd.Min))
	}
	return "**Badges.** Every badge is a value threshold: " + t.String() + ". A result earns the highest " +
		"threshold it reaches. There is no limit on how many players earn a badge, and no other account can take " +
		"one away or add one. A season's results and badges are final at its end, to the second; actions that " +
		"reach the chain later do not count.\n\n"
}

// notice: the halt banner and the successor link, "" if neither.
func notice() string {
	s := ""
	if halted {
		s += "> **Halted:** " + haltReason + "\n>\n> Join and Collect are closed for good. Everything recorded so far " +
			"stays readable here; every player's last projection is their result.\n\n"
	}
	if successor != "" {
		s += "> **Next version:** the game continues at [" + successor + "](" + successor[len("gno.land"):] + ").\n\n"
	}
	return s
}

func renderHome() string {
	t := now()
	n := seasonAt(t)
	var b strings.Builder
	b.WriteString("# Coblyn\n\n")
	b.WriteString(notice())
	switch {
	case start == 0:
		b.WriteString("The first season has not started yet.\n\n")
	case n == 0:
		b.WriteString("Season 1 opens " + fmtTime(start) + ".\n\n")
	default:
		ss := seasonStartOf(n)
		day := int((t-ss)/eco.Day) + 1
		b.WriteString("Season **" + strconv.Itoa(n) + "** · day **" + strconv.Itoa(day) + " / " +
			strconv.Itoa(eco.Net.SeasonDays) + "** · ends " + fmtTime(ss+seasonMs) + ", results final at that second\n\n")
	}
	b.WriteString("Every value here is computed on chain: each Collect sends the player's logged actions, and this realm " +
		"replays them with `gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2`, the same economy " +
		"the game runs in the browser, then collects at block time.\n\n")

	if n > 0 {
		b.WriteString("## Season " + strconv.Itoa(n) + " · if it ended now\n\n")
		r := recOf(n)
		if r == nil || r.ladder.Players == 0 {
			b.WriteString("Nobody has played this season yet.\n\n")
		} else {
			writeResults(&b, r, cutsOf(n), TopN)
			b.WriteString("Results are projections: what each farm reaches by the season end if its player does nothing " +
				"more (mining stops when the monitoring window runs out).\n\n")
		}
		b.WriteString(badgeRule())
	}
	b.WriteString("Players: " + strconv.Itoa(players.Size()) + "\n\n")

	if n > 1 {
		b.WriteString("## Past seasons\n\n")
		for s := 1; s < n; s++ {
			r := recOf(s)
			if r == nil || r.ladder.Players == 0 {
				continue
			}
			c := cutsOf(s)
			b.WriteString("- [Season " + strconv.Itoa(s) + "](:season/" + strconv.Itoa(s) + ") · final · players " +
				strconv.Itoa(r.ladder.Players) + " · Diamond " + strconv.Itoa(c.NDiamond) +
				" · Sapphire " + strconv.Itoa(c.NSapphire) + "\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("---\n\nA [Hazen Network Solutions](https://hazennetworksolutions.com) game.\n")
	return b.String()
}

// writeResults writes a season's counts, the Diamond and Sapphire counts and
// its best results (at most rows distinct results of at least Pearl).
func writeResults(b *strings.Builder, r *seasonRec, c eco.Cuts, rows int) {
	l := &r.ladder
	b.WriteString("Players: " + strconv.Itoa(l.Players) + " · at Copper or above: " + strconv.Itoa(l.Counted) +
		" · at Pearl or above: " + strconv.Itoa(l.PearlPlus) + "\n\n")
	b.WriteString("- Diamond (results of at least **" + fmtInt(float64(c.Diamond)) + "**): " + strconv.Itoa(c.NDiamond) + " players\n")
	b.WriteString("- Sapphire (results of at least **" + fmtInt(float64(c.Sapphire)) + "**): " + strconv.Itoa(c.NSapphire) + " players\n\n")
	if l.PearlPlus == 0 {
		return
	}
	b.WriteString("| # | Result | Players | Badge |\n|---|---|---|---|\n")
	above := 0
	l.Top(rows, func(v int64, k int) bool {
		b.WriteString("| " + strconv.Itoa(above+1) + " | " + fmtInt(float64(v)) + " | " + strconv.Itoa(k) + " | " +
			badgeName(eco.RankBadge(v)) + " |\n")
		above += k
		return false
	})
	b.WriteString("\n")
}

func orDash(s string) string {
	if s == "" {
		return "—"
	}
	return s
}

func renderSeason(n int) string {
	var b strings.Builder
	b.WriteString("# Coblyn · Season " + strconv.Itoa(n) + "\n\n")
	b.WriteString(notice())
	t := now()
	if start == 0 || n > seasonAt(t) {
		b.WriteString("This season has not started yet.\n")
		return b.String()
	}
	ss := seasonStartOf(n)
	end := ss + seasonMs
	b.WriteString(fmtTime(ss) + " – " + fmtTime(end) + "\n\n")
	if ended(n, t) {
		b.WriteString("**Final** since " + fmtTime(end) + ".\n\n")
	} else {
		b.WriteString("Running. Results are projections and badges are as if the season ended now; both are final at " +
			fmtTime(end) + ".\n\n")
	}
	r := recOf(n)
	if r == nil || r.ladder.Players == 0 {
		b.WriteString("Nobody played this season.\n")
		return b.String()
	}
	b.WriteString("## Results\n\n")
	writeResults(&b, r, cutsOf(n), SeasonRows)
	b.WriteString(badgeRule())
	return b.String()
}

func renderPlayer(key string) string {
	// only a valid address is echoed back into the page
	if !address(key).IsValid() {
		return "# Not found\n\nNo such page.\n"
	}
	var b strings.Builder
	b.WriteString("# " + key + "\n\n")
	b.WriteString(notice())
	v := players.Get(key)
	if v == nil {
		b.WriteString("This address has no farm on chain yet.\n")
		return b.String()
	}
	p := v.(*player)
	st := farmOf(p)
	badge := orDash(badgeName(eco.RankBadge(p.proj)))
	place := ""
	if r := recOf(p.season); r != nil && r.ladder.Players > 0 {
		ahead, tied := r.ladder.Place(p.proj)
		if tied < 1 {
			tied = 1
		}
		place = " · place **#" + strconv.Itoa(ahead+1)
		if tied > 1 {
			place += "–" + strconv.Itoa(ahead+tied)
		}
		place += "** of " + strconv.Itoa(r.ladder.Players)
	}
	b.WriteString("## Season " + strconv.Itoa(p.season) + "\n\n")
	if ended(p.season, now()) {
		b.WriteString("Ended. Final result: **" + fmtInt(float64(p.proj)) + "** · badge: **" + badge + "**" + place + ". " +
			"The farm enters the current season at the player's next Join or Collect.\n\n")
	} else {
		b.WriteString("- Projected result: **" + fmtInt(float64(p.proj)) + "** · badge if the season ended now: **" + badge + "**" + place + "\n")
		b.WriteString("- At the last Collect: value " + fmtInt(st.Value) + " · mined " + fmtInt(st.Mined) + " " + eco.Token +
			" · wallet " + fmtInt(st.Wallet) + " " + eco.Token + "\n")
		b.WriteString("- Facility: " + eco.Rooms[st.Room].Name + " · rigs: " + strconv.Itoa(len(st.Rigs)) +
			" · cards: " + strconv.Itoa(len(st.Cards)) + " · monitoring: " + strconv.Itoa(st.WatchHours()) + " h\n")
		b.WriteString("- Last Collect: " + fmtTime(p.lastCollect) + " · Collects: " + strconv.Itoa(p.collects) + "\n\n")
		b.WriteString("The projection is what the farm reaches by the season end (" + fmtTime(seasonEndOf(p.season)) +
			") if the player does nothing more; it is final then.\n\n")
	}
	b.WriteString("## History\n\n")
	if len(st.History) == 0 {
		b.WriteString("No finished season yet.\n")
		return b.String()
	}
	b.WriteString("| Season | Badge | Value | Facility |\n|---|---|---|---|\n")
	for i := len(st.History) - 1; i >= 0; i-- {
		h := st.History[i]
		b.WriteString("| [" + strconv.Itoa(h.Season) + "](:season/" + strconv.Itoa(h.Season) + ") | " + orDash(h.Badge) +
			" | " + fmtInt(h.Value) + " | " + eco.Rooms[h.Room].Name + " |\n")
	}
	return b.String()
}

// fmtInt rounds x and groups thousands: 1234567.6 -> "1,234,568".
func fmtInt(x float64) string {
	v := int64(eco.JSRound(x))
	neg := v < 0
	if neg {
		v = -v
	}
	s := strconv.FormatInt(v, 10)
	var b strings.Builder
	if neg {
		b.WriteByte('-')
	}
	for i := 0; i < len(s); i++ {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

func fmtTime(ms int64) string {
	return time.Unix(ms/1000, 0).UTC().Format("2006-01-02 15:04:05 UTC")
}

package miner

import (
	"chain"
	"strconv"

	"gno.land/p/nt/avl/v0"

	eco "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2"
)

// Seasons and badges on chain
//
// A season's result for a player is their projection for it (see the
// package comment): the farm's season value, rounded, if the player does
// nothing more. Badges are fixed value thresholds, Copper … Diamond
// (eco.Badges): a result earns the highest threshold it reaches, whatever
// other players do, so no number of other accounts can take a badge away
// or create one. Each season keeps an eco.Ladder of its players' results
// for places, the results table and the badge counts.
//
// The ladder moves with the projections while the season runs, so its
// badges are "if the season ended now". At the season end the projections
// are final. The first Join or Collect (by anyone) after the season ended
// stores the season's badge counts in its record (event SeasonFinal). A
// player's history entry gets the final badge when their farm rolls over
// (event SeasonEnd).

var (
	seasons avl.Tree // seasonKey(n) -> *seasonRec

	copperMin = eco.Badges[eco.CopperIdx].Min
	pearlMin  = eco.Badges[eco.PearlIdx].Min
)

// seasonRec is one season's results: no per-player entry.
type seasonRec struct {
	ladder eco.Ladder
	final  bool     // badge counts are stored (the season has ended)
	cuts   eco.Cuts // valid when final
}

func pad15(x int64) string {
	s := strconv.FormatInt(x, 10)
	return "000000000000000"[len(s):] + s
}

func seasonKey(n int) string { return pad15(int64(n)) }

func recOf(n int) *seasonRec {
	v := seasons.Get(seasonKey(n))
	if v == nil {
		return nil
	}
	return v.(*seasonRec)
}

func rec(n int) *seasonRec {
	r := recOf(n)
	if r == nil {
		r = &seasonRec{}
		seasons.Set(seasonKey(n), r)
	}
	return r
}

// badgeName of a badge index, "" for none (-1).
func badgeName(i int) string {
	if i < 0 {
		return ""
	}
	return eco.Badges[i].Name
}

// project: the farm's projected season result, rounded. It settles st up
// to the season end (Settle stops at the monitoring window), so st must not
// be used afterwards.
func project(st *eco.State) int64 {
	st.Settle(st.SeasonEnd())
	v := eco.JSRound(st.Value)
	if v < 0 {
		return 0
	}
	return int64(v)
}

// save stores the farm and its projection. entered: the farm has just
// entered season st.Season (Join or rollover); otherwise its projection
// moves within that season's ladder. Only called before the farm's season
// ends, so an ended season's ladder never changes. st is spent afterwards.
func save(p *player, st *eco.State, entered bool) {
	p.farm = eco.Encode(st)
	v := project(st)
	r := rec(st.Season)
	if entered {
		r.ladder.Add(v)
	} else {
		r.ladder.Move(p.proj, v)
	}
	p.proj = v
	p.season = st.Season
}

// cutsOf: season n's Sapphire/Diamond thresholds and counts, stored ones if
// final, else as of now.
func cutsOf(n int) eco.Cuts {
	r := recOf(n)
	if r == nil {
		return eco.Cuts{}
	}
	if r.final {
		return r.cuts
	}
	return r.ladder.Cuts()
}

// finalCuts stores the badge counts of season n, which has ended, unless
// that is done already, and returns them.
func finalCuts(n int) eco.Cuts {
	r := recOf(n)
	if r == nil {
		return eco.Cuts{}
	}
	if !r.final {
		r.cuts = r.ladder.Cuts()
		r.final = true
		chain.Emit("SeasonFinal",
			"season", strconv.Itoa(n),
			"players", strconv.Itoa(r.ladder.Players),
			"counted", strconv.Itoa(r.ladder.Counted),
			"diamond", strconv.Itoa(r.cuts.NDiamond),
			"sapphire", strconv.Itoa(r.cuts.NSapphire),
			"diamondCutoff", strconv.FormatInt(r.cuts.Diamond, 10),
			"sapphireCutoff", strconv.FormatInt(r.cuts.Sapphire, 10))
	}
	return r.cuts
}

// cacheLast: run at the end of every Join and Collect in season n; stores
// the previous season's badge counts the first time.
func cacheLast(n int) {
	if n > 1 {
		finalCuts(n - 1)
	}
}

// rollover ends the farm's season (over at block time t) and returns the
// farm's start state in season n at t. The result is the stored
// projection: the farm cannot have changed since it was computed, and
// settling it to the season end (done here, for the history entry's
// "mined") gives the same value. The badge is the result's threshold badge; the
// next season starts with that badge's cards. The farm is no newcomer
// there (Born = season start) and mines nothing for the time away.
func rollover(key string, p *player, st *eco.State, n int, t int64) *eco.State {
	f := p.season
	finalCuts(f)
	b := eco.RankBadge(p.proj)
	next := st.NewSeason(st.SeasonEnd(), "")
	h := &next.History[len(next.History)-1]
	h.Value = float64(p.proj)
	h.Badge = badgeName(b)
	cards := []int{1}
	if b >= 0 {
		cards = eco.Badges[b].Start
	}
	next.Cards = map[int]*eco.Card{}
	next.Rigs = [][]int{{0, 0, 0, 0}} // as eco.NewSeason
	for k, ty := range cards {
		next.Cards[k+1] = &eco.Card{T: ty}
		next.Rigs[0][k] = k + 1
	}
	next.NextID = len(cards) + 1
	ss := seasonStartOf(n)
	next.Season = n
	next.SeasonStart = ss
	next.Born = ss
	next.Last = t
	next.LastClaim = t
	chain.Emit("SeasonEnd",
		"player", key,
		"season", strconv.Itoa(f),
		"value", strconv.FormatInt(p.proj, 10),
		"badge", h.Badge)
	return next
}

// PlayerSeason returns the player's latest season result as JSON:
// {"season","projection","badge","final","players","ahead","tied"}.
// season: the season of the
// farm's last Join or Collect; projection: its projected result, the final
// result once the season has ended; badge: the threshold badge of that
// result ("" for none) — the final badge when final is true (the season
// has ended), else the badge "if the season ended now"; players:
// farms with a result for that season; ahead and tied: the player's place
// among them (eco.Ladder.Place: exact at or above Pearl, the badge band
// below it). "" for an address that has not joined.
func PlayerSeason(addr address) string {
	v := players.Get(addr.String())
	if v == nil {
		return ""
	}
	p := v.(*player)
	fin := ended(p.season, now())
	pl, ahead, tied := 0, 0, 0
	if r := recOf(p.season); r != nil {
		pl = r.ladder.Players
		ahead, tied = r.ladder.Place(p.proj)
	}
	return `{"season":` + strconv.Itoa(p.season) +
		`,"projection":` + strconv.FormatInt(p.proj, 10) +
		`,"badge":` + jsonStr(badgeName(eco.RankBadge(p.proj))) +
		`,"final":` + strconv.FormatBool(fin) +
		`,"players":` + strconv.Itoa(pl) +
		`,"ahead":` + strconv.Itoa(ahead) +
		`,"tied":` + strconv.Itoa(tied) + `}`
}

// SeasonResult returns season n's results as JSON: {"season","ended",
// "players","counted","pearlPlus","diamondCutoff","sapphireCutoff",
// "diamond","sapphire"}. ended: the results are final; players: farms with
// a result for the season; counted: results of at least Copper;
// pearlPlus: results of at least Pearl; diamondCutoff and sapphireCutoff
// are the fixed Diamond and Sapphire thresholds; diamond and sapphire how
// many players reach them (Diamond not counted in sapphire). Before the
// season ends these are
// "if the season ended now". n must be at least 1; a season that has not
// started yet has no results.
func SeasonResult(n int) string {
	if n < 1 {
		panic("no such season")
	}
	pl, cnt, pp := 0, 0, 0
	c := eco.Cuts{Diamond: int64(eco.Badges[eco.DiamondIdx].Min), Sapphire: int64(eco.Badges[eco.SapphireIdx].Min)}
	if r := recOf(n); r != nil {
		pl, cnt, pp = r.ladder.Players, r.ladder.Counted, r.ladder.PearlPlus
		c = cutsOf(n)
	}
	return `{"season":` + strconv.Itoa(n) +
		`,"ended":` + strconv.FormatBool(ended(n, now())) +
		`,"players":` + strconv.Itoa(pl) +
		`,"counted":` + strconv.Itoa(cnt) +
		`,"pearlPlus":` + strconv.Itoa(pp) +
		`,"diamondCutoff":` + strconv.FormatInt(c.Diamond, 10) +
		`,"sapphireCutoff":` + strconv.FormatInt(c.Sapphire, 10) +
		`,"diamond":` + strconv.Itoa(c.NDiamond) +
		`,"sapphire":` + strconv.Itoa(c.NSapphire) + `}`
}

package miner

import (
	"chain"
	"strings"
)

// Admin functions: the smallest honest upgrade path. None of them can edit a
// player's values, log, history or badges.
//
//   - Halt(reason): one way. Join and Collect panic with "Halted: <reason>"
//     from then on; nothing else changes. State, Season, PlayerSeason,
//     SeasonResult and Render keep working: every player's stored
//     projection is their result, and season results become final at the
//     season end as usual (computed on read, since no Collect stores the
//     cutoffs any more).
//   - SetSuccessor(path): records the package path of the realm that takes
//     over (shown by Render and Season()). It may be set before or after a
//     halt, and corrected.
//   - ProposeAdmin(addr), then AcceptAdmin() by addr: hands the admin role
//     over in two steps, so a typo cannot lose it.

const (
	MaxReasonBytes    = 200
	MaxSuccessorBytes = 128
)

var (
	halted       bool
	haltReason   string
	successor    string  // package path of the next realm, "" = none
	pendingAdmin address // proposed by ProposeAdmin, "" = none
)

func onlyAdmin(caller address) {
	if caller != admin {
		panic("admin only")
	}
}

func notHalted() {
	if halted {
		panic("Halted: " + haltReason)
	}
}

// Halt stops Join and Collect for good, with a reason shown to players
// (1 to MaxReasonBytes bytes, one line). Admin only.
func Halt(cur realm, reason string) {
	onlyAdmin(cur.Previous().Address())
	if halted {
		panic("already halted")
	}
	if reason == "" || len(reason) > MaxReasonBytes {
		panic("reason: 1 to 200 bytes")
	}
	for i := 0; i < len(reason); i++ {
		if reason[i] < 0x20 || reason[i] == 0x7f {
			panic("reason: one line, no control characters")
		}
	}
	halted = true
	haltReason = reason
	chain.Emit("Halt", "reason", reason)
}

// SetSuccessor records the package path of the realm that continues the
// game, e.g. "gno.land/r/…/coblyn/miner/v2"; "" clears it. Admin only.
func SetSuccessor(cur realm, path string) {
	onlyAdmin(cur.Previous().Address())
	if path != "" {
		if !strings.HasPrefix(path, "gno.land/r/") || len(path) > MaxSuccessorBytes {
			panic("successor: a realm path gno.land/r/…, at most 128 bytes")
		}
		for i := len("gno.land/r/"); i < len(path); i++ {
			c := path[i]
			if !(c >= 'a' && c <= 'z' || c >= '0' && c <= '9' || c == '/' || c == '_' || c == '.' || c == '-') {
				panic("successor: only a-z 0-9 / _ . - in the path")
			}
		}
	}
	successor = path
	chain.Emit("Successor", "path", path)
}

// ProposeAdmin names the next admin; it takes effect when that address
// calls AcceptAdmin. Proposing again replaces the proposal. Admin only.
func ProposeAdmin(cur realm, addr address) {
	onlyAdmin(cur.Previous().Address())
	if !addr.IsValid() {
		panic("invalid address")
	}
	pendingAdmin = addr
	chain.Emit("AdminProposed", "admin", admin.String(), "proposed", addr.String())
}

// AcceptAdmin makes the caller the admin; only the proposed address may
// call it.
func AcceptAdmin(cur realm) {
	caller := cur.Previous().Address()
	if pendingAdmin == "" || caller != pendingAdmin {
		panic("not the proposed admin")
	}
	prev := admin
	admin = caller
	pendingAdmin = ""
	chain.Emit("AdminChanged", "from", prev.String(), "to", caller.String())
}

// Package miner is the on-chain season of Coblyn, a GPU mining
// game. The browser plays instantly and logs every action with its
// timestamp; "Collect" is a transaction that sends that log here. This realm
// replays the log with the same economy package the browser uses
// (p/…/coblyn/miner/v2), then collects at block time. The state kept here
// is canonical: the client replaces its own state with it after each
// Collect, so season values and badges can be checked by anyone.
//
// Seasons are global and consecutive: season n starts at
// start + (n-1)*28 days for everyone, and the daily event calendar depends
// on the season number. A player who joins mid-season gets the economy's
// newcomer boost; a returning player does not.
//
// Season end, to the second. A season's results are final at its end
// (seasonEnd, in ms): nothing changes an ended season afterwards.
//
//   - Projection: after every Join and Collect the realm settles a copy of
//     the farm up to min(lastClaim + monitoring window, season end) —
//     mining stops when the monitoring window runs out — and stores the
//     rounded value: what the farm's season ends at if the player does
//     nothing more. Since the window and the season end are fixed, it is
//     the exact final result unless the player collects again before the
//     end. A player who never comes back keeps it as their result.
//   - A logged line dated at or after the end of the farm's season is
//     skipped (ErrAfterSeason). A Collect whose block time is at or after
//     that end skips every line of the ended season too (ErrSeasonEnded):
//     actions must reach the chain before the season ends.
//   - The first Join or Collect after the farm's season ended rolls it
//     over: the stored projection becomes the season's result (it equals
//     settling the farm to the end, nothing could change it since), a
//     history entry {season, value, mined, badge, room} is added, and the
//     next farm starts in the current season at block time with the start
//     cards of the badge earned (Sapphire and Diamond included: the rank is
//     final at the end). Seasons the player skipped get no entry.
//
// Badges: Copper … Pearl by value threshold, Sapphire and Diamond by rank
// within the season (the rule is eco.Ladder's; season.gno keeps one ladder
// per season). Before a season ends its badges are what it would give "if
// the season ended now".
//
// Storage. A player is one small record: a few numbers and the farm as one
// compact string (eco.Encode, a few hundred bytes even for a big farm), not
// a tree of objects. A season keeps counts and a histogram of the results
// of at least Pearl, no per-player entry. Storage changes only through the
// player's own Join and Collect, so the storage deposit for a farm is paid,
// and refunded when it shrinks, by that player's own transaction: nobody
// else can close, shrink or grow another player's records.
//
// Log format: one action per line, "ts|op|args", ts in integer
// milliseconds. Ops (economy.js names):
//
//	b  buyCard       t,rgb      (rgb 0/1)
//	o  buyOffer      k
//	s  sellCard      id
//	c  overclock     id
//	C  ocMany        id;id;…    (may be empty; a-b is the ids a…b, a <= b)
//	w  rigSwap       r,t,rgb
//	r  buyRig        —
//	m  moveRoom      —
//	u  upgradeWatch  —
//
// Claims are not loggable: collecting happens only as the transaction
// itself, at block time, so the monitoring window cannot be faked.
//
// Which lines are replayed: a malformed log (bad syntax, unknown op, too
// long, a claim line, a timestamp more than MaxAhead past block time) aborts
// the whole Collect. Any other line that cannot be replayed is skipped and
// reported, and the Collect still collects at block time, so a stale log can
// never lock a player out: lines dated at or before the last Collect, out of
// order, more than MaxBackdate before block time, at or after the end of the
// farm's season, in a season that has already ended, or refused by the
// economy.
//
// The log is written by the client. The realm checks that every action is
// legal at its timestamp, not that a person made it then. Backdating gives
// no hindsight: prices, events, offers and the network are pure functions
// of the day and the season, so a whole season can be planned on day 1.
// What a script can do is play that plan perfectly, in real time or inside
// the MaxBackdate window, with the same result. Bot play is an open point
// for mainnet: it needs randomness the chain reveals over time, not a
// shorter window.
//
// Upgrade path (admin, see admin.gno): Halt stops Join and Collect for good,
// SetSuccessor names the next realm, ProposeAdmin/AcceptAdmin hand the admin
// role over. No admin function can edit player values, logs or badges.
//
// Gas and storage (filetests z1–z9, gno v1.8.0 tree fc79041, 2026-11-19).
// On chain every transaction also pays ≈ 4.4M for loading the economy
// package and 59k per store read: a daily Collect that is 23M here is ≈ 39M
// on a local chain (see docs/design.md). Join ≈ 2.8M gas and ≈ 3.1 KB
// (the first player of a season ≈ 5.4 KB, with the season record); the daily
// Collect of an 80-card data-center farm (10 actions over 24 h) ≈ 23M gas and
// +32 bytes; the whole 80-card farm ≈ 5.6 KB; the rollover of that farm
// ≈ 9M gas (+4.2 KB for the first entrant into a season: the season record;
// ≈ +50 bytes for everyone after); storing the cutoffs of a 1000-player
// season ≈ 7M gas. Of a Collect, about 3M is decoding the farm, 3M encoding
// it and about 3M the projection (one settle step per hour of the monitoring
// window). 500 short actions ≈ 0.46G for a new farm and ≈ 0.56G on the
// 80-card farm. Each logged action costs about 1–4M (it settles the farm
// first), an ocMany line about 0.06M more per listed card, and every log
// byte about 10k to parse: clients should Collect after a few dozen actions
// at most. A ladder histogram entry (a distinct result of at least Pearl) is
// an avl node of ≈ 2 KB.
package miner

import (
	"chain"
	"strconv"
	"strings"
	"time"

	"gno.land/p/nt/avl/v0"

	eco "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2"
)

const (
	// RulesVersion is reported by Season() so the client can tell which
	// rules the realm replays with. 2: strict season end, projections,
	// rank badges at the season end (no FinalizeSeason).
	RulesVersion = 2

	MaxLogLines = 500
	MaxLogBytes = 20000
	// MaxCardIDs: card ids on one C line, ranges expanded.
	MaxCardIDs = 1000
	// MaxLogCardIDs: card ids in a whole log, ranges expanded (a farm has at
	// most 112 cards, so even a long day's log stays far below it).
	MaxLogCardIDs = 2000
	// MaxAhead: a device clock may run a little ahead of block time. Log
	// timestamps up to this many ms after block time are accepted and
	// replayed at block time.
	MaxAhead int64 = 120000
	// MaxBackdate: log lines dated more than this many ms before block time
	// are skipped ("Too old"). 72 h covers the longest monitoring window
	// (48 h) plus slack for a player who comes back late.
	MaxBackdate int64 = 72 * 3600 * 1000

	// Messages of skipped log lines (besides the economy's own).
	ErrBeforeCollect = "Before the last Collect"
	ErrOutOfOrder    = "Out of order"
	ErrTooOld        = "Too old"
	ErrAfterSeason   = "After your season ended"
	ErrSeasonEnded   = "Season ended"

	// TopN: rows of the top results on the main page; SeasonRows: on a
	// season page.
	TopN       = 20
	SeasonRows = 100
)

var (
	admin   = address("g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06")
	start   int64    // ms of season 1 start, 0 = not started
	players avl.Tree // address string -> *player

	seasonMs = int64(eco.Net.SeasonDays) * eco.Day

	testNow int64 // tests set this (ms); 0 = block time
)

// player is one wallet's record: primitive fields and the farm as one
// compact string.
type player struct {
	farm        string // eco.Encode of the farm (as of the last Join/Collect)
	season      int    // the farm's season
	proj        int64  // projected result of that season (see the package comment)
	lastCollect int64  // block time (ms) of the last Collect, or of the Join
	collects    int
}

// farmOf decodes the player's farm. The realm wrote it, so it always
// decodes.
func farmOf(p *player) *eco.State {
	st, err := eco.Decode(p.farm)
	if err != nil {
		panic("corrupt farm record")
	}
	return st
}

func now() int64 {
	if testNow != 0 {
		return testNow
	}
	return time.Now().UnixMilli()
}

// seasonAt is the season number at t (ms), 0 before the first season.
func seasonAt(t int64) int {
	if start == 0 || t < start {
		return 0
	}
	return int((t-start)/seasonMs) + 1
}

// seasonStartOf is the start (ms) of season n >= 1.
func seasonStartOf(n int) int64 {
	return start + int64(n-1)*seasonMs
}

// seasonEndOf is the end (ms) of season n >= 1: its results are final from
// this moment on.
func seasonEndOf(n int) int64 {
	return seasonStartOf(n) + seasonMs
}

// ended: season n is over at block time t (t >= its end; no overflow for
// any n).
func ended(n int, t int64) bool {
	return n < seasonAt(t)
}

// Start opens season 1 at startMs (unix ms, not in the past). Admin only;
// it can be changed until the first season has begun.
func Start(cur realm, startMs int64) {
	onlyAdmin(cur.Previous().Address())
	notHalted()
	if start != 0 && now() >= start {
		panic("season already running")
	}
	if startMs <= 0 {
		panic("bad start time")
	}
	if startMs < now() {
		panic("start time is in the past")
	}
	start = startMs
	chain.Emit("SeasonStart", "start", strconv.FormatInt(start, 10))
}

func mustOpen(t int64) int {
	n := seasonAt(t)
	if n == 0 {
		panic("the first season has not started yet")
	}
	return n
}

// Join creates the caller's farm at block time, in the current season, and
// returns its state JSON (the economy.js save format). A player who joins
// mid-season gets the newcomer boost. For an existing player it only rolls
// an ended season over (see the package comment) and returns the state;
// actions dated before that moment can no longer be replayed.
func Join(cur realm) string {
	if !cur.Previous().IsUserCall() {
		panic("join directly from a wallet")
	}
	notHalted()
	key := cur.Previous().Address().String()
	t := now()
	n := mustOpen(t)
	defer cacheLast(n)
	if v := players.Get(key); v != nil {
		p := v.(*player)
		st := farmOf(p)
		if p.season < n {
			st = rollover(key, p, st, n, t)
			p.lastCollect = t
			out := st.JSON()
			save(p, st, true)
			return out
		}
		return st.JSON()
	}
	st := eco.NewState(t) // Last = LastClaim = Born = t
	st.Season = n
	st.SeasonStart = seasonStartOf(n)
	p := &player{lastCollect: t}
	out := st.JSON()
	save(p, st, true)
	players.Set(key, p)
	chain.Emit("Join", "player", key, "season", strconv.Itoa(n), "projection", strconv.FormatInt(p.proj, 10))
	return out
}

// action is one parsed log line.
type action struct {
	ts   int64 // replay time: the logged time, clamped to block time
	raw  int64 // the logged time
	op   byte
	x    [3]int
	ids  []int
	line int
	err  string // set: the line is skipped with this message
}

// Collect replays the caller's action log, then collects at block time.
// It returns {"applied":n,"skipped":[{"i":k,"err":"…"}],"season":…,
// "projection":…}: season is the farm's season after it, projection its
// projected season result (see the package comment). The farm itself
// (wallet, value, …) is read with State: formatting its floats here would
// cost every Collect gas for numbers the client reads anyway. A malformed log aborts the
// whole transaction (see the package comment). Every other line that
// cannot be replayed is skipped and reported with its line index i
// (0-based) and a message: an economy refusal (for example "Not enough
// BLK" after a tiny rounding difference), ErrBeforeCollect, ErrOutOfOrder,
// ErrTooOld, ErrAfterSeason (dated at or after the end of the farm's
// season) or ErrSeasonEnded (the farm's season ended before this Collect:
// the farm enters the current season at block time, after the replay).
func Collect(cur realm, log string) string {
	if !cur.Previous().IsUserCall() {
		panic("collect directly from a wallet")
	}
	notHalted()
	key := cur.Previous().Address().String()
	t := now()
	n := mustOpen(t)
	v := players.Get(key)
	if v == nil {
		panic("join first")
	}
	defer cacheLast(n)
	p := v.(*player)
	acts := parseLog(log, p.lastCollect, t)
	st := farmOf(p)

	applied := 0
	var skipped strings.Builder
	nSkipped := 0
	esc := map[string]string{} // escaped error texts (a handful of distinct ones)
	skip := func(line int, msg string) {
		e, ok := esc[msg]
		if !ok {
			e = jsonStr(msg)
			esc[msg] = e
		}
		if nSkipped > 0 {
			skipped.WriteByte(',')
		}
		skipped.WriteString(`{"i":`)
		skipped.WriteString(strconv.Itoa(line))
		skipped.WriteString(`,"err":`)
		skipped.WriteString(e)
		skipped.WriteByte('}')
		nSkipped++
	}
	end := seasonEndOf(p.season)
	over := t >= end // the farm's season has ended: nothing changes it now
	for _, a := range acts {
		switch {
		case a.err != "":
			skip(a.line, a.err)
		case a.raw >= end:
			skip(a.line, ErrAfterSeason)
		case over:
			skip(a.line, ErrSeasonEnded)
		default:
			if err := apply(st, a); err != nil {
				skip(a.line, err.Error())
				continue
			}
			applied++
		}
	}
	if over {
		st = rollover(key, p, st, n, t)
	}
	st.Claim(t)
	p.lastCollect = t
	p.collects++

	season := strconv.Itoa(st.Season)
	save(p, st, over)
	proj := strconv.FormatInt(p.proj, 10)
	nApplied := strconv.Itoa(applied)
	chain.Emit("Collect",
		"player", key,
		"season", season,
		"applied", nApplied,
		"skipped", strconv.Itoa(nSkipped),
		"projection", proj)
	return `{"applied":` + nApplied + `,"skipped":[` + skipped.String() + `],"season":` + season +
		`,"projection":` + proj + `}`
}

func apply(st *eco.State, a action) error {
	var err error
	switch a.op {
	case 'b':
		_, err = st.BuyCard(a.x[0], a.ts, a.x[1] == 1)
	case 'o':
		_, err = st.BuyOffer(a.x[0], a.ts)
	case 's':
		_, err = st.SellCard(a.x[0], a.ts)
	case 'c':
		_, err = st.Overclock(a.x[0], a.ts)
	case 'C':
		_, err = st.OCMany(a.ids, a.ts)
	case 'w':
		_, err = st.RigSwap(a.x[0], a.x[1], a.ts, a.x[2] == 1)
	case 'r':
		_, err = st.BuyRig(a.ts)
	case 'm':
		_, err = st.MoveRoom(a.ts)
	case 'u':
		_, err = st.UpgradeWatch(a.ts)
	}
	return err
}

// parseLog checks the whole log before anything is applied, in one pass
// over its bytes (every byte touched costs gas). after: the previous
// Collect (or Join) time; t: block time. Timestamps up to MaxAhead past
// block time are clamped to block time (a.raw keeps the logged one). A
// line is marked skipped (a.err) when its timestamp is not after `after`,
// more than MaxBackdate before t, or before an earlier replayed line; it is
// still checked for syntax. One trailing newline is allowed.
func parseLog(log string, after, t int64) []action {
	n := len(log)
	if n == 0 {
		return nil
	}
	if n > MaxLogBytes {
		panic("log too long: at most " + strconv.Itoa(MaxLogBytes) + " bytes, Collect more often")
	}
	out := []action{}
	idsTotal := 0
	prev := after
	i := 0
	for line := 0; i < n; line++ {
		if line >= MaxLogLines {
			panic("log too long: at most " + strconv.Itoa(MaxLogLines) + " actions, Collect more often")
		}
		// ts
		var ts int64
		j := i
		for i < n {
			c := log[i]
			if c < '0' || c > '9' {
				break
			}
			ts = ts*10 + int64(c-'0')
			i++
		}
		if i == n || log[i] == '\n' {
			bad(line, "want ts|op|args")
		}
		if i == j || i-j > 15 || log[i] != '|' {
			bad(line, "timestamp must be an integer (ms)")
		}
		if ts > t+MaxAhead {
			bad(line, "timestamp is in the future")
		}
		raw := ts
		if ts > t {
			ts = t
		}
		a := action{ts: ts, raw: raw, line: line}
		switch {
		case ts <= after:
			a.err = ErrBeforeCollect
		case ts < t-MaxBackdate:
			a.err = ErrTooOld
		case ts < prev:
			a.err = ErrOutOfOrder
		default:
			prev = ts
		}
		// op
		i++
		if i+1 >= n || log[i] == '\n' {
			bad(line, "want ts|op|args")
		}
		a.op = log[i]
		i++
		if log[i] != '|' {
			bad(line, "unknown op")
		}
		i++
		// args, up to the end of the line
		switch a.op {
		case 'b', 'w', 'o', 's', 'c':
			k := 1
			if a.op == 'b' {
				k = 2
			} else if a.op == 'w' {
				k = 3
			}
			for m := 0; m < k; m++ {
				v, end := readUint(log, i, n)
				if end == i {
					bad(line, "arguments must be integers")
				}
				a.x[m] = v
				i = end
				last := m == k-1
				if i < n && log[i] == ',' && !last {
					i++
					continue
				}
				if (i == n || log[i] == '\n') && last {
					break
				}
				if i < n && log[i] != ',' && log[i] != '\n' {
					bad(line, "arguments must be integers")
				}
				bad(line, "want "+strconv.Itoa(k)+" comma separated integers")
			}
			if a.op == 'b' && a.x[1] > 1 || a.op == 'w' && a.x[2] > 1 {
				bad(line, "rgb must be 0 or 1")
			}
		case 'C':
			// The longest lines: the digits are read here, not by
			// readUint (a call per id costs gas).
			a.ids = []int{}
			for i < n {
				c := log[i]
				if c == '\n' {
					break
				}
				v, j := 0, i
				for c >= '0' && c <= '9' {
					v = v*10 + int(c-'0')
					i++
					if i == n {
						break
					}
					c = log[i]
				}
				if i == j || i-j > 9 {
					bad(line, "card ids must be integers")
				}
				if c == '-' && i < n { // a range v-w: v, v+1, …, w
					i++
					if i == n {
						bad(line, "card ids must be integers")
					}
					c = log[i]
					w := 0
					j = i
					for c >= '0' && c <= '9' {
						w = w*10 + int(c-'0')
						i++
						if i == n {
							break
						}
						c = log[i]
					}
					if i == j || i-j > 9 {
						bad(line, "card ids must be integers")
					}
					if w < v {
						bad(line, "a card id range must ascend")
					}
					if len(a.ids)+w-v >= MaxCardIDs {
						bad(line, "too many card ids: at most "+strconv.Itoa(MaxCardIDs))
					}
					for ; v <= w; v++ {
						a.ids = append(a.ids, v)
					}
				} else {
					if len(a.ids) >= MaxCardIDs {
						bad(line, "too many card ids: at most "+strconv.Itoa(MaxCardIDs))
					}
					a.ids = append(a.ids, v)
				}
				if i == n || c == '\n' {
					break
				}
				if c != ';' {
					bad(line, "card ids must be integers")
				}
				i++
				if i == n || log[i] == '\n' {
					bad(line, "card ids must be integers")
				}
			}
		case 'r', 'm', 'u':
			if i < n && log[i] != '\n' {
				bad(line, "this op takes no arguments")
			}
		case 'K':
			bad(line, "claims cannot be logged: the Collect transaction itself collects at block time")
		default:
			bad(line, "unknown op")
		}
		idsTotal += len(a.ids)
		if idsTotal > MaxLogCardIDs {
			bad(line, "too many card ids in one log: at most "+strconv.Itoa(MaxLogCardIDs)+", Collect more often")
		}
		out = append(out, a)
		i++ // the newline (or past the end)
	}
	return out
}

func bad(line int, why string) {
	panic("log entry " + strconv.Itoa(line) + ": " + why)
}

// readUint reads up to 9 decimal digits from s at i; n = len(s) (a len
// call per byte costs gas). end == i: no digit.
func readUint(s string, i, n int) (v, end int) {
	end = i
	for end < n && end-i < 10 {
		c := s[end]
		if c < '0' || c > '9' {
			break
		}
		v = v*10 + int(c-'0')
		end++
	}
	if end-i > 9 {
		return 0, i // too long: reported as not an integer
	}
	return v, end
}


// State returns the player's state JSON (the economy.js save format, as of
// the last Join or Collect), or "" for an address that has not joined.
func State(addr address) string {
	v := players.Get(addr.String())
	if v == nil {
		return ""
	}
	return farmOf(v.(*player)).JSON()
}

// Season returns the season clock as JSON:
// {"start","season","seasonStart","seasonEnd","day","players","rules",
// "halted","haltReason","successor"}. Times are unix ms; day is the
// current season day 1..28; seasonEnd is the second at which the current
// season's results become final. Before the first season, season,
// seasonStart, seasonEnd and day are 0. players: every address that has
// joined. halted: Join and Collect are stopped for good (see Halt);
// successor: the package path of the next realm, "" if none.
func Season() string {
	t := now()
	n := seasonAt(t)
	var ss, se int64
	day := 0
	if n > 0 {
		ss = seasonStartOf(n)
		se = ss + seasonMs
		day = int((t-ss)/eco.Day) + 1
	}
	return `{"start":` + strconv.FormatInt(start, 10) +
		`,"season":` + strconv.Itoa(n) +
		`,"seasonStart":` + strconv.FormatInt(ss, 10) +
		`,"seasonEnd":` + strconv.FormatInt(se, 10) +
		`,"day":` + strconv.Itoa(day) +
		`,"players":` + strconv.Itoa(players.Size()) +
		`,"rules":` + strconv.Itoa(RulesVersion) +
		`,"halted":` + strconv.FormatBool(halted) +
		`,"haltReason":` + jsonStr(haltReason) +
		`,"successor":` + jsonStr(successor) + `}`
}

func jsonStr(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case c == '"':
			b.WriteString(`\"`)
		case c == '\\':
			b.WriteString(`\\`)
		case c < 0x20:
			const hexd = "0123456789abcdef"
			b.WriteString(`\u00`)
			b.WriteByte(hexd[c>>4])
			b.WriteByte(hexd[c&15])
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('"')
	return b.String()
}

package miner

import (
	"strconv"
	"strings"
	"time"

	eco "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2"
)

// Render shows the current season (path ""), one season's results
// ("season/<n>") or one player's page ("<address>"). It reads the season
// records and at most one player; it never scans all players. Seasons keep
// no per-player index, so the result tables list results and how many
// players reached each, not who.
func Render(path string) string {
	if path == "" {
		return renderHome()
	}
	if strings.HasPrefix(path, "season/") {
		n, err := strconv.Atoi(path[len("season/"):])
		if err != nil || n < 1 {
			return "# Not found\n\nNo such season.\n"
		}
		return renderSeason(n)
	}
	return renderPlayer(path)
}

// badgeRule explains the badge rule in one paragraph.
func badgeRule() string {
	var t strings.Builder
	for i, bd := range eco.Badges {
		if i > 0 {
			t.WriteString(" · ")
		}
		t.WriteString(bd.Name + " " + fmtInt(bd.Min))
	}
	return "**Badges.** Every badge is a value threshold: " + t.String() + ". A result earns the highest " +
		"threshold it reaches. There is no limit on how many players earn a badge, and no other account can take " +
		"one away or add one. A season's results and badges are final at its end, to the second; actions that " +
		"reach the chain later do not count.\n\n"
}

// notice: the halt banner and the successor link, "" if neither.
func notice() string {
	s := ""
	if halted {
		s += "> **Halted:** " + haltReason + "\n>\n> Join and Collect are closed for good. Everything recorded so far " +
			"stays readable here; every player's last projection is their result.\n\n"
	}
	if successor != "" {
		s += "> **Next version:** the game continues at [" + successor + "](" + successor[len("gno.land"):] + ").\n\n"
	}
	return s
}

func renderHome() string {
	t := now()
	n := seasonAt(t)
	var b strings.Builder
	b.WriteString("# Coblyn\n\n")
	b.WriteString(notice())
	switch {
	case start == 0:
		b.WriteString("The first season has not started yet.\n\n")
	case n == 0:
		b.WriteString("Season 1 opens " + fmtTime(start) + ".\n\n")
	default:
		ss := seasonStartOf(n)
		day := int((t-ss)/eco.Day) + 1
		b.WriteString("Season **" + strconv.Itoa(n) + "** · day **" + strconv.Itoa(day) + " / " +
			strconv.Itoa(eco.Net.SeasonDays) + "** · ends " + fmtTime(ss+seasonMs) + ", results final at that second\n\n")
	}
	b.WriteString("Every value here is computed on chain: each Collect sends the player's logged actions, and this realm " +
		"replays them with `gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2`, the same economy " +
		"the game runs in the browser, then collects at block time.\n\n")

	if n > 0 {
		b.WriteString("## Season " + strconv.Itoa(n) + " · if it ended now\n\n")
		r := recOf(n)
		if r == nil || r.ladder.Players == 0 {
			b.WriteString("Nobody has played this season yet.\n\n")
		} else {
			writeResults(&b, r, cutsOf(n), TopN)
			b.WriteString("Results are projections: what each farm reaches by the season end if its player does nothing " +
				"more (mining stops when the monitoring window runs out).\n\n")
		}
		b.WriteString(badgeRule())
	}
	b.WriteString("Players: " + strconv.Itoa(players.Size()) + "\n\n")

	if n > 1 {
		b.WriteString("## Past seasons\n\n")
		for s := 1; s < n; s++ {
			r := recOf(s)
			if r == nil || r.ladder.Players == 0 {
				continue
			}
			c := cutsOf(s)
			b.WriteString("- [Season " + strconv.Itoa(s) + "](:season/" + strconv.Itoa(s) + ") · final · players " +
				strconv.Itoa(r.ladder.Players) + " · Diamond " + strconv.Itoa(c.NDiamond) +
				" · Sapphire " + strconv.Itoa(c.NSapphire) + "\n")
		}
		b.WriteString("\n")
	}
	b.WriteString("---\n\nA [Hazen Network Solutions](https://hazennetworksolutions.com) game.\n")
	return b.String()
}

// writeResults writes a season's counts, the Diamond and Sapphire counts and
// its best results (at most rows distinct results of at least Pearl).
func writeResults(b *strings.Builder, r *seasonRec, c eco.Cuts, rows int) {
	l := &r.ladder
	b.WriteString("Players: " + strconv.Itoa(l.Players) + " · at Copper or above: " + strconv.Itoa(l.Counted) +
		" · at Pearl or above: " + strconv.Itoa(l.PearlPlus) + "\n\n")
	b.WriteString("- Diamond (results of at least **" + fmtInt(float64(c.Diamond)) + "**): " + strconv.Itoa(c.NDiamond) + " players\n")
	b.WriteString("- Sapphire (results of at least **" + fmtInt(float64(c.Sapphire)) + "**): " + strconv.Itoa(c.NSapphire) + " players\n\n")
	if l.PearlPlus == 0 {
		return
	}
	b.WriteString("| # | Result | Players | Badge |\n|---|---|---|---|\n")
	above := 0
	l.Top(rows, func(v int64, k int) bool {
		b.WriteString("| " + strconv.Itoa(above+1) + " | " + fmtInt(float64(v)) + " | " + strconv.Itoa(k) + " | " +
			badgeName(eco.RankBadge(v)) + " |\n")
		above += k
		return false
	})
	b.WriteString("\n")
}

func orDash(s string) string {
	if s == "" {
		return "—"
	}
	return s
}

func renderSeason(n int) string {
	var b strings.Builder
	b.WriteString("# Coblyn · Season " + strconv.Itoa(n) + "\n\n")
	b.WriteString(notice())
	t := now()
	if start == 0 || n > seasonAt(t) {
		b.WriteString("This season has not started yet.\n")
		return b.String()
	}
	ss := seasonStartOf(n)
	end := ss + seasonMs
	b.WriteString(fmtTime(ss) + " – " + fmtTime(end) + "\n\n")
	if ended(n, t) {
		b.WriteString("**Final** since " + fmtTime(end) + ".\n\n")
	} else {
		b.WriteString("Running. Results are projections and badges are as if the season ended now; both are final at " +
			fmtTime(end) + ".\n\n")
	}
	r := recOf(n)
	if r == nil || r.ladder.Players == 0 {
		b.WriteString("Nobody played this season.\n")
		return b.String()
	}
	b.WriteString("## Results\n\n")
	writeResults(&b, r, cutsOf(n), SeasonRows)
	b.WriteString(badgeRule())
	return b.String()
}

func renderPlayer(key string) string {
	// only a valid address is echoed back into the page
	if !address(key).IsValid() {
		return "# Not found\n\nNo such page.\n"
	}
	var b strings.Builder
	b.WriteString("# " + key + "\n\n")
	b.WriteString(notice())
	v := players.Get(key)
	if v == nil {
		b.WriteString("This address has no farm on chain yet.\n")
		return b.String()
	}
	p := v.(*player)
	st := farmOf(p)
	badge := orDash(badgeName(eco.RankBadge(p.proj)))
	place := ""
	if r := recOf(p.season); r != nil && r.ladder.Players > 0 {
		ahead, tied := r.ladder.Place(p.proj)
		if tied < 1 {
			tied = 1
		}
		place = " · place **#" + strconv.Itoa(ahead+1)
		if tied > 1 {
			place += "–" + strconv.Itoa(ahead+tied)
		}
		place += "** of " + strconv.Itoa(r.ladder.Players)
	}
	b.WriteString("## Season " + strconv.Itoa(p.season) + "\n\n")
	if ended(p.season, now()) {
		b.WriteString("Ended. Final result: **" + fmtInt(float64(p.proj)) + "** · badge: **" + badge + "**" + place + ". " +
			"The farm enters the current season at the player's next Join or Collect.\n\n")
	} else {
		b.WriteString("- Projected result: **" + fmtInt(float64(p.proj)) + "** · badge if the season ended now: **" + badge + "**" + place + "\n")
		b.WriteString("- At the last Collect: value " + fmtInt(st.Value) + " · mined " + fmtInt(st.Mined) + " " + eco.Token +
			" · wallet " + fmtInt(st.Wallet) + " " + eco.Token + "\n")
		b.WriteString("- Facility: " + eco.Rooms[st.Room].Name + " · rigs: " + strconv.Itoa(len(st.Rigs)) +
			" · cards: " + strconv.Itoa(len(st.Cards)) + " · monitoring: " + strconv.Itoa(st.WatchHours()) + " h\n")
		b.WriteString("- Last Collect: " + fmtTime(p.lastCollect) + " · Collects: " + strconv.Itoa(p.collects) + "\n\n")
		b.WriteString("The projection is what the farm reaches by the season end (" + fmtTime(seasonEndOf(p.season)) +
			") if the player does nothing more; it is final then.\n\n")
	}
	b.WriteString("## History\n\n")
	if len(st.History) == 0 {
		b.WriteString("No finished season yet.\n")
		return b.String()
	}
	b.WriteString("| Season | Badge | Value | Facility |\n|---|---|---|---|\n")
	for i := len(st.History) - 1; i >= 0; i-- {
		h := st.History[i]
		b.WriteString("| [" + strconv.Itoa(h.Season) + "](:season/" + strconv.Itoa(h.Season) + ") | " + orDash(h.Badge) +
			" | " + fmtInt(h.Value) + " | " + eco.Rooms[h.Room].Name + " |\n")
	}
	return b.String()
}

// fmtInt rounds x and groups thousands: 1234567.6 -> "1,234,568".
func fmtInt(x float64) string {
	v := int64(eco.JSRound(x))
	neg := v < 0
	if neg {
		v = -v
	}
	s := strconv.FormatInt(v, 10)
	var b strings.Builder
	if neg {
		b.WriteByte('-')
	}
	for i := 0; i < len(s); i++ {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteByte(',')
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

func fmtTime(ms int64) string {
	return time.Unix(ms/1000, 0).UTC().Format("2006-01-02 15:04:05 UTC")
}

package miner

import (
	"chain"
	"strconv"

	"gno.land/p/nt/avl/v0"

	eco "gno.land/p/g1jz6j9hj6rdf5ltl2kcrpa4jwtdh3w30z0yul06/coblyn/miner/v2"
)

// Seasons and badges on chain
//
// A season's result for a player is their projection for it (see the
// package comment): the farm's season value, rounded, if the player does
// nothing more. Badges are fixed value thresholds, Copper … Diamond
// (eco.Badges): a result earns the highest threshold it reaches, whatever
// other players do, so no number of other accounts can take a badge away
// or create one. Each season keeps an eco.Ladder of its players' results
// for places, the results table and the badge counts.
//
// The ladder moves with the projections while the season runs, so its
// badges are "if the season ended now". At the season end the projections
// are final. The first Join or Collect (by anyone) after the season ended
// stores the season's badge counts in its record (event SeasonFinal). A
// player's history entry gets the final badge when their farm rolls over
// (event SeasonEnd).

var (
	seasons avl.Tree // seasonKey(n) -> *seasonRec

	copperMin = eco.Badges[eco.CopperIdx].Min
	pearlMin  = eco.Badges[eco.PearlIdx].Min
)

// seasonRec is one season's results: no per-player entry.
type seasonRec struct {
	ladder eco.Ladder
	final  bool     // badge counts are stored (the season has ended)
	cuts   eco.Cuts // valid when final
}

func pad15(x int64) string {
	s := strconv.FormatInt(x, 10)
	return "000000000000000"[len(s):] + s
}

func seasonKey(n int) string { return pad15(int64(n)) }

func recOf(n int) *seasonRec {
	v := seasons.Get(seasonKey(n))
	if v == nil {
		return nil
	}
	return v.(*seasonRec)
}

func rec(n int) *seasonRec {
	r := recOf(n)
	if r == nil {
		r = &seasonRec{}
		seasons.Set(seasonKey(n), r)
	}
	return r
}

// badgeName of a badge index, "" for none (-1).
func badgeName(i int) string {
	if i < 0 {
		return ""
	}
	return eco.Badges[i].Name
}

// project: the farm's projected season result, rounded. It settles st up
// to the season end (Settle stops at the monitoring window), so st must not
// be used afterwards.
func project(st *eco.State) int64 {
	st.Settle(st.SeasonEnd())
	v := eco.JSRound(st.Value)
	if v < 0 {
		return 0
	}
	return int64(v)
}

// save stores the farm and its projection. entered: the farm has just
// entered season st.Season (Join or rollover); otherwise its projection
// moves within that season's ladder. Only called before the farm's season
// ends, so an ended season's ladder never changes. st is spent afterwards.
func save(p *player, st *eco.State, entered bool) {
	p.farm = eco.Encode(st)
	v := project(st)
	r := rec(st.Season)
	if entered {
		r.ladder.Add(v)
	} else {
		r.ladder.Move(p.proj, v)
	}
	p.proj = v
	p.season = st.Season
}

// cutsOf: season n's Sapphire/Diamond thresholds and counts, stored ones if
// final, else as of now.
func cutsOf(n int) eco.Cuts {
	r := recOf(n)
	if r == nil {
		return eco.Cuts{}
	}
	if r.final {
		return r.cuts
	}
	return r.ladder.Cuts()
}

// finalCuts stores the badge counts of season n, which has ended, unless
// that is done already, and returns them.
func finalCuts(n int) eco.Cuts {
	r := recOf(n)
	if r == nil {
		return eco.Cuts{}
	}
	if !r.final {
		r.cuts = r.ladder.Cuts()
		r.final = true
		chain.Emit("SeasonFinal",
			"season", strconv.Itoa(n),
			"players", strconv.Itoa(r.ladder.Players),
			"counted", strconv.Itoa(r.ladder.Counted),
			"diamond", strconv.Itoa(r.cuts.NDiamond),
			"sapphire", strconv.Itoa(r.cuts.NSapphire),
			"diamondCutoff", strconv.FormatInt(r.cuts.Diamond, 10),
			"sapphireCutoff", strconv.FormatInt(r.cuts.Sapphire, 10))
	}
	return r.cuts
}

// cacheLast: run at the end of every Join and Collect in season n; stores
// the previous season's badge counts the first time.
func cacheLast(n int) {
	if n > 1 {
		finalCuts(n - 1)
	}
}

// rollover ends the farm's season (over at block time t) and returns the
// farm's start state in season n at t. The result is the stored
// projection: the farm cannot have changed since it was computed, and
// settling it to the season end (done here, for the history entry's
// "mined") gives the same value. The badge is the result's threshold badge; the
// next season starts with that badge's cards. The farm is no newcomer
// there (Born = season start) and mines nothing for the time away.
func rollover(key string, p *player, st *eco.State, n int, t int64) *eco.State {
	f := p.season
	finalCuts(f)
	b := eco.RankBadge(p.proj)
	next := st.NewSeason(st.SeasonEnd(), "")
	h := &next.History[len(next.History)-1]
	h.Value = float64(p.proj)
	h.Badge = badgeName(b)
	cards := []int{1}
	if b >= 0 {
		cards = eco.Badges[b].Start
	}
	next.Cards = map[int]*eco.Card{}
	next.Rigs = [][]int{{0, 0, 0, 0}} // as eco.NewSeason
	for k, ty := range cards {
		next.Cards[k+1] = &eco.Card{T: ty}
		next.Rigs[0][k] = k + 1
	}
	next.NextID = len(cards) + 1
	ss := seasonStartOf(n)
	next.Season = n
	next.SeasonStart = ss
	next.Born = ss
	next.Last = t
	next.LastClaim = t
	chain.Emit("SeasonEnd",
		"player", key,
		"season", strconv.Itoa(f),
		"value", strconv.FormatInt(p.proj, 10),
		"badge", h.Badge)
	return next
}

// PlayerSeason returns the player's latest season result as JSON:
// {"season","projection","badge","final","players","ahead","tied"}.
// season: the season of the
// farm's last Join or Collect; projection: its projected result, the final
// result once the season has ended; badge: the threshold badge of that
// result ("" for none) — the final badge when final is true (the season
// has ended), else the badge "if the season ended now"; players:
// farms with a result for that season; ahead and tied: the player's place
// among them (eco.Ladder.Place: exact at or above Pearl, the badge band
// below it). "" for an address that has not joined.
func PlayerSeason(addr address) string {
	v := players.Get(addr.String())
	if v == nil {
		return ""
	}
	p := v.(*player)
	fin := ended(p.season, now())
	pl, ahead, tied := 0, 0, 0
	if r := recOf(p.season); r != nil {
		pl = r.ladder.Players
		ahead, tied = r.ladder.Place(p.proj)
	}
	return `{"season":` + strconv.Itoa(p.season) +
		`,"projection":` + strconv.FormatInt(p.proj, 10) +
		`,"badge":` + jsonStr(badgeName(eco.RankBadge(p.proj))) +
		`,"final":` + strconv.FormatBool(fin) +
		`,"players":` + strconv.Itoa(pl) +
		`,"ahead":` + strconv.Itoa(ahead) +
		`,"tied":` + strconv.Itoa(tied) + `}`
}

// SeasonResult returns season n's results as JSON: {"season","ended",
// "players","counted","pearlPlus","diamondCutoff","sapphireCutoff",
// "diamond","sapphire"}. ended: the results are final; players: farms with
// a result for the season; counted: results of at least Copper;
// pearlPlus: results of at least Pearl; diamondCutoff and sapphireCutoff
// are the fixed Diamond and Sapphire thresholds; diamond and sapphire how
// many players reach them (Diamond not counted in sapphire). Before the
// season ends these are
// "if the season ended now". n must be at least 1; a season that has not
// started yet has no results.
func SeasonResult(n int) string {
	if n < 1 {
		panic("no such season")
	}
	pl, cnt, pp := 0, 0, 0
	c := eco.Cuts{Diamond: int64(eco.Badges[eco.DiamondIdx].Min), Sapphire: int64(eco.Badges[eco.SapphireIdx].Min)}
	if r := recOf(n); r != nil {
		pl, cnt, pp = r.ladder.Players, r.ladder.Counted, r.ladder.PearlPlus
		c = cutsOf(n)
	}
	return `{"season":` + strconv.Itoa(n) +
		`,"ended":` + strconv.FormatBool(ended(n, now())) +
		`,"players":` + strconv.Itoa(pl) +
		`,"counted":` + strconv.Itoa(cnt) +
		`,"pearlPlus":` + strconv.Itoa(pp) +
		`,"diamondCutoff":` + strconv.FormatInt(c.Diamond, 10) +
		`,"sapphireCutoff":` + strconv.FormatInt(c.Sapphire, 10) +
		`,"diamond":` + strconv.Itoa(c.NDiamond) +
		`,"sapphire":` + strconv.Itoa(c.NSapphire) + `}`
}

package coppermug

import (
	"chain/runtime"
)

// openCupErr reports whether a stake can be opened, or why not.
func openCupErr(addr string, stake int64) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if a.InCup {
		return "your cup is already on the table: roll or hold"
	}
	if stake < MinStake {
		return "the minimum stake is 10 gold"
	}
	if stake > a.Gold {
		return "you cannot stake gold you do not have"
	}
	return ""
}

// OpenCup puts a stake on the table and starts a run.
//
// The rules are simple: roll a d6.
//   - 1 busts the run and the stake is gone
//   - 2-5 adds half the stake to the pot
//   - 6 multiplies the pot by 1.2
//
// You may Hold at any time and take the pot. Gold is tavern money and is
// worth nothing outside this realm.
func OpenCup(cur realm, stake int64) {
	addr, _ := caller(cur)
	if msg := openCupErr(addr, stake); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	a.Gold -= stake
	a.InCup = true
	a.Stake = stake
	a.Pot = stake
	a.Rolls = 0
	a.CupDice = nil
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	emit("CupOpen", "addr", addr, "stake", itoa(stake))
}

// rollErr reports whether a cup is on the table.
func rollErr(addr string) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if !a.InCup {
		return "no cup on the table: call OpenCup first"
	}
	return ""
}

// Roll throws the die once. It returns the die, the pot after the throw,
// and whether the run busted.
func Roll(cur realm) (int, int64, bool) {
	addr, _ := caller(cur)
	if msg := rollErr(addr); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	d := rollDie(addr)
	a.CupDice = append(a.CupDice, d)
	a.Rolls++
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	if d == 1 {
		lost := a.Stake
		a.InCup = false
		a.Losses++
		a.CupDice = nil
		a.Pot = 0
		a.Stake = 0
		a.Rolls = 0

		addPost("bust", addr, a, "cups out — the dice take **"+itoa(lost)+" gold**.")
		emit("CupBust", "addr", addr, "lost", itoa(lost))
		return d, 0, true
	}

	if d == 6 {
		a.Pot = a.Pot * 6 / 5
	} else {
		a.Pot += a.Stake / 2
	}

	emit("CupRoll", "addr", addr, "die", itoa(int64(d)), "pot", itoa(a.Pot))
	return d, a.Pot, false
}

// holdErr reports whether a cup can be banked.
func holdErr(addr string) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if !a.InCup {
		return "no cup on the table: call OpenCup first"
	}
	if a.Rolls == 0 {
		return "roll at least once before you hold"
	}
	return ""
}

// Hold banks the pot and ends the run.
func Hold(cur realm) (int64, int64) {
	addr, _ := caller(cur)
	if msg := holdErr(addr); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	payout := a.Pot
	stake := a.Stake
	a.Gold += payout
	a.InCup = false
	a.CupDice = nil
	a.Pot = 0
	a.Stake = 0
	a.Rolls = 0
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	if payout > stake {
		a.Wins++
		if payout > a.BestPot {
			a.BestPot = payout
		}
		addPost("win", addr, a, "cashes out **"+itoa(payout)+" gold** from a "+itoa(stake)+" gold cup.")
	} else if payout < stake {
		a.Losses++
		addPost("cash", addr, a, "takes **"+itoa(payout)+" gold** off a "+itoa(stake)+" gold cup and calls it a night.")
	} else {
		addPost("cash", addr, a, "walks away with their "+itoa(stake)+" gold stake intact.")
	}

	emit("CupHold", "addr", addr, "payout", itoa(payout), "stake", itoa(stake))
	return payout, a.Gold
}

package coppermug

import (
	"strings"
)

// Render is the whole front end: gnoweb serves this Markdown as the realm
// page, and the sub-pages hang off the realm's args (`/r/<pkg>:feed`).
func Render(cur realm, path string) string {
	pkg := cur.PkgPath()
	p := strings.Trim(strings.TrimSpace(path), "/")

	switch {
	case p == "":
		return renderHome(pkg)
	case p == "feed":
		return renderFeed(pkg)
	case p == "board":
		return renderBoard(pkg)
	case p == "cup":
		return renderCup(pkg)
	case p == "rules":
		return renderRules(pkg)
	case strings.HasPrefix(p, "u/"):
		return renderProfile(pkg, strings.TrimPrefix(p, "u/"))
	}
	return renderMissing(pkg, p)
}

// ---------------------------------------------------------------------------
// links
// ---------------------------------------------------------------------------

// realmBase is the URL path of this realm. gnoweb URLs drop the chain
// domain, so gno.land/r/<addr>/coppermug becomes /r/<addr>/coppermug.
func realmBase(pkg string) string {
	if i := strings.Index(pkg, "/"); i > 0 && strings.Contains(pkg[:i], ".") {
		return "/" + pkg[i+1:]
	}
	return "/" + pkg
}

func realmURL(pkg, suffix string) string {
	base := realmBase(pkg)
	if suffix == "" {
		return base
	}
	return base + ":" + suffix
}

func actionURL(pkg, fn string) string {
	return realmBase(pkg) + "$help&func=" + fn
}

func actionURL1(pkg, fn, key, value string) string {
	return realmBase(pkg) + "$help&func=" + fn + "&" + key + "=" + strings.ReplaceAll(value, " ", "%20")
}

// profileURL links to a profile, encoding the spaces names may contain.
func profileURL(pkg, name string) string {
	return realmURL(pkg, "u/"+strings.ReplaceAll(name, " ", "%20"))
}

func nav(pkg string) string {
	return "[Common room](" + realmURL(pkg, "feed") + ") · " +
		"[Board](" + realmURL(pkg, "board") + ") · " +
		"[The Cup](" + realmURL(pkg, "cup") + ") · " +
		"[House rules](" + realmURL(pkg, "rules") + ")"
}

func header(pkg string) string {
	return "# 🍺 Copper Mug\n\n" +
		"*A candle-lit room at the edge of the chain.*\n\n" +
		nav(pkg) + "\n\n---\n\n"
}

// ---------------------------------------------------------------------------
// home
// ---------------------------------------------------------------------------

func renderHome(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))

	seated := 0
	gold := int64(0)
	cups := 0
	for _, a := range seats {
		seated++
		gold += a.Gold
		if a.InCup {
			cups++
		}
	}

	b.WriteString("**" + itoa(int64(seated)) + " adventurer(s)** · **" +
		itoa(int64(len(feed))) + " tale(s) on the board** · **" +
		itoa(gold) + " gold** on the tables")
	if cups > 0 {
		b.WriteString(" · **" + itoa(int64(cups)) + " cup(s)** in play")
	}
	b.WriteString("\n\n")

	if seated == 0 {
		b.WriteString("The room is quiet. The fire is lit. The first stool is yours.\n\n")
	}

	b.WriteString("### Take a stool\n\n")
	b.WriteString("Pick a name and a trade, then call `Join`. The house stakes you **100 gold**.\n\n")
	b.WriteString("*[Join the tavern](" + actionURL(pkg, "Join") + ")*\n\n")
	b.WriteString("Trades: ⚔️ Fighter · 🗡️ Rogue · 🔮 Mage · 🎻 Bard\n\n")

	if len(feed) > 0 {
		b.WriteString("### Tonight at the mug\n\n")
		start := len(feed) - 3
		if start < 0 {
			start = 0
		}
		for i := len(feed) - 1; i >= start; i-- {
			writePost(&b, pkg, feed[i])
			b.WriteString("\n")
		}
		b.WriteString("[Read the whole board](" + realmURL(pkg, "feed") + ")\n\n")
	}

	if cups > 0 {
		b.WriteString("### Cups on the table\n\n")
		writeOpenCups(&b, pkg)
		b.WriteString("\n")
	}

	b.WriteString("### The house in three lines\n\n")
	b.WriteString("1. Every tale, tip and roll is realm state — no server, no database, no JavaScript.\n")
	b.WriteString("2. Gold is tavern money. It buys rounds and stakes cups; it is worth nothing outside.\n")
	b.WriteString("3. Cheer other people's tales. The board remembers.\n\n")

	b.WriteString("*[House rules](" + realmURL(pkg, "rules") + ") · Copper Mug v" + Version + "*\n")
	return b.String()
}

// ---------------------------------------------------------------------------
// feed
// ---------------------------------------------------------------------------

func renderFeed(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 📜 The common room\n\n")
	b.WriteString("Every line here is a transaction. Cheer the ones you like.\n\n")
	b.WriteString("*[Say something](" + actionURL(pkg, "Say") + ")*\n\n")

	if len(feed) == 0 {
		b.WriteString("> The board is blank. Somebody has to go first.\n")
		return b.String()
	}

	shown := 0
	for i := len(feed) - 1; i >= 0 && shown < 40; i-- {
		writePost(&b, pkg, feed[i])
		b.WriteString("\n")
		shown++
	}

	if len(feed) > shown {
		b.WriteString("*Older tales have been scraped off the board. The mug keeps the last " +
			itoa(int64(MaxFeed)) + ".*\n")
	}
	return b.String()
}

func writePost(b *strings.Builder, pkg string, p *Post) {
	b.WriteString("> **[" + p.Name + "](" + profileURL(pkg, p.Name) + ")** " + p.Class.Sigil() +
		" · *" + p.Class.Label() + "* · night " + itoa(p.Height))
	if len(p.Cheers) > 0 {
		b.WriteString(" · 🍻 " + itoa(int64(len(p.Cheers))))
	}
	b.WriteString(" · [cheer](" + actionURL1(pkg, "Cheer", "postID", itoa(p.ID)) + ")")
	b.WriteString("\n> " + escapeMarkdown(p.Text) + "\n")
}

// ---------------------------------------------------------------------------
// board
// ---------------------------------------------------------------------------

func renderBoard(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 🏆 The board\n\n")

	if len(seats) == 0 {
		b.WriteString("No names on the board yet.\n")
		return b.String()
	}

	b.WriteString("### Richest\n\n")
	writeTable(&b, pkg, topSeats(0, 8), 0, "Gold")

	b.WriteString("### Most renowned\n\n")
	writeTable(&b, pkg, topSeats(1, 8), 1, "Renown")

	b.WriteString("### Biggest pots\n\n")
	writeTable(&b, pkg, topSeats(2, 8), 2, "Best pot")

	b.WriteString("*Renown comes from tips received and tales cheered. Pots come from the Cup.*\n")
	return b.String()
}

// topSeats returns up to limit seats ordered by metric (0 gold, 1 renown,
// 2 best pot), with names breaking ties so the page is deterministic.
func topSeats(metric int, limit int) []*Adventurer {
	out := make([]*Adventurer, 0, limit)
	for _, a := range seats {
		v := metricValue(a, metric)
		if v <= 0 {
			continue
		}
		pos := len(out)
		for i := 0; i < len(out); i++ {
			ov := metricValue(out[i], metric)
			if v > ov || (v == ov && a.Name < out[i].Name) {
				pos = i
				break
			}
		}
		if pos >= limit {
			continue
		}
		out = append(out, nil)
		for i := len(out) - 1; i > pos; i-- {
			out[i] = out[i-1]
		}
		out[pos] = a
		if len(out) > limit {
			out = out[:limit]
		}
	}
	return out
}

func metricValue(a *Adventurer, metric int) int64 {
	switch metric {
	case 0:
		return a.Gold
	case 1:
		return a.Rep
	case 2:
		return a.BestPot
	}
	return 0
}

func writeTable(b *strings.Builder, pkg string, rows []*Adventurer, metric int, label string) {
	if len(rows) == 0 {
		b.WriteString("*Nobody yet.*\n\n")
		return
	}
	b.WriteString("| # | Adventurer | " + label + " |\n")
	b.WriteString("|---|---|---|\n")
	for i, a := range rows {
		b.WriteString("| " + itoa(int64(i+1)) + " | " +
			"[" + a.Name + "](" + profileURL(pkg, a.Name) + ") " + a.Class.Sigil() +
			" | " + itoa(metricValue(a, metric)) + " |\n")
	}
	b.WriteString("\n")
}

// ---------------------------------------------------------------------------
// cup
// ---------------------------------------------------------------------------

func renderCup(pkg string) string {
	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## 🎲 The Cup\n\n")
	b.WriteString("A push-your-luck game played for tavern gold.\n\n")
	b.WriteString("| Roll | Result |\n|---|---|\n")
	b.WriteString("| **1** | Bust — the stake is gone |\n")
	b.WriteString("| **2–5** | Pot grows by half your stake |\n")
	b.WriteString("| **6** | Pot grows by 20% |\n\n")
	b.WriteString("Roll as often as you dare, then **Hold** to bank the pot.\n\n")
	b.WriteString("*[Open a cup](" + actionURL(pkg, "OpenCup") + ") · " +
		"[Roll](" + actionURL(pkg, "Roll") + ") · " +
		"[Hold](" + actionURL(pkg, "Hold") + ")*\n\n")
	b.WriteString("Minimum stake: **10 gold**. The house does not take a cut; the dice are enough.\n\n")

	if cups := openCups(); len(cups) > 0 {
		b.WriteString("### Cups on the table\n\n")
		writeOpenCups(&b, pkg)
		b.WriteString("\n")
	}

	b.WriteString("### Biggest pots ever\n\n")
	writeTable(&b, pkg, topSeats(2, 5), 2, "Best pot")

	b.WriteString("### Fairness\n\n")
	b.WriteString("Rolls are derived from the chain height, the player's address and a realm " +
		"sequence number. That is **house randomness**: it is deterministic and a player who " +
		"can simulate the next block can predict the roll. It is fine for play money and not " +
		"fine for anything valuable. A commit-reveal scheme is the next version.\n")
	return b.String()
}

func openCups() []*Adventurer {
	var out []*Adventurer
	for _, a := range seats {
		if a.InCup {
			out = append(out, a)
		}
	}
	// Simple insertion sort by pot, descending, name as tie-break.
	for i := 1; i < len(out); i++ {
		for j := i; j > 0; j-- {
			if out[j].Pot > out[j-1].Pot ||
				(out[j].Pot == out[j-1].Pot && out[j].Name < out[j-1].Name) {
				out[j], out[j-1] = out[j-1], out[j]
				continue
			}
			break
		}
	}
	return out
}

func writeOpenCups(b *strings.Builder, pkg string) {
	cups := openCups()
	if len(cups) == 0 {
		b.WriteString("*No cups on the table right now.*\n")
		return
	}
	b.WriteString("| Adventurer | Stake | Pot | Dice |\n")
	b.WriteString("|---|---|---|---|\n")
	for _, a := range cups {
		b.WriteString("| [" + a.Name + "](" + profileURL(pkg, a.Name) + ") " + a.Class.Sigil() +
			" | " + itoa(a.Stake) + " | " + itoa(a.Pot) + " | " + diceString(a.CupDice) + " |\n")
	}
}

func diceString(dice []int) string {
	if len(dice) == 0 {
		return "—"
	}
	parts := make([]string, 0, len(dice))
	for _, d := range dice {
		parts = append(parts, itoa(int64(d)))
	}
	return strings.Join(parts, " · ")
}

// ---------------------------------------------------------------------------
// profile
// ---------------------------------------------------------------------------

func renderProfile(pkg, name string) string {
	key := strings.ToLower(strings.TrimSpace(strings.ReplaceAll(name, "%20", " ")))
	addr, ok := byName[key]
	if !ok {
		return renderMissing(pkg, "u/"+name)
	}
	a := seats[addr]

	var b strings.Builder
	b.WriteString(header(pkg))
	b.WriteString("## " + a.Name + " " + a.Class.Sigil() + "\n\n")
	b.WriteString("*" + a.Class.Label() + " · seated since night " + itoa(a.Joined) + "*\n\n")

	b.WriteString("| Gold | Renown | Wins | Losses | Best pot |\n")
	b.WriteString("|---|---|---|---|---|\n")
	b.WriteString("| " + itoa(a.Gold) + " | " + itoa(a.Rep) + " | " + itoa(int64(a.Wins)) +
		" | " + itoa(int64(a.Losses)) + " | " + itoa(a.BestPot) + " |\n\n")

	if a.InCup {
		b.WriteString("### A cup is on the table\n\n")
		b.WriteString("Stake **" + itoa(a.Stake) + "**, pot **" + itoa(a.Pot) + "**, dice: " +
			diceString(a.CupDice) + "\n\n")
	}

	b.WriteString("*[Tip " + a.Name + "](" + actionURL1(pkg, "Tip", "to", a.Name) + ")*\n\n")

	wrote := false
	for i := len(feed) - 1; i >= 0; i-- {
		if feed[i].Author != addr {
			continue
		}
		if !wrote {
			b.WriteString("### From their table\n\n")
			wrote = true
		}
		writePost(&b, pkg, feed[i])
		b.WriteString("\n")
	}
	if !wrote {
		b.WriteString("*Has not said a word yet.*\n")
	}
	return b.String()
}

