package coppermug

import (
	"strings"

	"chain/runtime"
)

// joinErr reports why a wallet cannot take a stool, or "" if it can.
func joinErr(addr, name, class string) string {
	if _, taken := seats[addr]; taken {
		return "you already have a stool here"
	}
	if msg := nameErr(name); msg != "" {
		return msg
	}
	if _, used := byName[strings.ToLower(strings.TrimSpace(name))]; used {
		return "that name is already behind the bar"
	}
	if _, ok := classFromString(class); !ok {
		return "unknown class: pick fighter, rogue, mage or bard"
	}
	return ""
}

// Join claims a stool. One seat per wallet, one wallet per name.
func Join(cur realm, name string, class string) {
	addr, _ := caller(cur)
	if msg := joinErr(addr, name, class); msg != "" {
		panic(msg)
	}

	n := strings.TrimSpace(name)
	c, _ := classFromString(class)
	h := runtime.ChainHeight()
	a := &Adventurer{
		Name:     n,
		Class:    c,
		Gold:     StartingGold,
		Joined:   h,
		LastSeen: h,
	}
	seats[addr] = a
	byName[strings.ToLower(n)] = addr
	touch(addr)

	addPost("join", addr, a, "*"+n+"* the "+c.Label()+" pulls up a stool.")
	emit("Join", "addr", addr, "name", n, "class", c.Label())
}

// sayErr reports whether a seated adventurer may speak at this height.
func sayErr(addr string, height int64) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if a.LastPost != 0 && height-a.LastPost < SayCooldown {
		return "easy there: one tale every few blocks"
	}
	return ""
}

// Say adds a line to the common-room board.
func Say(cur realm, text string) {
	addr, _ := caller(cur)
	h := runtime.ChainHeight()
	if msg := sayErr(addr, h); msg != "" {
		panic(msg)
	}
	msg, errMsg := cleanText(text)
	if errMsg != "" {
		panic(errMsg)
	}

	a := seats[addr]
	a.LastPost = h
	a.LastSeen = h

	addPost("say", addr, a, msg)
	emit("Say", "addr", addr, "id", itoa(nextPostID))
}

// tipCheck resolves a tip, returning the recipient address or a message.
func tipCheck(addr, to string, amount int64) (string, string) {
	a, ok := seats[addr]
	if !ok {
		return "", "no stool yet: call Join first"
	}
	if amount <= 0 {
		return "", "a tip has to be worth something"
	}
	if amount > a.Gold {
		return "", "you cannot tip gold you do not have"
	}
	recipient, ok := byName[strings.ToLower(strings.TrimSpace(to))]
	if !ok {
		return "", "nobody by that name is sitting here"
	}
	if recipient == addr {
		return "", "you cannot tip yourself; the house is watching"
	}
	return recipient, ""
}

// Tip passes gold to another adventurer and earns them a little renown.
func Tip(cur realm, to string, amount int64) int64 {
	addr, _ := caller(cur)
	h := runtime.ChainHeight()

	recipient, msg := tipCheck(addr, to, amount)
	if msg != "" {
		panic(msg)
	}

	a := seats[addr]
	b := seats[recipient]
	a.Gold -= amount
	b.Gold += amount
	if rep := amount / 10; rep > 0 {
		b.Rep += rep
	}
	a.LastSeen = h
	b.LastSeen = h
	touch(addr)
	touch(recipient)

	addPost("tip", addr, a, "slides **"+itoa(amount)+" gold** across the table to *"+b.Name+"*.")
	emit("Tip", "from", addr, "to", recipient, "amount", itoa(amount))
	return a.Gold
}

// cheerCheck finds a post a seated adventurer may cheer, or says why not.
func cheerCheck(addr string, postID int64) (*Post, string) {
	if _, ok := seats[addr]; !ok {
		return nil, "no stool yet: call Join first"
	}

	var target *Post
	for i := len(feed) - 1; i >= 0; i-- {
		if feed[i].ID == postID {
			target = feed[i]
			break
		}
	}
	if target == nil {
		return nil, "that tale has already left the board"
	}
	if target.Author == addr {
		return nil, "you cannot cheer your own tale"
	}
	for _, c := range target.Cheers {
		if c == addr {
			return nil, "you already cheered that one"
		}
	}
	return target, ""
}

// Cheer raises a glass to somebody else's tale. One cheer per wallet per post.
func Cheer(cur realm, postID int64) {
	addr, _ := caller(cur)
	target, msg := cheerCheck(addr, postID)
	if msg != "" {
		panic(msg)
	}

	target.Cheers = append(target.Cheers, addr)
	if author, ok := seats[target.Author]; ok {
		author.Rep++
	}
	a := seats[addr]
	a.LastSeen = runtime.ChainHeight()
	touch(addr)
	emit("Cheer", "addr", addr, "post", itoa(postID))
}

// roundErr reports whether a seated adventurer can buy the room a round.
func roundErr(addr string) string {
	a, ok := seats[addr]
	if !ok {
		return "no stool yet: call Join first"
	}
	if a.Gold < RoundCost {
		return "a round costs 25 gold and you are short"
	}
	return ""
}

// BuyRound spends gold on the room: up to ten recently active neighbours
// each get a small share, and the buyer earns a point of renown.
func BuyRound(cur realm) (int, int64) {
	addr, _ := caller(cur)
	if msg := roundErr(addr); msg != "" {
		panic(msg)
	}

	a := seats[addr]
	a.Gold -= RoundCost
	served := 0
	for i := len(recent) - 1; i >= 0 && served < MaxRoundShare; i-- {
		other := recent[i]
		if other == addr {
			continue
		}
		if b, ok := seats[other]; ok {
			b.Gold += RoundShare
			served++
		}
	}
	a.Rep++
	a.LastSeen = runtime.ChainHeight()
	touch(addr)

	text := "buys the room a round — " + itoa(int64(served)) + " neighbour(s) raise a glass."
	addPost("round", addr, a, text)
	emit("Round", "addr", addr, "served", itoa(int64(served)))
	return served, a.Gold
}

// Package coppermug is an on-chain social tavern for Gno.land.
//
// Adventurers take a seat, talk in the common room, tip each other, and
// play a push-your-luck dice game called the Cup. Every table, every tale
// and every roll lives in realm state, and the whole place renders in
// gnoweb without a single line of JavaScript.
package coppermug

import (
	"chain"
	"chain/runtime"
	"strconv"
	"strings"
)

const (
	// Version is surfaced on the home page.
	Version = "0.1.0"

	// StartingGold is the purse every new adventurer gets.
	StartingGold int64 = 100
	// MinStake is the smallest Cup stake.
	MinStake int64 = 10
	// RoundCost is what it costs to buy the room a round.
	RoundCost int64 = 25
	// RoundShare is what each neighbour receives from a bought round.
	RoundShare int64 = 2
	// MaxRoundShare caps how many neighbours a round can cover.
	MaxRoundShare = 10

	// MaxNameLen and MinNameLen bound adventurer names.
	MaxNameLen = 20
	MinNameLen = 2
	// MaxPostLen bounds a single message, in bytes.
	MaxPostLen = 240
	// SayCooldown is the number of blocks between two messages.
	SayCooldown int64 = 5

	// MaxFeed is how many posts are kept on the board.
	MaxFeed = 100
	// MaxRecent is how many recently active seats are remembered.
	MaxRecent = 24
)

// Class is an adventurer's trade. It flavours the prose and nothing else.
type Class int

const (
	Fighter Class = iota
	Rogue
	Mage
	Bard
	Wanderer // not selectable; the fallback for unknown trades
)

// Label returns the display name of the class.
func (c Class) Label() string {
	switch c {
	case Fighter:
		return "Fighter"
	case Rogue:
		return "Rogue"
	case Mage:
		return "Mage"
	case Bard:
		return "Bard"
	}
	return "Wanderer"
}

// Sigil returns a small glyph for the class.
func (c Class) Sigil() string {
	switch c {
	case Fighter:
		return "⚔️"
	case Rogue:
		return "🗡️"
	case Mage:
		return "🔮"
	case Bard:
		return "🎻"
	}
	return "🥾"
}

// Adventurer is one seat at the tavern, keyed by wallet address.
type Adventurer struct {
	Name     string
	Class    Class
	Gold     int64
	Rep      int64
	Joined   int64
	LastSeen int64
	LastPost int64

	Wins    int
	Losses  int
	BestPot int64

	// Cup state. InCup is true between OpenCup and Hold (or a bust).
	InCup   bool
	Stake   int64
	Pot     int64
	Rolls   int
	CupDice []int
}

// Post is one line on the common-room board.
type Post struct {
	ID     int64
	Author string // address, as a string
	Name   string
	Class  Class
	Text   string
	Kind   string // join, say, tip, round, win, bust
	Height int64
	Cheers []string // addresses that cheered
}

var (
	seats      = map[string]*Adventurer{}
	byName     = map[string]string{}
	feed       []*Post
	recent     []string
	nextPostID int64
	rollSeq    uint64
)

// caller returns the wallet address behind a transaction, and refuses
// calls that arrive through another realm. The Copper Mug is a place for
// people, not contracts.
func caller(cur realm) (string, address) {
	prev := cur.Previous()
	if !prev.IsUserCall() {
		panic("the mug only takes calls from a wallet")
	}
	addr := prev.Address()
	return addr.String(), addr
}

// seatOf returns the caller's seat or panics with a friendly message.
func seatOf(addr string) *Adventurer {
	a, ok := seats[addr]
	if !ok {
		panic("no stool yet: call Join first")
	}
	return a
}

// nameErr trims and checks a display name, returning a message on failure.
func nameErr(name string) string {
	n := strings.TrimSpace(name)
	if len(n) < MinNameLen {
		return "name is too short (2 characters minimum)"
	}
	if len(n) > MaxNameLen {
		return "name is too long (20 characters maximum)"
	}
	for i := 0; i < len(n); i++ {
		c := n[i]
		ok := (c >= 'a' && c <= 'z') ||
			(c >= 'A' && c <= 'Z') ||
			(c >= '0' && c <= '9') ||
			c == ' ' || c == '-' || c == '_'
		if !ok {
			return "names may only use letters, digits, spaces, - and _"
		}
	}
	return ""
}

// classFromString accepts a class name and returns the matching Class.
func classFromString(s string) (Class, bool) {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "fighter":
		return Fighter, true
	case "rogue":
		return Rogue, true
	case "mage":
		return Mage, true
	case "bard":
		return Bard, true
	}
	return Wanderer, false
}

// cleanText flattens a message to one line and caps its length.
func cleanText(text string) (string, string) {
	t := strings.TrimSpace(text)
	t = strings.ReplaceAll(t, "\r", " ")
	t = strings.ReplaceAll(t, "\n", " ")
	t = strings.ReplaceAll(t, "\t", " ")
	if t == "" {
		return "", "say something first"
	}
	for strings.Contains(t, "  ") {
		t = strings.ReplaceAll(t, "  ", " ")
	}
	if len(t) > MaxPostLen {
		return "", "that tale is too long (240 characters maximum)"
	}
	return t, ""
}

// escapeMarkdown neutralises the characters that could turn a message
// into a link or raw HTML. Bold and italics stay, because this is a tavern.
func escapeMarkdown(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '[', ']', '<', '>', '`':
			b.WriteByte('\\')
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

// addPost appends to the board and trims it to MaxFeed.
func addPost(kind, addr string, a *Adventurer, text string) {
	nextPostID++
	p := &Post{
		ID:     nextPostID,
		Author: addr,
		Name:   a.Name,
		Class:  a.Class,
		Text:   text,
		Kind:   kind,
		Height: runtime.ChainHeight(),
	}
	feed = append(feed, p)
	if len(feed) > MaxFeed {
		kept := make([]*Post, MaxFeed)
		copy(kept, feed[len(feed)-MaxFeed:])
		feed = kept
	}
}

// touch remembers a seat as recently active, newest last.
func touch(addr string) {
	out := make([]string, 0, len(recent)+1)
	for _, x := range recent {
		if x != addr {
			out = append(out, x)
		}
	}
	out = append(out, addr)
	if len(out) > MaxRecent {
		out = out[len(out)-MaxRecent:]
	}
	recent = out
}

// rollDie returns a deterministic d6 derived from the chain height, the
// caller and a realm-wide sequence number.
//
// This is house randomness, not consensus-grade randomness: a player who
// can simulate the next block can predict the roll. The Cup is played for
// tavern gold that has no value outside this realm, and a commit-reveal
// version is the natural next step.
func rollDie(addr string) int {
	rollSeq++
	x := uint64(runtime.ChainHeight()) + 0x9E3779B97F4A7C15*rollSeq
	for i := 0; i < len(addr); i++ {
		x ^= uint64(addr[i])
		x *= 0x100000001B3
	}
	x ^= x >> 30
	x *= 0xBF58476D1CE4E5B9
	x ^= x >> 27
	x *= 0x94D049BB133111EB
	x ^= x >> 31
	return int(x%6) + 1
}

// emit is a thin wrapper so event names stay consistent.
func emit(typ string, attrs ...string) {
	chain.Emit("CopperMug"+typ, attrs...)
}

// itoa is a short alias used all over the renderer.
func itoa(n int64) string { return strconv.FormatInt(n, 10) }

package heirloom

import (
	"strconv"
	"strings"

	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/r/nt/grc20reg/v0"
)

type assetInfo struct {
	label    string
	symbol   string
	unit     string
	decimals int
}

type assetInfos map[string]assetInfo

func describe(asset string) assetInfo {
	if asset == gnot {
		return assetInfo{label: "GNOT", symbol: "GNOT", unit: gnot, decimals: 6}
	}
	tok := grc20reg.MustGet(asset)
	return assetInfo{
		label:    sanitize.TableCell(tok.GetName()) + " (`" + asset + "`)",
		symbol:   sanitize.TableCell(tok.GetSymbol()),
		unit:     "units",
		decimals: tok.GetDecimals(),
	}
}

func describeAll(assets []string) assetInfos {
	infos := assetInfos{}
	for _, asset := range assets {
		infos[asset] = describe(asset)
	}
	return infos
}

func (a assetInfo) unitNote() string {
	if a.decimals == 0 {
		return ""
	}
	return "1 " + a.symbol + " = 1" + strings.Repeat("0", a.decimals) + " " + a.unit
}

func (a assetInfo) amount(units int64) string {
	s := strconv.FormatInt(units, 10)
	if a.decimals > 0 {
		if len(s) <= a.decimals {
			s = strings.Repeat("0", a.decimals-len(s)+1) + s
		}
		whole, frac := s[:len(s)-a.decimals], strings.TrimRight(s[len(s)-a.decimals:], "0")
		if frac != "" {
			whole += "." + frac
		}
		s = whole
	}
	return strings.TrimSpace(s + " " + a.symbol)
}

package heirloom

import (
	"chain"
	"chain/banker"

	"gno.land/r/nt/grc20reg/v0"
)

const gnot = "ugnot"

func credit(w *Will, asset string, amount int64) {
	w.add(asset, amount)
	if asset == gnot {
		state.totalGNOT += amount
	}
}

func payOut(cur realm, w *Will, asset string, to address, amount int64) {
	w.take(asset, amount)
	payShare(cur, asset, to, amount)
}

func payShare(cur realm, asset string, to address, amount int64) {
	if asset == gnot {
		state.totalGNOT -= amount
	}
	send(cur, asset, to, amount)
}

func pullToken(cur realm, w *Will, token string, amount int64) {
	grc20reg.TransferFrom(0, cur, token, w.Owner, cur.Address(), amount)
	credit(w, token, amount)
}

func send(cur realm, asset string, to address, amount int64) {
	if asset != gnot {
		grc20reg.Transfer(0, cur, asset, to, amount)
		return
	}
	banker.NewBanker(banker.BankerTypeRealmSend, cur).
		SendCoins(cur.Address(), to, chain.Coins{{gnot, amount}})
}

package heirloom

import (
	"chain/runtime"
	"chain/runtime/unsafe"
	"strconv"
)

func enter(cur realm) address {
	if !cur.IsCurrent() {
		panic("unauthorized realm")
	}
	caller := cur.Previous()
	if caller.IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("this function does not accept coins")
	}
	return caller.Address()
}

func enterWithGNOT(cur realm) (address, int64) {
	if !cur.IsCurrent() {
		panic("unauthorized realm")
	}
	caller := cur.Previous()
	if !caller.IsUserCall() {
		panic("coins must be sent with a direct call (gnokey maketx call or a wallet)")
	}
	sent := unsafe.OriginSend()
	if len(sent) != 1 || sent[0].Denom != gnot || sent[0].Amount <= 0 {
		panic("attach the GNOT to deposit")
	}
	return caller.Address(), sent[0].Amount
}

func touchOwnWill(caller address, id int) *Will {
	w := mustGetWill(id)
	if w.Owner != caller {
		panic("only the owner can change will " + strconv.Itoa(id))
	}
	if w.isReleased() {
		panic("will " + strconv.Itoa(id) + " is already released")
	}
	mustUseMasterKey()
	w.touch()
	return w
}

func enterAsOutsider(cur realm, id int) (*Will, address) {
	caller := enter(cur)
	signer := unsafe.OriginCaller()
	w := mustGetWill(id)
	if (signer == w.Owner || caller == w.Owner) && !w.isReleased() {
		panic("you own this will: call Ping to show a sign of life")
	}
	markAlive(signer)
	return w, signer
}

func mustUseMasterKey() {
	if signedWithSessionKey() {
		panic("sign with your master key: a session key cannot create, change or ping a will")
	}
}

func markAlive(addr address) {
	if signedWithSessionKey() {
		return
	}
	if w := getActiveWill(addr); w != nil {
		w.touch()
	}
}

func signedWithSessionKey() bool {
	_, _, _, isSession := runtime.GetSessionInfo()
	return isSession
}

func mustGetWill(id int) *Will {
	w := getWill(id)
	if w == nil {
		panic("no such will")
	}
	return w
}

package heirloom

import (
	"time"

	"gno.land/p/nt/ufmt/v0"
)

func formatTime(t time.Time) string {
	return t.UTC().Format("2006-01-02 15:04 UTC")
}

func formatTimeFrom(t time.Time) string {
	if m := t.Truncate(time.Minute); m.Before(t) {
		t = m.Add(time.Minute)
	}
	return formatTime(t)
}

func formatDuration(d time.Duration) string {
	days, hours, minutes := int(d/day), int(d%day/time.Hour), int(d%time.Hour/time.Minute)
	switch {
	case days > 0 && hours > 0:
		return ufmt.Sprintf("%dd %dh", days, hours)
	case days > 0:
		return ufmt.Sprintf("%dd", days)
	case hours > 0 && minutes > 0:
		return ufmt.Sprintf("%dh %dm", hours, minutes)
	case hours > 0:
		return ufmt.Sprintf("%dh", hours)
	case minutes > 0:
		return ufmt.Sprintf("%dm", minutes)
	}
	return "<1m"
}

func shortAddr(addr address) string {
	s := addr.String()
	if len(s) <= 14 {
		return s
	}
	return s[:8] + "…" + s[len(s)-4:]
}

package heirloom

import (
	"chain"
	"chain/runtime/unsafe"
	"strconv"
	"time"
)

// CreateWill makes your will and returns its id; one unreleased will at a time.
// heirs: address:percent pairs adding up to 100, at most 10, e.g.
// "g1abc...:70, g1def...:30"; the first heir gets any rounding remainder.
// silence: days without a sign of life, 1 to 3650, e.g. "180".
// successor: gets your admin rights in realms that check Holder, or empty.
// Needs your master key.
func CreateWill(cur realm, heirs, silence string, successor address) int {
	owner := enter(cur)
	mustUseMasterKey()
	if getActiveWill(owner) != nil {
		panic("you already have an unreleased will")
	}
	list, period, next := parseHeirs(heirs, owner), parseSilence(silence), parseSuccessor(successor, owner)
	w := newWill(owner, list, period)
	setSuccessor(w, next)
	emit("WillCreated", w)
	return w.ID
}

// SetHeirs replaces the heirs of your will id, in the CreateWill format.
// Needs your master key.
func SetHeirs(cur realm, id int, heirs string) {
	w := touchOwnWill(enter(cur), id)
	indexHeirs(w, parseHeirs(heirs, w.Owner))
	emit("HeirsChanged", w)
}

// SetSuccessor sets the successor of your will id, or clears it if empty.
// Refused for an address that declined, and once a released will of yours has
// handed your admin rights over. Needs your master key.
func SetSuccessor(cur realm, id int, successor address) {
	w := touchOwnWill(enter(cur), id)
	setSuccessor(w, parseSuccessor(successor, w.Owner))
	emit("SuccessorChanged", w, "successor", w.Successor.String())
}

// SetSilence changes the silence period of your will id, in days, 1 to 3650.
// Needs your master key.
func SetSilence(cur realm, id int, silence string) {
	w := touchOwnWill(enter(cur), id)
	w.Silence = parseSilence(silence)
	emit("SilenceChanged", w)
}

// Ping restarts the silence period of your will id and cancels a release
// request. Needs your master key.
func Ping(cur realm, id int) {
	touchOwnWill(enter(cur), id)
}

// Touch is a sign of life for the account that signed the transaction, unless
// it was signed with a session key. Any realm can call it.
func Touch(cur realm) {
	enter(cur)
	markAlive(unsafe.OriginCaller())
}

// Deposit adds the GNOT sent with this call to your will id. Only a direct call
// from a wallet or gnokey maketx call is accepted. Needs your master key.
func Deposit(cur realm, id int) {
	caller, amount := enterWithGNOT(cur)
	w := touchOwnWill(caller, id)
	credit(w, gnot, amount)
	emit("Deposited", w, amountAttrs(gnot, amount)...)
}

// DepositToken moves amount of a GRC20 token, in its smallest unit, into your
// will id. token is its grc20reg key; approve this realm as a spender first. At
// most 10 different assets per will, GNOT included. Needs your master key.
func DepositToken(cur realm, id int, token string, amount int64) {
	w := touchOwnWill(enter(cur), id)
	mustBePositive(amount)
	pullToken(cur, w, token, amount)
	emit("Deposited", w, amountAttrs(token, amount)...)
}

// Withdraw sends amount of asset ("ugnot" or a token key), in its smallest
// unit, from your will id to you. Needs your master key.
func Withdraw(cur realm, id int, asset string, amount int64) {
	w := touchOwnWill(enter(cur), id)
	mustBePositive(amount)
	payOut(cur, w, asset, w.Owner, amount)
	emit("Withdrawn", w, amountAttrs(asset, amount)...)
}

// Revoke sends everything in your will id to you and deletes the will.
// Needs your master key.
func Revoke(cur realm, id int) {
	w := touchOwnWill(enter(cur), id)
	for _, asset := range w.assets() {
		payOut(cur, w, asset, w.Owner, w.balance(asset))
	}
	removeWill(w)
	emit("WillRevoked", w)
}

// Release asks to release will id once the silence period has passed, or
// releases it once 7 days have passed since that request with no sign of life.
// Returns "requested" or "released". Anyone but the owner can call it.
func Release(cur realm, id int) string {
	w, signer := enterAsOutsider(cur, id)
	if w.isReleased() {
		panic("the will is already released")
	}
	if w.isRequested() {
		mustRelease(w)
	} else {
		mustRequest(w, signer)
	}
	return string(w.status())
}

// Claim sends heir's share of one asset ("ugnot" or a token key) from will id
// to heir, releasing the will first if it can be released. Anyone can call it,
// except the owner before release.
func Claim(cur realm, id int, heir address, asset string) {
	w, _ := enterAsOutsider(cur, id)
	h := mustGetHeir(w, heir)
	if !w.isReleased() {
		mustRelease(w)
	}
	if !w.held.Has(asset) {
		panic("the will held no " + asset + " when it was released")
	}
	if h.hasClaimed(asset) {
		panic(h.Addr.String() + " has already been paid their share of " + asset)
	}
	share := w.shareOf(h, asset)
	if share == 0 {
		panic(h.Addr.String() + "'s share of " + asset + " rounds down to 0")
	}
	payHeir(cur, w, h, asset, share)
}

// ClaimAll sends heir every unpaid share from will id, like Claim for each
// asset. If one transfer fails, nothing is paid; Claim each asset instead.
func ClaimAll(cur realm, id int, heir address) {
	w, _ := enterAsOutsider(cur, id)
	h := mustGetHeir(w, heir)
	if !w.isReleased() {
		mustRelease(w)
	}
	paid := 0
	for _, asset := range w.assets() {
		if share := w.shareOf(h, asset); share > 0 && !h.hasClaimed(asset) {
			payHeir(cur, w, h, asset, share)
			paid++
		}
	}
	if paid == 0 {
		panic(h.Addr.String() + " has nothing left to claim")
	}
}

// Hide takes will id off your page at :u/<your address> if it names you as an
// heir or successor. You stay an heir or successor.
func Hide(cur realm, id int) {
	caller := enter(cur)
	w := mustGetWill(id)
	if !w.names(caller) {
		panic("will " + strconv.Itoa(id) + " does not name you as an heir or successor")
	}
	hideWill(w, caller)
	markAlive(unsafe.OriginCaller())
	emit("WillHidden", w, "by", caller.String())
}

// Unhide puts will id back on your page after Hide.
func Unhide(cur realm, id int) {
	caller := enter(cur)
	w := mustGetWill(id)
	if !w.hiddenFor(caller) {
		panic("will " + strconv.Itoa(id) + " is not hidden from your page")
	}
	unhideWill(w, caller)
	markAlive(unsafe.OriginCaller())
	emit("WillUnhidden", w, "by", caller.String())
}

// Decline removes you as the successor of will id before it is released. The
// owner cannot name you as successor again.
func Decline(cur realm, id int) {
	caller := enter(cur)
	w := mustGetWill(id)
	switch {
	case w.isReleased():
		panic("will " + strconv.Itoa(id) + " is already released; use ReturnRights")
	case w.Successor != caller:
		panic("you are not the successor of will " + strconv.Itoa(id))
	}
	setSuccessor(w, "")
	recordDecline(w.Owner, caller)
	markAlive(unsafe.OriginCaller())
	emit("SuccessionDeclined", w, "by", caller.String())
}

// ReturnRights gives owner back the admin rights that owner's released will
// handed to you. Only that direct successor can call it. Needs your master key.
func ReturnRights(cur realm, owner address) {
	caller := enter(cur)
	mustUseMasterKey()
	h := mustReturnRights(normalize(owner.String()), caller)
	markAlive(unsafe.OriginCaller())
	if w := getWill(h.WillID); w != nil {
		emit("RightsReturned", w, "by", caller.String())
	}
}

// HomeURL returns the gnoweb path of the Heirloom home page.
func HomeURL() string {
	return webPath
}

// WillURL returns the gnoweb path of the page of will id.
func WillURL(id int) string {
	return webPath + ":will/" + strconv.Itoa(id)
}

// UserURL returns the gnoweb path of the Heirloom page of addr.
func UserURL(addr address) string {
	return webPath + ":u/" + addr.String()
}

// Holder returns who holds the admin rights of addr: addr itself, or the end
// of the chain of handovers that starts at addr.
func Holder(addr address) address {
	return holderOf(normalize(addr.String()))
}

// ActiveWill returns the id of the unreleased will of owner, whose status is
// "active", "due" or "requested".
func ActiveWill(owner address) (id int, ok bool) {
	if w := getActiveWill(normalize(owner.String())); w != nil {
		return w.ID, true
	}
	return 0, false
}

// WillInfo returns the owner and status of will id: "active", "due" (a release
// can be requested), "requested" or "released". releaseAt is the next moment
// that status can change, or the release time. ok is false if there is no will.
func WillInfo(id int) (owner address, status string, releaseAt time.Time, ok bool) {
	w := getWill(id)
	if w == nil {
		return "", "", time.Time{}, false
	}
	switch {
	case w.isReleased():
		releaseAt = w.ReleasedAt
	case w.isRequested():
		releaseAt = w.objectionEnds()
	default:
		releaseAt = w.releaseAt()
	}
	return w.Owner, string(w.status()), releaseAt, true
}

func mustGetHeir(w *Will, heir address) *Heir {
	h := w.heir(normalize(heir.String()))
	if h == nil {
		panic(heir.String() + " is not an heir of this will")
	}
	return h
}

func payHeir(cur realm, w *Will, h *Heir, asset string, share int64) {
	h.claimed.Set(asset, true)
	payShare(cur, asset, h.Addr, share)
	emit("Claimed", w, append([]string{"heir", h.Addr.String()}, amountAttrs(asset, share)...)...)
}

func notDue(w *Will) string {
	return "the owner was last seen on " + formatTime(w.LastSeen) + "; anyone but the owner can ask to release the will from " + formatTimeFrom(w.releaseAt())
}

func mustRequest(w *Will, by address) {
	if !w.isDue() {
		panic(notDue(w))
	}
	w.RequestedAt, w.RequestedBy = time.Now(), by
	emit("ReleaseRequested", w, "by", by.String())
}

func mustRelease(w *Will) {
	switch {
	case !w.isRequested() && !w.isDue():
		panic(notDue(w))
	case !w.isRequested():
		panic("nobody has asked to release this will yet: call Release first")
	case time.Now().Before(w.objectionEnds()):
		panic("release was requested on " + formatTime(w.RequestedAt) + "; the owner can object until " + formatTimeFrom(w.objectionEnds()))
	}
	w.release()
	deactivate(w)
	recordRelease(w)
	if recordHandover(w) {
		emit("WillReleased", w, "successor", w.Successor.String())
		return
	}
	emit("WillReleased", w)
}

func mustBePositive(amount int64) {
	if amount <= 0 {
		panic("amount must be positive")
	}
}

func amountAttrs(asset string, amount int64) []string {
	return []string{"asset", asset, "amount", strconv.FormatInt(amount, 10)}
}

func emit(event string, w *Will, attrs ...string) {
	chain.Emit(event, append([]string{"id", strconv.Itoa(w.ID), "owner", w.Owner.String()}, attrs...)...)
}

