package heirloom

import (
	"time"

	"gno.land/p/nt/avl/v0"
)

type handover struct {
	To         address
	WillID     int
	ReturnedAt time.Time
}

type succession struct {
	handovers avl.Tree
	returns   avl.Tree
	declined  avl.Tree
}

type adminOutcome int

const (
	adminPending adminOutcome = iota
	adminHandedOverHere
	adminHandedOverByAnother
	adminReturned
	adminNoSuccessor
	adminStaysWithOwner
)

func handoverOf(owner address) (handover, bool) {
	h, ok := state.rights.handovers.Get(owner.String()).(handover)
	return h, ok
}

func holderOf(addr address) address {
	for {
		h, ok := handoverOf(addr)
		if !ok {
			return addr
		}
		addr = h.To
	}
}

func canHandOver(w *Will) bool {
	if _, done := handoverOf(w.Owner); done || w.Successor == "" {
		return false
	}
	return holderOf(w.Successor) != w.Owner
}

func recordHandover(w *Will) bool {
	if !canHandOver(w) {
		return false
	}
	state.rights.handovers.Set(w.Owner.String(), handover{To: w.Successor, WillID: w.ID})
	return true
}

func mustReturnRights(owner, by address) handover {
	h, ok := handoverOf(owner)
	if !ok || h.To != by {
		panic("you do not hold the admin rights of " + owner.String() + " by a handover from them")
	}
	state.rights.handovers.Remove(owner.String())
	h.ReturnedAt = time.Now()
	state.rights.returns.Set(willKey(h.WillID), h)
	return h
}

func declineKey(owner, successor address) string {
	return owner.String() + "/" + successor.String()
}

func hasDeclined(owner, successor address) bool {
	return state.rights.declined.Has(declineKey(owner, successor))
}

func recordDecline(owner, successor address) {
	state.rights.declined.Set(declineKey(owner, successor), true)
}

func adminOutcomeOf(w *Will) (adminOutcome, handover) {
	if h, ok := state.rights.returns.Get(willKey(w.ID)).(handover); ok {
		return adminReturned, h
	}
	if h, done := handoverOf(w.Owner); done {
		if h.WillID == w.ID {
			return adminHandedOverHere, h
		}
		return adminHandedOverByAnother, h
	}
	if w.Successor == "" {
		return adminNoSuccessor, handover{}
	}
	if w.isReleased() || !canHandOver(w) {
		return adminStaysWithOwner, handover{}
	}
	return adminPending, handover{}
}

package heirloom

import (
	"math/bits"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/ufmt/v0"
)

const (
	MaxHeirs        = 10
	MaxAssets       = 10
	MinSilence      = day
	MaxSilence      = 3650 * day
	ObjectionPeriod = 7 * day

	day = 24 * time.Hour
)

type willStatus string

const (
	statusActive    willStatus = "active"
	statusDue       willStatus = "due"
	statusRequested willStatus = "requested"
	statusReleased  willStatus = "released"
)

type Heir struct {
	Addr    address
	Percent int

	claimed avl.Tree
}

type Will struct {
	ID          int
	Owner       address
	Heirs       []*Heir
	Successor   address
	Silence     time.Duration
	LastSeen    time.Time
	RequestedAt time.Time
	RequestedBy address
	ReleasedAt  time.Time

	held   avl.Tree
	hidden avl.Tree
}

func (w *Will) releaseAt() time.Time {
	return w.LastSeen.Add(w.Silence)
}

func (w *Will) isReleased() bool {
	return !w.ReleasedAt.IsZero()
}

func (w *Will) isDue() bool {
	return !w.isReleased() && !time.Now().Before(w.releaseAt())
}

func (w *Will) isRequested() bool {
	return !w.isReleased() && !w.RequestedAt.IsZero()
}

func (w *Will) objectionEnds() time.Time {
	return w.RequestedAt.Add(ObjectionPeriod)
}

func (w *Will) status() willStatus {
	switch {
	case w.isReleased():
		return statusReleased
	case w.isRequested():
		return statusRequested
	case w.isDue():
		return statusDue
	}
	return statusActive
}

func (w *Will) touch() {
	w.LastSeen = time.Now()
	if w.isRequested() {
		w.RequestedAt, w.RequestedBy = time.Time{}, ""
		emit("ReleaseCancelled", w)
	}
}

func (w *Will) heir(addr address) *Heir {
	for _, h := range w.Heirs {
		if h.Addr == addr {
			return h
		}
	}
	return nil
}

func (w *Will) names(addr address) bool {
	return w.heir(addr) != nil || w.Successor == addr
}

func (w *Will) hiddenFor(addr address) bool {
	return w.hidden.Has(addr.String())
}

func (w *Will) balance(asset string) int64 {
	amount, _ := w.held.Get(asset).(int64)
	return amount
}

func (w *Will) assets() []string {
	return keys(&w.held)
}

func (w *Will) add(asset string, amount int64) {
	if !w.held.Has(asset) && w.held.Size() >= MaxAssets {
		panic(ufmt.Sprintf("a will can hold at most %d different assets", MaxAssets))
	}
	total := w.balance(asset) + amount
	if total < w.balance(asset) {
		panic("the will cannot hold that much of " + asset)
	}
	w.held.Set(asset, total)
}

func (w *Will) take(asset string, amount int64) {
	left := w.balance(asset) - amount
	switch {
	case left < 0:
		panic("the will does not hold that much of " + asset)
	case left == 0:
		w.held.Remove(asset)
	default:
		w.held.Set(asset, left)
	}
}

func (w *Will) release() {
	w.ReleasedAt = time.Now()
}

func (w *Will) shareOf(h *Heir, asset string) int64 {
	total := w.balance(asset)
	if h != w.Heirs[0] {
		return mulDiv(total, int64(h.Percent), 100)
	}
	rest := total
	for _, other := range w.Heirs[1:] {
		rest -= mulDiv(total, int64(other.Percent), 100)
	}
	return rest
}

func (h *Heir) hasClaimed(asset string) bool {
	return h.claimed.Has(asset)
}

func keys(t *avl.Tree) []string {
	var ks []string
	t.Iterate("", "", func(k string, _ any) bool {
		ks = append(ks, k)
		return false
	})
	return ks
}

func mulDiv(a, b, c int64) int64 {
	hi, lo := bits.Mul64(uint64(a), uint64(b))
	quo, _ := bits.Div64(hi, lo, uint64(c))
	return int64(quo)
}

package keepersboard

import (
	"chain/runtime/unsafe"
	"strconv"
	"strings"
	"time"
	"unicode/utf8"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/seqid/v0"

	"gno.land/r/g1klfptn25xf37smf27vqr4g6qlmtwc0lz6y5mcj/heirloom/v1"
)

const (
	maxNoteLen = 280
	shownNotes = 20
)

type note struct {
	ID     int
	Author address
	Text   string
	At     time.Time
}

var (
	founder address
	pkgPath string
	lastID  seqid.ID
	notes   avl.Tree
	pinned  int
)

func init(cur realm) {
	pkgPath = cur.PkgPath()
	founder = address(strings.Split(pkgPath, "/")[2])
	if !founder.IsValid() {
		panic("deploy the board under an address: gno.land/r/<address>/...")
	}
}

// Post adds a note of up to 280 characters to the board and returns its id.
// Anyone can post; it counts as a sign of life on Heirloom for the signer.
func Post(cur realm, text string) int {
	author := callerOf(cur)
	text = strings.Join(strings.Fields(text), " ")
	if text == "" || utf8.RuneCountInString(text) > maxNoteLen {
		panic("a note must be 1 to " + strconv.Itoa(maxNoteLen) + " characters")
	}
	n := &note{ID: int(lastID.Next()), Author: author, Text: text, At: time.Now()}
	notes.Set(noteKey(n.ID), n)
	heirloom.Touch(cross(cur))
	return n.ID
}

// Pin shows note id at the top of the board. Only the keeper can call it.
func Pin(cur realm, id int) {
	mustBeKeeper(cur)
	mustGetNote(id)
	pinned = id
	heirloom.Touch(cross(cur))
}

// Remove deletes note id. Only the keeper can call it.
func Remove(cur realm, id int) {
	mustBeKeeper(cur)
	mustGetNote(id)
	notes.Remove(noteKey(id))
	if pinned == id {
		pinned = 0
	}
	heirloom.Touch(cross(cur))
}

// Keeper returns who runs the board now: heirloom.Holder of the founder.
func Keeper() address {
	return heirloom.Holder(founder)
}

func callerOf(cur realm) address {
	if !cur.IsCurrent() {
		panic("unauthorized realm")
	}
	caller := cur.Previous()
	if caller.IsUserCall() && len(unsafe.OriginSend()) > 0 {
		panic("the board does not accept coins")
	}
	return caller.Address()
}

func mustBeKeeper(cur realm) {
	if callerOf(cur) != Keeper() {
		panic("only the keeper can do this; the keeper is " + Keeper().String())
	}
}

func mustGetNote(id int) *note {
	n, ok := notes.Get(noteKey(id)).(*note)
	if !ok {
		panic("note " + strconv.Itoa(id) + " not found")
	}
	return n
}

func noteKey(id int) string {
	return seqid.ID(id).Binary()
}

package keepersboard

import (
	"chain/runtime"
	"strconv"
	"strings"
	"time"

	"gno.land/p/jeronimoalbi/mdform/v0"
	"gno.land/p/nt/markdown/sanitize/v0"
	"gno.land/p/nt/ufmt/v0"

	"gno.land/r/g1klfptn25xf37smf27vqr4g6qlmtwc0lz6y5mcj/heirloom/v1"
)

// Render shows the board, its keeper and the founder's will on Heirloom.
func Render(path string) string {
	if strings.Trim(path, "/") != "" {
		return "# Page not found\n\n[Back to the board](" + strings.TrimPrefix(pkgPath, runtime.ChainDomain()) + ")\n"
	}
	var b strings.Builder
	b.WriteString("# The Keeper's Board\n\n")
	b.WriteString("A small board that shows [Heirloom](" + heirloom.HomeURL() + ") at work; see [the founder's wills](" + heirloom.UserURL(founder) + "). ")
	b.WriteString("Anyone can post a note. The keeper can pin one note and remove any. ")
	b.WriteString("The keeper is `heirloom.Holder(founder)`: the founder, until a released will of the founder hands the board to a successor. ")
	b.WriteString("Every post, pin and removal is a sign of life on Heirloom for whoever signed it.\n\n")
	b.WriteString(keeperSection())
	b.WriteString(pinnedSection())
	b.WriteString(notesSection())
	b.WriteString(actionsSection())
	return b.String()
}

func keeperSection() string {
	keeper := Keeper()
	var b strings.Builder
	b.WriteString("## Keeper\n\n")
	b.WriteString("| Founder | Keeper now |\n| :--- | :--- |\n")
	b.WriteString("| " + userLink(founder) + " | " + userLink(keeper) + " |\n\n")
	if keeper != founder {
		b.WriteString("The founder's admin rights have passed on, so the board is now run by " + userLink(keeper) + ".\n\n")
		return b.String()
	}
	id, ok := heirloom.ActiveWill(founder)
	if !ok {
		b.WriteString("The founder has no unreleased will on Heirloom, so the board stays with the founder.\n\n")
		return b.String()
	}
	_, status, _, _ := heirloom.WillInfo(id)
	willLink := "[will " + strconv.Itoa(id) + "](" + heirloom.WillURL(id) + ")"
	switch status {
	case "due":
		b.WriteString("The founder's " + willLink + " is due: anyone but the founder can ask to release it now.\n\n")
	case "requested":
		b.WriteString("Someone asked to release the founder's " + willLink + ". Anyone can release it once the objection period ends, and until someone does, any sign of life from the founder cancels the request. The dates are on the will's page.\n\n")
	default:
		b.WriteString("If the founder stays silent for the whole silence period, anyone but the founder can ask to release the founder's " + willLink + ". The date is on the will's page.\n\n")
	}
	return b.String()
}

func pinnedSection() string {
	n, ok := notes.Get(noteKey(pinned)).(*note)
	if pinned == 0 || !ok {
		return ""
	}
	return "## Pinned\n\n" + noteLine(n) + "\n"
}

func notesSection() string {
	if notes.Size() == 0 {
		return "## Notes\n\nNo notes yet.\n\n"
	}
	var b strings.Builder
	b.WriteString("## Notes\n\n")
	count := 0
	notes.ReverseIterate("", "", func(_ string, v any) bool {
		b.WriteString(noteLine(v.(*note)))
		count++
		return count >= shownNotes
	})
	return b.String() + "\n"
}

func actionsSection() string {
	var b strings.Builder
	b.WriteString("## Post a note\n\n")
	b.WriteString(mdform.New("exec", "Post").
		Input("text", "placeholder", "Up to 280 characters", "description", "Note").
		String() + "\n\n")
	b.WriteString("## Keeper only\n\n")
	b.WriteString(mdform.New("exec", "Pin").Input("id", "type", mdform.InputTypeNumber, "description", "Note to pin").String() + "\n\n")
	b.WriteString(mdform.New("exec", "Remove").Input("id", "type", mdform.InputTypeNumber, "description", "Note to remove").String() + "\n")
	return b.String()
}

func noteLine(n *note) string {
	return ufmt.Sprintf("- #%d %s · %s, %s\n", n.ID, sanitize.InlineText(n.Text), userLink(n.Author), formatTime(n.At))
}

func userLink(addr address) string {
	s := addr.String()
	short := s
	if len(s) > 14 {
		short = s[:8] + "…" + s[len(s)-4:]
	}
	return "[" + short + "](" + heirloom.UserURL(addr) + ")"
}

func formatTime(t time.Time) string {
	return t.UTC().Format("2006-01-02 15:04 UTC")
}

package patusworld404_onyx_v2

import (
    "chain/banker"
    "chain/runtime/unsafe"
    "strconv"
    "time"
    "gno.land/p/nt/avl/v0"
    "gno.land/p/nt/grc721/v0"
    "gno.land/p/nt/grc721/metadata/v0"
    "gno.land/p/nt/grc721/royalty/v0"
)

const (
    MaxSupply = 44
    PaidSupply = 36
    FreeSupply = 6
    BatchLimit = 10
    PaidWalletLimit = 10
    WhitelistSeconds int64 = 30 * 60
)

var (
    collection *grc721.Token
    ledger *grc721.PrivateLedger
    nftMeta *metadata.Metadata
    metaLedger *metadata.Ledger
    nftRoyalty *royalty.Royalty
    royaltyLedger *royalty.Ledger
    admin address
    recovery address
    creator address
    treasury address
    opened bool
    paused bool
    openedAt int64
    pausedAt int64
    pauseSeconds int64
    totalMinted int
    paidMinted int
    freeMinted int
    releasedMinted int
    creatorMinted int
    whitelist avl.Tree
    claimed avl.Tree
    paidByWallet avl.Tree
)

func init(cur realm) {
    collection, ledger = grc721.NewToken("ERROR 404: PATUS NOT FOUND", "PATUS404", 0, cur)
    nftMeta, metaLedger = metadata.NewMetadata(ledger)
    nftRoyalty, royaltyLedger = royalty.NewRoyalty(ledger, 500)
    admin = cur.Previous().Address()
    creator = admin
}

func requireAdmin(cur realm) {
    if !cur.Previous().IsUserCall() { panic("direct wallet call only") }
    if cur.Previous().Address() != admin { panic("admin only") }
}

func Configure(cur realm, receiver, recoveryWallet, creatorWallet address) {
    requireAdmin(cur)
    if opened { panic("configuration frozen") }
    if !receiver.IsValid() || !recoveryWallet.IsValid() || !creatorWallet.IsValid() { panic("invalid address") }
    if receiver == admin { panic("treasury must differ from admin") }
    if err := royaltyLedger.SetDefaultRoyalty(receiver, 500); err != nil {
        panic(err)
    }
    treasury, recovery, creator = receiver, recoveryWallet, creatorWallet
}

// ChangeTreasury updates the mint and royalty receiver.
func ChangeTreasury(cur realm, newTreasury address) {
    requireAdmin(cur)
    if !newTreasury.IsValid() { panic("invalid address") }
    if newTreasury == admin { panic("treasury must differ from admin") }
    if err := royaltyLedger.SetDefaultRoyalty(newTreasury, 500); err != nil {
        panic(err)
    }
    treasury = newTreasury
}

// ChangeRecovery updates the recovery wallet.
func ChangeRecovery(cur realm, newRecovery address) {
    requireAdmin(cur)
    if !newRecovery.IsValid() { panic("invalid address") }
    recovery = newRecovery
}

func SetWhitelist(cur realm, wallet address, enabled bool) {
    requireAdmin(cur)
    if opened { panic("whitelist frozen") }
    if !wallet.IsValid() { panic("invalid address") }
    old := whitelist.Get(wallet.String()) != nil
    if enabled && !old {
        if WhitelistCount() >= FreeSupply { panic("6 whitelist slots maximum") }
        whitelist.Set(wallet.String(), true)
    } else if !enabled && old {
        whitelist.Remove(wallet.String())
    }
}

func WhitelistCount() int {
    return whitelist.Size()
}

func OpenMint(cur realm) {
    requireAdmin(cur)
    if opened { panic("already opened") }
    if !treasury.IsValid() || !recovery.IsValid() { panic("configure wallets first") }
    opened = true
    openedAt = time.Now().Unix()
}

func PauseMint(cur realm) {
    requireAdmin(cur)
    if !opened || paused { panic("mint not active") }
    paused = true
    pausedAt = time.Now().Unix()
}

func ResumeMint(cur realm) {
    requireAdmin(cur)
    if !paused { panic("not paused") }
    pauseSeconds += time.Now().Unix() - pausedAt
    pausedAt = 0
    paused = false
}

func ReplaceAdmin(cur realm, newAdmin address) {
    if !cur.Previous().IsUserCall() { panic("direct wallet call only") }
    who := cur.Previous().Address()
    if who != admin && who != recovery { panic("not authorized") }
    if !newAdmin.IsValid() { panic("invalid admin") }
    admin = newAdmin
}

func PriceAt(paidIndex int) int64 {
    if paidIndex < 0 || paidIndex >= PaidSupply { panic("paid supply exceeded") }
    if paidIndex < 4 { return 44 * 1000 }
    if paidIndex < 12 { return 96 * 1000 }
    if paidIndex < 28 { return 144 * 1000 }
    return 404 * 1000
}

func PaidMintedBy(wallet address) int {
    value := paidByWallet.Get(wallet.String())
    if value == nil { return 0 }
    return value.(int)
}

func IsWhitelisted(wallet address) bool { return whitelist.Get(wallet.String()) != nil }
func HasClaimed(wallet address) bool { return claimed.Get(wallet.String()) != nil }

func FreeClaimAvailable(wallet address) bool {
    if !opened || paused || freeMinted >= FreeSupply || !IsWhitelisted(wallet) || HasClaimed(wallet) { return false }
    elapsed := time.Now().Unix() - openedAt - pauseSeconds
    return elapsed < WhitelistSeconds || paidMinted < PaidSupply
}

// WhitelistReleased becomes true only after both expiration conditions.
func WhitelistReleased() bool {
    if !opened || paused || paidMinted < PaidSupply { return false }
    elapsed := time.Now().Unix() - openedAt - pauseSeconds
    return elapsed >= WhitelistSeconds
}

func ReleasedRemaining() int {
    if !WhitelistReleased() { return 0 }
    return FreeSupply - freeMinted - releasedMinted
}

func ReleasedMinted() int { return releasedMinted }

func QuoteMint(wallet address, quantity int) int64 {
    if !opened || paused || quantity < 1 || quantity > BatchLimit { panic("mint unavailable or invalid quantity") }
    if totalMinted + quantity > MaxSupply - (2 - creatorMinted) { panic("creator reserve protected") }

    paidQty := quantity
    if FreeClaimAvailable(wallet) { paidQty-- }

    originalQty := PaidSupply - paidMinted
    if originalQty > paidQty { originalQty = paidQty }

    releasedQty := paidQty - originalQty
    if releasedQty > 0 && (!WhitelistReleased() || releasedQty > ReleasedRemaining()) {
        panic("paid limit exceeded")
    }

    if PaidMintedBy(wallet) + paidQty > PaidWalletLimit { panic("paid limit exceeded") }

    var total int64
    for i := 0; i < originalQty; i++ {
        total += PriceAt(paidMinted+i)
    }
    total += int64(releasedQty) * 404 * 1000
    return total
}

// RoyaltyInfo returns the royalty receiver and amount for a secondary sale.
// The marketplace is responsible for honoring and paying the royalty.
func RoyaltyInfo(id string, salePrice int64) (address, int64, error) {
    return nftRoyalty.RoyaltyInfo(grc721.TokenID(id), salePrice)
}

func mintOne(to address) {
    totalMinted++
    tokenID := strconv.Itoa(totalMinted)
    uri, _ := catalogEntry(tokenID)
    if uri == "" { panic("missing catalog entry") }
    if err := ledger.Mint(to, grc721.TokenID(tokenID)); err != nil { panic(err) }
    if err := metaLedger.SetTokenURI(grc721.TokenID(tokenID), uri); err != nil { panic(err) }
}

// Mint accepts exactly the quoted amount in ugnot. maxAuthorized is a price ceiling,
// not an instruction to send more than the actual quote.
func Mint(cur realm, quantity int, maxAuthorized int64) {
    if !cur.Previous().IsUserCall() { panic("direct wallet call only") }
    caller := cur.Previous().Address()
    cost := QuoteMint(caller, quantity)
    if cost > maxAuthorized { panic("price changed: exceeds authorization") }
    sent := unsafe.OriginSend()
    if cost == 0 {
        if len(sent) != 0 { panic("free mint: no payment required") }
    } else if len(sent) != 1 || sent[0].Denom != "ugnot" || sent[0].Amount != cost {
        panic("send exact quote in ugnot")
    }
    free := FreeClaimAvailable(caller)
    paidQty := quantity
    if free { paidQty-- }

    originalQty := PaidSupply - paidMinted
    if originalQty > paidQty { originalQty = paidQty }
    releasedQty := paidQty - originalQty

    for i := 0; i < quantity; i++ { mintOne(caller) }
    if free { claimed.Set(caller.String(), true); freeMinted++ }

    paidMinted += originalQty
    releasedMinted += releasedQty
    paidByWallet.Set(caller.String(), PaidMintedBy(caller)+paidQty)
    if cost > 0 {
        bank := banker.NewBanker(banker.BankerTypeRealmSend, cur)
        bank.SendCoins(cur.Address(), treasury, sent)
    }
}

func MintCreator(cur realm) {
    if cur.Previous().Address() != creator { panic("creator only") }
    if creatorMinted >= 2 { panic("creator reserve exhausted") }
    if opened && paused { panic("paused") }
    if totalMinted >= MaxSupply { panic("supply exhausted") }
    if len(unsafe.OriginSend()) != 0 { panic("creator mint is free") }
    mintOne(creator)
    creatorMinted++
}

// Name returns the collection name.
func Name() string { return collection.GetName() }

// Symbol returns the collection symbol.
func Symbol() string { return collection.GetSymbol() }

// BalanceOf returns the number of NFTs owned by a wallet.
func BalanceOf(owner address) (int64, error) {
    return collection.BalanceOf(owner)
}

func TotalSupply() int64 { return collection.TotalSupply() }
func PaidMinted() int { return paidMinted }
func FreeMinted() int { return freeMinted }
func CreatorMinted() int { return creatorMinted }
func RemainingSupply() int { return MaxSupply-totalMinted }
func OwnerOf(id string) string {
    owner, err := collection.OwnerOf(grc721.TokenID(id))
    if err != nil { return "" }
    return owner.String()
}
func TokenURI(id string) string {
    uri, err := nftMeta.TokenURI(grc721.TokenID(id))
    if err != nil { return "" }
    return uri
}
func TokenMetadata(id grc721.TokenID) (string, error) {
    _, err := collection.OwnerOf(id)
    if err != nil { return "", err }
    _, json := catalogEntry(string(id))
    return json, nil
}
func TransferFrom(cur realm, from, to address, id string) {
    if err := ledger.TransferFrom(cur.Previous().Address(), from, to, grc721.TokenID(id)); err != nil { panic(err) }
}

// Approve authorizes an address to transfer a specific NFT.
func Approve(cur realm, to address, id string) {
    if err := ledger.CallerTeller().Approve(0, cur, to, grc721.TokenID(id)); err != nil {
        panic(err)
    }
}

// SetApprovalForAll authorizes or revokes an operator for all NFTs owned by the caller.
func SetApprovalForAll(cur realm, operator address, approved bool) {
    if err := ledger.CallerTeller().SetApprovalForAll(0, cur, operator, approved); err != nil {
        panic(err)
    }
}

// GetApproved returns the approved address for a specific NFT.
func GetApproved(id string) (address, error) {
    return collection.GetApproved(grc721.TokenID(id))
}

// IsApprovedForAll checks whether an operator is authorized by an owner.
func IsApprovedForAll(owner, operator address) bool {
    return collection.IsApprovedForAll(owner, operator)
}

// Package heirrealm is a dead-man's-switch inheritance realm for Gno.land.
//
// The problem: a Gno holder dies, loses their keys, or simply disappears,
// and their GNOT is locked forever. No will, no custodian, no recovery.
//
// HeirRealm lets the holder name a beneficiary and a check-in window.
// As long as the holder checks in before the window expires, nothing
// happens. Miss the window and anyone — an incentivised keeper, not a
// trusted custodian — can trigger the release. The keeper earns a small
// fee for doing the work; the rest goes to the beneficiary. The keeper
// can never release early, never change the beneficiary, and never
// touch the funds before the deadline.
//
// Design choices (all documented in README.md):
//   - Denomination is ugnot only (GNOT). One coin type keeps the
//     accounting auditable.
//   - Keeper fee is 2% (200 basis points) of the vault balance at
//     release time. Integer math: fee = balance * 200 / 10000.
//     For balances under 50 ugnot the fee rounds to 0.
//   - Check-in interval must be between 60 seconds (1 minute, so the
//     60-second demo can fast-forward) and 365 days.
//   - CheckIn only works BEFORE the deadline. Once the deadline has
//     passed, the vault is claimable and the owner can no longer
//     rescue it by checking in — that is the whole point of a
//     dead-man's switch.
//   - Cancel (owner refund) only works BEFORE the deadline and only
//     while the vault is still active. After expiry the funds belong
//     to the beneficiary.
//   - The keeper may not be the owner or the beneficiary.
//   - Time is block time: time.Now(), the same timelock primitive
//     used by examples/gno.land/r/demo/defi/atomicswap in gnolang/gno.
//
// Caller authentication follows the atomicswap pattern: payment
// functions require cur.Previous().IsUserCall() and read the attached
// coins from unsafe.OriginSend(). A realm in the middle of a call
// chain cannot fake a payment, because OriginSend describes the
// transaction envelope and IsUserCall rejects non-wallet callers.
//
// Social/voice recovery is intentionally NOT in this MVP. It is listed
// as a future extension in README.md.
package heirrealm

import (
	"chain"
	"chain/banker"
	"chain/runtime/unsafe"
	"strconv"
	"time"

	"gno.land/p/nt/avl/v0"
)

// Denom is the only coin this realm accepts: ugnot (GNOT).
const Denom = "ugnot"

// KeeperFeeBPS is the keeper's cut of a released vault, in basis
// points. 200 bps = 2%.
const KeeperFeeBPS = 200

// MinCheckInIntervalSeconds is the shortest check-in window: 60s.
// It exists so the demo can fast-forward through a full lifecycle
// in about a minute.
const MinCheckInIntervalSeconds = 60

// MaxCheckInIntervalSeconds is the longest check-in window: 365 days.
const MaxCheckInIntervalSeconds = 365 * 24 * 60 * 60

var (
	vaults    avl.Tree // vault ID (string) -> *Vault
	nextVault int
)

// Vault is one inheritance vault.
type Vault struct {
	ID          int
	Owner       address
	Beneficiary address
	Balance     int64 // ugnot held by this vault
	Interval    int64 // check-in window, in seconds
	Deadline    time.Time
	CreatedAt   time.Time
	Released    bool
	Cancelled   bool
	Keeper      address   // set on release; zero address until then
	ReleasedAt  time.Time // zero until released
}

// Status returns a human-readable state for the vault.
func (v Vault) Status() string {
	if v.Released {
		return "released"
	}
	if v.Cancelled {
		return "cancelled"
	}
	if time.Now().After(v.Deadline) {
		return "expired — awaiting keeper"
	}
	return "active"
}

// KeeperFee returns the keeper's cut of the vault balance at release.
func (v Vault) KeeperFee() int64 {
	return v.Balance * KeeperFeeBPS / 10000
}

// BeneficiaryShare returns what the beneficiary receives at release.
func (v Vault) BeneficiaryShare() int64 {
	return v.Balance - v.KeeperFee()
}

// CreateVault opens a vault for beneficiary with a check-in window of
// intervalSeconds. Attach the initial deposit with -send ugnot.
//
// The caller becomes the owner. The beneficiary must not be the owner.
// The deposit must be more than 0 ugnot.
func CreateVault(cur realm, beneficiary address, intervalSeconds int64) int {
	if !cur.Previous().IsUserCall() {
		panic("heirrealm: only direct wallet calls may create a vault")
	}
	owner := cur.Previous().Address()
	if beneficiary == "" {
		panic("heirrealm: beneficiary must not be empty")
	}
	if beneficiary == owner {
		panic("heirrealm: beneficiary must not be the owner")
	}
	if intervalSeconds < MinCheckInIntervalSeconds {
		panic("heirrealm: check-in interval too short (minimum 60 seconds)")
	}
	if intervalSeconds > MaxCheckInIntervalSeconds {
		panic("heirrealm: check-in interval too long (maximum 365 days)")
	}
	sent := unsafe.OriginSend()
	if len(sent) == 0 || sent.AmountOf(Denom) <= 0 {
		panic("heirrealm: attach an initial deposit in ugnot with -send")
	}
	if len(sent) != 1 || sent[0].Denom != Denom {
		panic("heirrealm: only ugnot is accepted")
	}
	amount := sent.AmountOf(Denom)
	now := time.Now()
	nextVault++
	v := &Vault{
		ID:          nextVault,
		Owner:       owner,
		Beneficiary: beneficiary,
		Balance:     amount,
		Interval:    intervalSeconds,
		Deadline:    now.Add(time.Duration(intervalSeconds) * time.Second),
		CreatedAt:   now,
	}
	vaults.Set(strconv.Itoa(v.ID), v)
	return v.ID
}

// Deposit tops up an active vault. Only the owner may deposit, and
// only ugnot is accepted. The check-in timer is NOT reset by a
// deposit — only CheckIn resets it.
func Deposit(cur realm, id int) int64 {
	if !cur.Previous().IsUserCall() {
		panic("heirrealm: only direct wallet calls may deposit")
	}
	v := mustGetVault(id)
	caller := cur.Previous().Address()
	if caller != v.Owner {
		panic("heirrealm: only the vault owner may deposit")
	}
	requireActive(v)
	sent := unsafe.OriginSend()
	if len(sent) == 0 || sent.AmountOf(Denom) <= 0 {
		panic("heirrealm: attach ugnot with -send")
	}
	if len(sent) != 1 || sent[0].Denom != Denom {
		panic("heirrealm: only ugnot is accepted")
	}
	v.Balance += sent.AmountOf(Denom)
	vaults.Set(strconv.Itoa(v.ID), v)
	return v.Balance
}

// CheckIn resets the vault's deadline to now + the check-in interval.
// Only the owner may check in, only while the vault is active, and
// only BEFORE the deadline has passed. After the deadline the vault
// is claimable and checking in can no longer save it.
func CheckIn(cur realm, id int) time.Time {
	v := mustGetVault(id)
	caller := cur.Previous().Address()
	if caller != v.Owner {
		panic("heirrealm: only the vault owner may check in")
	}
	requireActive(v)
	if !time.Now().Before(v.Deadline) {
		panic("heirrealm: deadline has passed, check-in is too late")
	}
	v.Deadline = time.Now().Add(time.Duration(v.Interval) * time.Second)
	vaults.Set(strconv.Itoa(v.ID), v)
	return v.Deadline
}

// TriggerRelease releases an expired vault. Anyone may call it — that
// is the keeper's job — but the keeper may not be the owner or the
// beneficiary, and the deadline must have passed. The keeper earns
// 2% of the balance; the beneficiary receives the remaining 98%.
// The keeper is paid for doing the work, never a custodian: they
// cannot release early, change the beneficiary, or touch the funds
// before expiry.
func TriggerRelease(cur realm, id int) (beneficiaryShare int64, keeperFee int64) {
	v := mustGetVault(id)
	keeper := cur.Previous().Address()
	if keeper == "" {
		panic("heirrealm: keeper must not be empty")
	}
	if keeper == v.Owner {
		panic("heirrealm: the owner cannot be the keeper")
	}
	if keeper == v.Beneficiary {
		panic("heirrealm: the beneficiary cannot be the keeper")
	}
	requireActive(v)
	if !time.Now().After(v.Deadline) {
		panic("heirrealm: vault has not expired yet")
	}
	keeperFee = v.KeeperFee()
	beneficiaryShare = v.BeneficiaryShare()
	realmAddr := cur.Address()
	banker_ := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if keeperFee > 0 {
		banker_.SendCoins(realmAddr, keeper, chain.Coins{chain.NewCoin(Denom, keeperFee)})
	}
	if beneficiaryShare > 0 {
		banker_.SendCoins(realmAddr, v.Beneficiary, chain.Coins{chain.NewCoin(Denom, beneficiaryShare)})
	}
	v.Released = true
	v.Keeper = keeper
	v.ReleasedAt = time.Now()
	vaults.Set(strconv.Itoa(v.ID), v)
	return beneficiaryShare, keeperFee
}

// Cancel closes an active vault and refunds the full balance to the
// owner. Only the owner may cancel, and only BEFORE the deadline.
// After expiry the funds belong to the beneficiary and the owner
// can no longer claw them back.
func Cancel(cur realm, id int) int64 {
	v := mustGetVault(id)
	caller := cur.Previous().Address()
	if caller != v.Owner {
		panic("heirrealm: only the vault owner may cancel")
	}
	requireActive(v)
	if !time.Now().Before(v.Deadline) {
		panic("heirrealm: deadline has passed, vault can no longer be cancelled")
	}
	refund := v.Balance
	realmAddr := cur.Address()
	banker_ := banker.NewBanker(banker.BankerTypeRealmSend, cur)
	if refund > 0 {
		banker_.SendCoins(realmAddr, v.Owner, chain.Coins{chain.NewCoin(Denom, refund)})
	}
	v.Balance = 0
	v.Cancelled = true
	vaults.Set(strconv.Itoa(v.ID), v)
	return refund
}

// GetVault returns a copy of the vault with the given ID.
// Read-only: callable as a query, no transaction needed.
func GetVault(id int) Vault {
	return *mustGetVault(id)
}

// VaultCount returns the number of vaults ever created.
func VaultCount() int {
	return nextVault
}

// requireActive panics unless the vault is still live.
func requireActive(v *Vault) {
	if v.Released {
		panic("heirrealm: vault already released")
	}
	if v.Cancelled {
		panic("heirrealm: vault already cancelled")
	}
}

// mustGetVault loads a vault by ID or panics.
func mustGetVault(id int) *Vault {
	v := vaults.Get(strconv.Itoa(id))
	if v == nil {
		panic("heirrealm: unknown vault ID")
	}
	return v.(*Vault)
}

package heirrealm

import (
	"chain"
	"chain/banker"
	"strings"
	"testing"
	"time"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

func resetTestState() {
	vaults = avl.Tree{}
	nextVault = 0
}

const testPkgPath = "gno.land/r/g1pzw2mc795ahjumtmkxjyxhz0awklc3apyfpw9e/heirrealm"

// makeVault creates a vault owned by owner for beneficiary with the
// given interval and deposit, funded on the realm so payouts work.
func makeVault(cur realm, t *testing.T, owner, beneficiary address, interval, deposit int64) int {
	pkgAddr := chain.PackageAddress(testPkgPath)
	testing.SetRealm(testing.NewUserRealm(owner))
	testing.SetOriginSend(chain.Coins{{Denom: Denom, Amount: deposit}})
	testing.IssueCoins(pkgAddr, chain.Coins{{Denom: Denom, Amount: deposit}})
	return CreateVault(cross(cur), beneficiary, interval)
}

func TestCreateVault(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner1")
	beneficiary := testutils.TestAddress("beneficiary1")
	id := makeVault(cur, t, owner, beneficiary, 3600, 1000)
	uassert.Equal(t, 1, id)
	uassert.Equal(t, 1, VaultCount())

	v := GetVault(id)
	uassert.Equal(t, owner, v.Owner)
	uassert.Equal(t, beneficiary, v.Beneficiary)
	uassert.Equal(t, int64(1000), v.Balance)
	uassert.Equal(t, int64(3600), v.Interval)
	uassert.Equal(t, "active", v.Status())
	uassert.False(t, v.Released)
	uassert.False(t, v.Cancelled)
	// Deadline is now + 3600s. In tests time.Now() is fixed, so the
	// deadline must be exactly 1h after the fixed test time.
	uassert.True(t, v.Deadline.Equal(time.Now().Add(3600*time.Second)))
	uassert.Equal(t, int64(20), v.KeeperFee()) // 2% of 1000
	uassert.Equal(t, int64(980), v.BeneficiaryShare())
}

func TestCreateVaultGuards(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner2")
	other := testutils.TestAddress("other2")

	// Beneficiary must not be the owner.
	testing.SetRealm(testing.NewUserRealm(owner))
	testing.SetOriginSend(chain.Coins{{Denom: Denom, Amount: 1000}})
	uassert.AbortsContains(t, cur, "must not be the owner", func() {
		CreateVault(cross(cur), owner, 3600)
	})

	// Interval too short (under 60s).
	uassert.AbortsContains(t, cur, "too short", func() {
		CreateVault(cross(cur), other, 30)
	})

	// Interval too long (over 365 days).
	uassert.AbortsContains(t, cur, "too long", func() {
		CreateVault(cross(cur), other, MaxCheckInIntervalSeconds+1)
	})

	// Zero deposit.
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsContains(t, cur, "initial deposit", func() {
		CreateVault(cross(cur), other, 3600)
	})

	// No vaults were created by the failed calls.
	uassert.Equal(t, 0, VaultCount())
}

func TestDeposit(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner3")
	beneficiary := testutils.TestAddress("beneficiary3")
	other := testutils.TestAddress("other3")
	id := makeVault(cur, t, owner, beneficiary, 3600, 1000)

	// Owner tops up by 500.
	testing.SetRealm(testing.NewUserRealm(owner))
	testing.SetOriginSend(chain.Coins{{Denom: Denom, Amount: 500}})
	balance := Deposit(cross(cur), id)
	uassert.Equal(t, int64(1500), balance)
	uassert.Equal(t, int64(1500), GetVault(id).Balance)

	// A non-owner cannot deposit.
	testing.SetRealm(testing.NewUserRealm(other))
	testing.SetOriginSend(chain.Coins{{Denom: Denom, Amount: 500}})
	uassert.AbortsContains(t, cur, "only the vault owner may deposit", func() {
		Deposit(cross(cur), id)
	})
	uassert.Equal(t, int64(1500), GetVault(id).Balance)

	// A zero deposit fails.
	testing.SetRealm(testing.NewUserRealm(owner))
	testing.SetOriginSend(chain.Coins{})
	uassert.AbortsContains(t, cur, "attach ugnot", func() {
		Deposit(cross(cur), id)
	})
}

func TestCheckInResetsTimer(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner4")
	beneficiary := testutils.TestAddress("beneficiary4")
	other := testutils.TestAddress("other4")
	id := makeVault(cur, t, owner, beneficiary, 3600, 1000)

	// Simulate a nearly-expired vault, then check in.
	v := mustGetVault(id)
	v.Deadline = time.Now().Add(10 * time.Second)
	vaults.Set("1", v)
	oldDeadline := v.Deadline

	testing.SetRealm(testing.NewUserRealm(owner))
	newDeadline := CheckIn(cross(cur), id)
	uassert.True(t, newDeadline.After(oldDeadline))
	uassert.True(t, newDeadline.Equal(time.Now().Add(3600*time.Second)))
	uassert.Equal(t, "active", GetVault(id).Status())

	// A non-owner cannot check in.
	testing.SetRealm(testing.NewUserRealm(other))
	uassert.AbortsContains(t, cur, "only the vault owner may check in", func() {
		CheckIn(cross(cur), id)
	})

	// Checking in after the deadline is too late.
	v = mustGetVault(id)
	v.Deadline = time.Now().Add(-1 * time.Hour)
	vaults.Set("1", v)
	testing.SetRealm(testing.NewUserRealm(owner))
	uassert.AbortsContains(t, cur, "too late", func() {
		CheckIn(cross(cur), id)
	})
}

func TestEarlyReleaseFails(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner5")
	beneficiary := testutils.TestAddress("beneficiary5")
	keeper := testutils.TestAddress("keeper5")
	id := makeVault(cur, t, owner, beneficiary, 3600, 1000)

	testing.SetRealm(testing.NewUserRealm(keeper))
	uassert.AbortsContains(t, cur, "has not expired yet", func() {
		TriggerRelease(cross(cur), id)
	})
	uassert.Equal(t, "active", GetVault(id).Status())
	uassert.False(t, GetVault(id).Released)
}

func TestExpiredReleaseSplits(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner6")
	beneficiary := testutils.TestAddress("beneficiary6")
	keeper := testutils.TestAddress("keeper6")
	id := makeVault(cur, t, owner, beneficiary, 3600, 1000)

	// Fast-forward: move the deadline into the past.
	v := mustGetVault(id)
	v.Deadline = time.Now().Add(-1 * time.Hour)
	vaults.Set("1", v)
	uassert.Equal(t, "expired — awaiting keeper", GetVault(id).Status())

	testing.SetRealm(testing.NewUserRealm(keeper))
	share, fee := TriggerRelease(cross(cur), id)
	uassert.Equal(t, int64(980), share)
	uassert.Equal(t, int64(20), fee)

	// Balances on chain: beneficiary 98%, keeper 2%.
	banker_ := banker.NewReadonlyBanker()
	uassert.Equal(t, int64(980), banker_.GetCoin(beneficiary, Denom))
	uassert.Equal(t, int64(20), banker_.GetCoin(keeper, Denom))

	// Vault is marked released, with the keeper recorded.
	released := GetVault(id)
	uassert.True(t, released.Released)
	uassert.Equal(t, keeper, released.Keeper)
	uassert.Equal(t, "released", released.Status())

	// Double-release fails.
	uassert.AbortsContains(t, cur, "already released", func() {
		TriggerRelease(cross(cur), id)
	})
	// Check-in after release fails too.
	testing.SetRealm(testing.NewUserRealm(owner))
	uassert.AbortsContains(t, cur, "already released", func() {
		CheckIn(cross(cur), id)
	})
}

func TestKeeperCannotBeOwnerOrBeneficiary(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner7")
	beneficiary := testutils.TestAddress("beneficiary7")
	id := makeVault(cur, t, owner, beneficiary, 3600, 1000)

	v := mustGetVault(id)
	v.Deadline = time.Now().Add(-1 * time.Hour)
	vaults.Set("1", v)

	testing.SetRealm(testing.NewUserRealm(owner))
	uassert.AbortsContains(t, cur, "owner cannot be the keeper", func() {
		TriggerRelease(cross(cur), id)
	})
	testing.SetRealm(testing.NewUserRealm(beneficiary))
	uassert.AbortsContains(t, cur, "beneficiary cannot be the keeper", func() {
		TriggerRelease(cross(cur), id)
	})
	uassert.False(t, GetVault(id).Released)
}

func TestCancelRefunds(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner8")
	beneficiary := testutils.TestAddress("beneficiary8")
	other := testutils.TestAddress("other8")
	id := makeVault(cur, t, owner, beneficiary, 3600, 500)

	// A non-owner cannot cancel.
	testing.SetRealm(testing.NewUserRealm(other))
	uassert.AbortsContains(t, cur, "only the vault owner may cancel", func() {
		Cancel(cross(cur), id)
	})

	// Owner cancels before expiry: full refund.
	testing.SetRealm(testing.NewUserRealm(owner))
	refund := Cancel(cross(cur), id)
	uassert.Equal(t, int64(500), refund)
	banker_ := banker.NewReadonlyBanker()
	uassert.Equal(t, int64(500), banker_.GetCoin(owner, Denom))
	cancelled := GetVault(id)
	uassert.True(t, cancelled.Cancelled)
	uassert.Equal(t, int64(0), cancelled.Balance)
	uassert.Equal(t, "cancelled", cancelled.Status())

	// Nothing more can happen to a cancelled vault.
	// (Call as a third party: as the owner, TriggerRelease would
	// abort on the keeper check first, which is also correct.)
	testing.SetRealm(testing.NewUserRealm(other))
	uassert.AbortsContains(t, cur, "already cancelled", func() {
		TriggerRelease(cross(cur), id)
	})
	testing.SetRealm(testing.NewUserRealm(owner))
	uassert.AbortsContains(t, cur, "already cancelled", func() {
		CheckIn(cross(cur), id)
	})

	// Cancelling after the deadline is refused: after expiry the
	// funds belong to the beneficiary.
	id2 := makeVault(cur, t, owner, beneficiary, 3600, 500)
	v := mustGetVault(id2)
	v.Deadline = time.Now().Add(-1 * time.Hour)
	vaults.Set("2", v)
	uassert.AbortsContains(t, cur, "no longer be cancelled", func() {
		Cancel(cross(cur), id2)
	})
}

func TestRender(cur realm, t *testing.T) {
	defer resetTestState()
	owner := testutils.TestAddress("owner9")
	beneficiary := testutils.TestAddress("beneficiary9")
	id := makeVault(cur, t, owner, beneficiary, 3600, 1000)

	home := Render("")
	uassert.True(t, strings.Contains(home, "# HeirRealm"))
	uassert.True(t, strings.Contains(home, "Vault #1"))
	uassert.True(t, strings.Contains(home, "active"))

	detail := Render("1")
	uassert.True(t, strings.Contains(detail, "Vault #1"))
	uassert.True(t, strings.Contains(detail, "1000 ugnot"))

	uassert.Equal(t, "# HeirRealm\n\nUnknown vault.", Render("999"))
	_ = id
}

package heirrealm

import (
	"strconv"
	"time"

	"gno.land/p/nt/ufmt/v0"
)

// Render is the gnoweb homepage for the realm. It lists every vault
// with its owner, beneficiary, balance, deadline and status, plus a
// short how-to. A single vault can be viewed at /<id>.
func Render(path string) string {
	if path != "" {
		id, err := strconv.Atoi(path)
		if err != nil {
			return "# HeirRealm\n\nUnknown vault."
		}
		v := vaults.Get(strconv.Itoa(id))
		if v == nil {
			return "# HeirRealm\n\nUnknown vault."
		}
		return renderVault(v.(*Vault))
	}
	out := "# HeirRealm — dead-man's switch for Gno\n\n"
	out += "Name a beneficiary and a check-in window. Check in before the window ends and nothing happens. "
	out += "Miss the window and any keeper can trigger the release: the beneficiary gets 98%, the keeper earns a 2% fee. "
	out += "No custodian, no will, no trusted third party.\n\n"
	out += "## Vaults\n\n"
	if nextVault == 0 {
		out += "No vaults yet. Create one with `CreateVault(beneficiary, intervalSeconds)` and attach ugnot with `-send`.\n"
		return out
	}
	for i := 1; i <= nextVault; i++ {
		v := vaults.Get(strconv.Itoa(i))
		if v == nil {
			continue
		}
		vv := v.(*Vault)
		out += ufmt.Sprintf("- Vault #%d — %s — balance %d ugnot — deadline %s\n",
			vv.ID, vv.Status(), vv.Balance, vv.Deadline.Format(time.RFC3339))
	}
	out += "\n## How it works\n\n"
	out += "1. `CreateVault(beneficiary, intervalSeconds)` + `-send` ugnot — you are the owner.\n"
	out += "2. `CheckIn(vaultID)` before the deadline to reset the timer.\n"
	out += "3. `Deposit(vaultID)` + `-send` ugnot to top up (owner only, timer unchanged).\n"
	out += "4. After the deadline, anyone except the owner or beneficiary calls `TriggerRelease(vaultID)` and earns 2%.\n"
	out += "5. `Cancel(vaultID)` refunds the owner in full — owner only, before the deadline.\n"
	return out
}

func renderVault(v *Vault) string {
	out := ufmt.Sprintf("# HeirRealm — Vault #%d\n\n", v.ID)
	out += ufmt.Sprintf("- Status: %s\n", v.Status())
	out += ufmt.Sprintf("- Owner: %s\n", v.Owner)
	out += ufmt.Sprintf("- Beneficiary: %s\n", v.Beneficiary)
	out += ufmt.Sprintf("- Balance: %d ugnot\n", v.Balance)
	out += ufmt.Sprintf("- Check-in interval: %d seconds\n", v.Interval)
	out += ufmt.Sprintf("- Deadline: %s\n", v.Deadline.Format(time.RFC3339))
	out += ufmt.Sprintf("- Keeper fee at release: %d ugnot (2%%)\n", v.KeeperFee())
	out += ufmt.Sprintf("- Beneficiary share at release: %d ugnot (98%%)\n", v.BeneficiaryShare())
	if v.Released {
		out += ufmt.Sprintf("- Released by keeper: %s at %s\n", v.Keeper, v.ReleasedAt.Format(time.RFC3339))
	}
	return out
}
